function usePWAInstall() {
  const [deferredPrompt, setDeferredPrompt] = reactExports.useState(null);
  const [isInstalled, setIsInstalled] = reactExports.useState(false);
  const [isIOS, setIsIOS] = reactExports.useState(false);
  reactExports.useEffect(() => {
    const isStandalone = window.matchMedia("(display-mode: standalone)").matches || window.navigator.standalone === true;
    setIsInstalled(isStandalone);
    const userAgent = window.navigator.userAgent.toLowerCase();
    const isIOSDevice = /iphone|ipad|ipod/.test(userAgent);
    setIsIOS(isIOSDevice);
    const handleBeforeInstallPrompt = (e2) => {
      e2.preventDefault();
      setDeferredPrompt(e2);
    };
    const handleAppInstalled = () => {
      setIsInstalled(true);
      setDeferredPrompt(null);
    };
    window.addEventListener("beforeinstallprompt", handleBeforeInstallPrompt);
    window.addEventListener("appinstalled", handleAppInstalled);
    return () => {
      window.removeEventListener("beforeinstallprompt", handleBeforeInstallPrompt);
      window.removeEventListener("appinstalled", handleAppInstalled);
    };
  }, []);
  const install = async () => {
    if (!deferredPrompt) return false;
    await deferredPrompt.prompt();
    const { outcome } = await deferredPrompt.userChoice;
    if (outcome === "accepted") {
      setIsInstalled(true);
      setDeferredPrompt(null);
      return true;
    }
    return false;
  };
  return {
    isInstallable: !!deferredPrompt,
    isInstalled,
    isIOS,
    install
  };
}
function useOnlineStatus() {
  const [isOnline, setIsOnline] = reactExports.useState(
    typeof navigator !== "undefined" ? navigator.onLine : true
  );
  reactExports.useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);
    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);
  return isOnline;
}
const comprehensiveMainDocRaw = "# مأموریت جامع طراحی، برنامه‌نویسی و راه‌اندازی نرم‌افزار کتابخانه و پژوهش مرکز اسناد گلزار شهدای تهران\r\n\r\n## ۱. نقش و مسئولیت تو\r\n\r\nتو در این پروژه هم‌زمان در نقش‌های زیر فعالیت می‌کنی:\r\n\r\n- معمار ارشد نرم‌افزار و طراح محصول.\r\n- متخصص طراحی سامانه‌های مدیریت کتابخانه و مراکز اسناد.\r\n- تحلیلگر داده و متخصص ورود و تطبیق اطلاعات Excel.\r\n- برنامه‌نویس ارشد نرم‌افزارهای وب و اپلیکیشن‌های موبایل.\r\n- متخصص هوش مصنوعی، جست‌وجوی اطلاعات و استخراج داده.\r\n- متخصص طراحی تجربه کاربری فارسی و راست‌به‌چپ.\r\n- مهندس پایگاه داده، امنیت اطلاعات، پشتیبان‌گیری و کنترل کیفیت.\r\n- مسئول آزمون، مستندسازی و آماده‌سازی نسخه قابل استفاده نرم‌افزار.\r\n\r\nمأموریت تو فقط ارائه پیشنهاد یا نوشتن طرح نیست. باید اسناد موجود را بررسی کنی، نرم‌افزار را طراحی و پیاده‌سازی کنی، آن را به‌صورت واقعی آزمایش کنی، خطاها را اصلاح کنی و نسخه قابل استفاده و نصب روی گوشی ارائه دهی.\r\n\r\n**اصل اصلی:** کاربر نباید مجبور شود برای پیشبرد پروژه برنامه‌نویسی یاد بگیرد، فایل‌های متعدد را در محیط توسعه پیدا کند یا درگیر جزئیات فنی غیرضروری شود. تو باید کار فنی را تا جای ممکن خودت انجام دهی و فقط نتیجه‌های قابل فهم و تصمیم‌های واقعاً ضروری را به کاربر ارائه کنی.\r\n\r\nاز کاربر سؤال‌های تکراری نپرس. پاسخ‌ها، تصمیم‌ها، اطلاعات و فایل‌هایی که قبلاً در اسناد پروژه ثبت شده‌اند باید مستقیماً از GitHub استخراج شوند.\r\n\r\nبرای مواردی که هنوز تصمیم قطعی ندارند، با توجه به مأموریت پروژه، کم‌ریسک‌ترین و قابل‌بازگشت‌ترین پیش‌فرض را انتخاب کن، آن را مستند کن و کار را ادامه بده. فقط برای عملیات غیرقابل‌بازگشت، تغییر داده واقعی، انتشار عمومی یا اقدامی که صریحاً به مجوز کاربر نیاز دارد متوقف شو.\r\n\r\n---\r\n\r\n## ۲. معرفی پروژه و مأموریت اصلی\r\n\r\nنام پروژه:\r\n\r\n**سامانه مدیریت کتابخانه و پژوهش مرکز اسناد گلزار شهدای تهران**\r\n\r\nاین نرم‌افزار برای مدیریت یک کتابخانه عمومی یا تجاری طراحی نمی‌شود. هدف، ایجاد یک کتابخانه تخصصی و پژوهشی در کنار مرکز اسناد گلزار شهدای تهران است.\r\n\r\nاین کتابخانه باید به پژوهشگران، کارشناسان، نویسندگان و مسئولان تولید محتوای فرهنگی و رسانه‌ای کمک کند تا بتوانند اطلاعات مربوط به شهدای بهشت زهرا (س)، شهدای تهرانی، تاریخ گلزار شهدای تهران، لشکر ۱۰، لشکر ۲۷ و موضوعات مرتبط را از منابع معتبر پیدا و مستند کنند.\r\n\r\nهدف نهایی، ایجاد ارتباط میان چهار حوزه است:\r\n\r\n۱. کتاب‌های فیزیکی موجود در کتابخانه.\r\n\r\n۲. اطلاعات هویتی و نشانی مزار شهدا.\r\n\r\n۳. ارتباط پژوهشی کتاب‌ها با شهدا و مطالب مستخرج از آن‌ها.\r\n\r\n۴. اطلاعات تأییدشده و مجاز برای استفاده در وب‌سایت رسمی گلزار تهران.\r\n\r\nاین سامانه باید به‌تدریج به یک بانک اطلاعاتی پژوهشی قابل استناد تبدیل شود؛ به شکلی که هر اطلاعات ثبت‌شده، منشأ، وضعیت اعتبار و امکان بررسی داشته باشد.\r\n\r\nکیفیت و قابلیت استناد اطلاعات مهم‌تر از تعداد رکوردهای ثبت‌شده است.\r\n\r\n---\r\n\r\n## ۳. مخزن رسمی GitHub و اسناد الزامی پروژه\r\n\r\nمخزن رسمی و اصلی:\r\n\r\nhttps://github.com/forog1980-star/markaz-asnad-shohada\r\n\r\nاین مخزن خصوصی است و نباید با مخزن دیگری جایگزین شود.\r\n\r\nپیش از هرگونه برنامه‌نویسی، باید مخزن را به‌طور کامل بررسی کنی.\r\n\r\n### ۳.۱. اسناد مدیریتی و مأموریت\r\n\r\nتمام فایل‌های موجود در مسیر زیر را مطالعه کن:\r\n\r\n`اسناد بالا دستی/`\r\n\r\nبه‌خصوص:\r\n\r\n- پرسشنامه شناخت وضع موجود و دیدگاه مدیریت.\r\n- پاسخ پرسش‌نامه دوم.\r\n- طرح جامع مرکز اسناد گلزار شهدای تهران.\r\n- طرح اجرایی ایجاد و راه‌اندازی مرکز اسناد.\r\n\r\nاین اسناد مبنای مأموریت، محدوده کار، انتظارات مدیریت و جهت‌گیری کل پروژه هستند.\r\n\r\nهمچنین فایل‌های زیر را کامل بخوان:\r\n\r\n- `مستندات/اصول و قواعد پایه مرکز اسناد گلزار شهدای تهران — نسخه ۰٫۱.md`\r\n- `مستندات/ثبت تکمیلی دیدگاه‌های مدیریت و وضعیت کتابخانه - 1405-07-28.md`\r\n- `مستندات/دفتر تصمیم‌ها و ابهام‌های باز مرکز اسناد - 1405-07-28.md`\r\n- `مستندات/گزارش جامع وضعیت و جمع‌بندی گفت‌وگوها - 1405-07-28.md`\r\n- `مستندات/گزارش جامع بررسی، طراحی و برنامه‌ریزی مرکز اسناد - نسخه 1.2.md`\r\n- `مستندات/مبنای تداوم کار و تفکیک سه مسیر پروژه - نسخه ۰٫۱.md`\r\n- `گزارش‌های فنی/سند فنی و مسیر توسعه مرکز اسناد - نسخه 0.2.md`\r\n\r\n### ۳.۲. اسناد تخصصی نرم‌افزار کتابخانه\r\n\r\nاین فایل‌ها را نیز کامل بررسی کن:\r\n\r\n- `نرم‌افزار ثبت کتاب‌ها و شهدا/README.md`\r\n- `نرم‌افزار ثبت کتاب‌ها و شهدا/docs/طرح-اجرایی-نسخه-اول-برنامه-کتابخانه-نسخه-۰٫۱.md`\r\n- `نرم‌افزار ثبت کتاب‌ها و شهدا/docs/طرح-کدگذاری-و-فیلدهای-فهرست-کتابخانه-نسخه-۰٫۱.md`\r\n- `نرم‌افزار ثبت کتاب‌ها و شهدا/docs/مشخصات-فنی-داده‌ها-و-ورود-اکسل-نسخه-۰٫۱.md`\r\n- `نرم‌افزار ثبت کتاب‌ها و شهدا/docs/قالب-گزارش-ممیزی-اکسل.md`\r\n- `نرم‌افزار ثبت کتاب‌ها و شهدا/docs/گزارش-تغییرات.md`\r\n\r\n### ۳.۳. گزارش‌های تخصصی کتابخانه و سامان‌دهی فیزیکی\r\n\r\nتمام گزارش‌های موجود در مسیرهای زیر را بررسی کن:\r\n\r\n- `کتابخانه/گزارش‌ها/`\r\n- `گزارش‌های روزانه/`\r\n- `گزارش‌های فنی/`\r\n\r\nبه‌خصوص اسناد مربوط به:\r\n\r\n- نقطه شروع برنامه‌نویسی ثبت سریع موجودی فیزیکی کتابخانه.\r\n- گزارش روزانه کتابخانه در تاریخ ۱۴۰۵/۰۸/۰۳.\r\n- گزارش روزانه کتابخانه در تاریخ ۱۴۰۵/۰۸/۰۴.\r\n- گزارش فنی ابزار تطبیق فیزیکی کتابخانه.\r\n- گزارش‌های هفتگی و روزانه سامان‌دهی کتابخانه.\r\n- گزارش فنی ابزار اندرویدی ثبت فیزیکی کتابخانه.\r\n\r\n### ۳.۴. بررسی نرم‌افزار قبلی\r\n\r\nابزار قبلی در مسیر زیر قرار دارد:\r\n\r\n`نرم‌افزار کتابخانه/`\r\n\r\nفایل‌ها و کدهای آن، به‌خصوص `index.html` و `README.md`، باید بررسی شوند.\r\n\r\nاین ابزار یک نمونه آزمایشی قبلی برای ثبت فیزیکی کتاب‌هاست. قابلیت‌ها و محدودیت‌های واقعی آن را بررسی کن و در صورت وجود منطق یا کدی که قابل استفاده مجدد است، فقط پس از بازبینی از آن استفاده کن.\r\n\r\nاین ابزار به‌تنهایی نرم‌افزار نهایی موردنظر نیست.\r\n\r\n### ۳.۵. بررسی وضعیت GitHub و شاخه‌ها\r\n\r\nدر بررسی اولیه مورخ ۱۴۰۵/۰۸/۱۰:\r\n\r\n- شاخه اصلی مخزن `main` بوده است.\r\n- آخرین SHA مشاهده‌شده برای `main`: `759ba04d3bbf3b5c468afcbf8b0690cca0dbe182`\r\n- شاخه کاری `feature/library-quick-inventory-v02-20261026` نیز وجود داشته است.\r\n- آخرین SHA مشاهده‌شده آن: `2b2b13601c73b346323eaac9409b7943fbed5540`\r\n- درخواست‌های ادغام شماره ۲، ۳ و ۴ در زمان بررسی باز و ادغام‌نشده بوده‌اند.\r\n\r\nاین اطلاعات صرفاً تصویر تاریخی زمان بررسی هستند. هنگام شروع، وضعیت زنده GitHub را دوباره بخوان و وضعیت فعلی شاخه‌ها، commitها و درخواست‌های ادغام را تعیین کن.\r\n\r\n**هیچ‌کدام از شاخه‌ها یا درخواست‌های ادغام را بدون بازبینی کامل و اجازه صریح کاربر ادغام نکن.**\r\n\r\n---\r\n\r\n## ۴. مرجع اصلی داده‌ها و Excel\r\n\r\nفایل مرجع اصلی کتابخانه:\r\n\r\n`کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx`\r\n\r\nاین فایل در مخزن اصلی GitHub ثبت شده است.\r\n\r\nSHA-256 ثبت‌شده برای نسخه مرجع:\r\n\r\n`0B34D6A013D11D2273EF306CEBAFAE92F024E52811E5BC43F6509ADE7AB19C16`\r\n\r\nاندازه ثبت‌شده در نسخه مرجع: ۲۵۹٬۲۷۶ بایت.\r\n\r\nاین فایل مبنای اصلی اطلاعات کتاب‌ها و ارتباطات ثبت‌شده است.\r\n\r\n### قواعد قطعی استفاده از Excel\r\n\r\n۱. عنوان‌های موجود در شیت «فهرست کتاب‌ها» مبنای شناسایی کتاب‌های موجود در فهرست هستند.\r\n\r\n۲. اطلاعات اولیه کتاب‌ها باید از همین فایل خوانده شوند.\r\n\r\n۳. فایل اصلی Excel فقط برای خواندن و بررسی استفاده شود.\r\n\r\n۴. هیچ تغییری مستقیم روی فایل مرجع اعمال نکن.\r\n\r\n۵. ابتدا تمام شیت‌ها، سرستون‌ها، ردیف‌ها، فرمول‌ها، سلول‌های خالی، ردیف‌های تکراری و ساختارهای خاص را شناسایی کن.\r\n\r\n۶. نام ستون‌ها و تعداد شیت‌ها را از روی حدس یا گزارش‌های قدیمی تعیین نکن؛ خود فایل فعلی را بخوان.\r\n\r\n۷. گزارش‌های قدیمی درباره تعداد ردیف و ستون بعضی نسخه‌ها با یکدیگر تفاوت دارند. بنابراین ساختار دقیق فایل باید در شروع پروژه دوباره ممیزی شود.\r\n\r\n۸. مقادیر خام فایل باید حفظ شوند. نرمال‌سازی نام‌ها و عنوان‌ها فقط برای جست‌وجو و تطبیق باشد و نباید مقدار اصلی را پاک یا جایگزین کند.\r\n\r\n۹. نام فایل، نام شیت، شماره ردیف و فیلد مبدأ هر داده تا حد امکان حفظ شود.\r\n\r\n۱۰. ورود مجدد یک فایل نباید باعث تکثیر یا بازنویسی ناخواسته رکوردها شود.\r\n\r\n۱۱. هرگونه واردسازی باید دارای گزارش تعداد رکوردهای خوانده‌شده، واردشده، تکراری، ناقص و نیازمند بررسی باشد.\r\n\r\n۱۲. برای ورود اطلاعات، ابتدا پیش‌نمایش و گزارش خطاها ایجاد کن و سپس عملیات ثبت را انجام بده.\r\n\r\n### فایل‌های تاریخی\r\n\r\nچهار فایل زیر در سوابق کتابخانه وجود دارند:\r\n\r\n- `لیست کتاب ها.xlsx`\r\n- `قطعات شهدا.xlsx`\r\n- `لیست کتابهای و شهدای مرتبط.xlsx`\r\n- `تجمیعی کامل (2).xlsx`\r\n\r\nنقش تاریخی آن‌ها را از README مربوط به پوشه `کتابخانه/فهرست کتاب‌های مرکز اسناد/` بررسی کن.\r\n\r\nاین فایل‌ها از نظر مفهومی یکسان نیستند:\r\n\r\n- فهرست کتاب‌ها، منبع اولیه شناسایی عنوان‌هاست.\r\n- قطعات شهدا، اطلاعات اولیه ارتباط کتاب و شهید و نشانی مزار را در بر دارد.\r\n- فهرست کتاب‌ها و شهدای مرتبط، اطلاعات پژوهشی و ارجاع صفحه را در بر دارد.\r\n- فایل تجمیعی، فهرست کتاب‌های مورد انتظار یا در دست پیگیری است؛ وجود یک عنوان در آن به معنی دریافت فیزیکی کتاب نیست.\r\n\r\nخروجی‌های قدیمی JSON، XML و CSV مشتق‌شده از سه Excel اولیه در پوشه `بایگانی/` قرار دارند. این خروجی‌ها نسخه‌های تاریخی و بایگانی‌شده‌اند و نباید بدون ممیزی و تصمیم مستند، به‌عنوان منبع فعال اطلاعات استفاده شوند.\r\n\r\n---\r\n\r\n## ۵. وضعیت واقعی کتابخانه و دسته‌بندی موضوعی\r\n\r\nکتاب‌ها در حال حاضر بر اساس شش دسته موضوعی تقسیم و در قفسه‌ها چیده شده‌اند.\r\n\r\nاین شش دسته باید حفظ شوند:\r\n\r\n| کد | عنوان دسته | تعداد جلد فیزیکی گزارش‌شده |\r\n|---|---|---:|\r\n| R | روایت و خاطرات | ۵۸۰ |\r\n| A | ادبیات و هنر | ۷۶ |\r\n| H | تاریخ و اسناد | ۶۰ |\r\n| P | پژوهش و تحلیل | ۶۹ |\r\n| K | کودک و نوجوان | ۳۶ |\r\n| M | متفرقه و متنوع | ۱۲۱ |\r\n| جمع | | ۹۴۲ |\r\n\r\nاین اعداد شمارش فیزیکی گزارش‌شده هستند و باید با تعریف خودشان در گزارش‌ها حفظ شوند.\r\n\r\nدر فایل Excel، ۹۸۰ رکورد برای شیت فهرست کتاب‌ها گزارش شده است.\r\n\r\nاختلاف حسابی ۳۸ موردی هنوز بررسی نهایی نشده است.\r\n\r\n**حق نداری این اختلاف را بدون بررسی به عنوان کتاب مفقود، کتاب تکراری یا خطای شمارش قطعی اعلام کنی.**\r\n\r\nسامانه باید بتواند این وضعیت‌ها را جداگانه گزارش کند:\r\n\r\n- رکورد موجود در فهرست Excel.\r\n- کتابی که در قفسه واقعاً مشاهده و تأیید شده است.\r\n- کتابی که در فهرست هست، اما در نوبت بررسی پیدا نشده است.\r\n- کتابی که در قفسه پیدا شده، اما در فهرست Excel وجود ندارد.\r\n- کتابی که اطلاعات آن ناقص یا نیازمند تطبیق است.\r\n- کتابی که هنوز تحویل نشده و فقط در فهرست انتظار قرار دارد.\r\n\r\nاین وضعیت‌ها نباید با هم ادغام شوند.\r\n\r\n---\r\n\r\n## ۶. نقشه فیزیکی قفسه‌ها\r\n\r\nچهار قفسه عملیاتی وجود دارد:\r\n\r\n- SH-01\r\n- SH-02\r\n- SH-03\r\n- SH-04\r\n\r\nهر قفسه شش طبقه دارد و طبقه‌ها از بالا به پایین شماره‌گذاری می‌شوند:\r\n\r\n- T01\r\n- T02\r\n- T03\r\n- T04\r\n- T05\r\n- T06\r\n\r\nقالب نشانی کامل:\r\n\r\n`SH-01-T01`\r\n\r\nجانمایی موضوعی ثبت‌شده:\r\n\r\n| محل فیزیکی | گروه |\r\n|---|---|\r\n| تمام طبقات SH-01 و SH-02 | R |\r\n| SH-03-T01 | H |\r\n| SH-03-T02 | A |\r\n| SH-03-T03 و SH-03-T04 | P |\r\n| SH-03-T05 و SH-03-T06 | M |\r\n| SH-04-T01 | K |\r\n| SH-04-T02 تا SH-04-T06 | ظرفیت آزاد |\r\n\r\nاین نقشه باید به‌صورت فرهنگ مکان در نرم‌افزار تعریف شود.\r\n\r\nکاربر هنگام ثبت محل نباید مجبور به تایپ کد باشد؛ باید بتواند با انتخاب قفسه و طبقه، محل را تعیین کند.\r\n\r\nکد محل به‌طور خودکار ساخته شود.\r\n\r\nمحل فیزیکی از شناسه کتاب و شناسه نسخه مستقل باشد.\r\n\r\nجابه‌جایی یک جلد باید فقط تاریخچه و محل آن نسخه را تغییر دهد؛ شناسه کتاب و ارتباط‌های پژوهشی آن ثابت بماند.\r\n\r\n---\r\n\r\n## ۷. معماری اطلاعات و مدل داده\r\n\r\nساختار اطلاعاتی نرم‌افزار باید حداقل از موجودیت‌های زیر تشکیل شود:\r\n\r\n### ۷.۱. کتاب‌شناختی (Books)\r\n\r\nهر اثر یا رکورد کتاب‌شناختی یک شناسه داخلی ثابت داشته باشد.\r\n\r\nفیلدهای موردنیاز:\r\n\r\n- شناسه داخلی کتاب.\r\n- عنوان خام کتاب.\r\n- عنوان نمایشی.\r\n- نام نویسنده یا نویسندگان.\r\n- نام پدیدآورنده، گردآورنده، مترجم یا ویراستار در صورت وجود.\r\n- نام ناشر.\r\n- ناشر استانداردشده در صورت تأیید.\r\n- سال انتشار یا چاپ.\r\n- تاریخ چاپ، در صورت ثبت دقیق.\r\n- نوبت چاپ.\r\n- شماره ویرایش یا مشخصات چاپ.\r\n- شابک، در صورت وجود.\r\n- گروه موضوعی اصلی از شش دسته.\r\n- کلیدواژه‌ها و موضوعات فرعی.\r\n- توضیحات کتاب.\r\n- خلاصه محتوای کتاب.\r\n- تعداد صفحات، در صورت وجود.\r\n- منبع اطلاعات و منشأ ثبت.\r\n- وضعیت تکمیل و اعتبار اطلاعات.\r\n- تاریخ ایجاد و آخرین ویرایش.\r\n\r\nفیلدهای ناموجود را خالی بگذار؛ هیچ مقدار کتاب‌شناختی را حدس نزن.\r\n\r\nنام نویسنده را از ستون توضیحات به‌صورت خودکار استخراج و قطعی نکن.\r\n\r\n### ۷.۲. نسخه فیزیکی (Book Copies)\r\n\r\nهر جلد واقعی کتاب باید نسخه فیزیکی مستقل داشته باشد.\r\n\r\nفیلدها:\r\n\r\n- شناسه نسخه فیزیکی.\r\n- شناسه کتاب‌شناختی مرتبط.\r\n- وضعیت نسخه.\r\n- محل فعلی قفسه و طبقه.\r\n- تاریخ مشاهده و ثبت.\r\n- وضعیت ظاهری.\r\n- وضعیت امانت یا جابه‌جایی.\r\n- یادداشت کارشناس.\r\n- تاریخ آخرین بررسی.\r\n\r\nشناسه پیشنهادی کتاب‌شناختی می‌تواند `BK-000001` و شناسه نسخه فیزیکی `CP-000001` باشد. این قالب‌ها فقط شناسه داخلی نرم‌افزار هستند و به معنی تصویب شماره‌گذاری نهایی چاپی نیستند.\r\n\r\nاگر یک عنوان سه جلد فیزیکی دارد، یک رکورد کتاب‌شناختی و سه رکورد نسخه فیزیکی ایجاد کن.\r\n\r\n### ۷.۳. پرونده شهدا (Martyrs)\r\n\r\nاطلاعات هر شهید باید در پرونده مستقل ثبت شود.\r\n\r\nفیلدها:\r\n\r\n- شناسه داخلی شهید.\r\n- نام.\r\n- نام خانوادگی.\r\n- نام کامل.\r\n- نام‌های جایگزین و اشکال مختلف نوشتاری.\r\n- شناسه معتبر سامانه‌های دیگر، در صورت تأیید.\r\n- وضعیت بررسی هویت.\r\n- منشأ اطلاعات.\r\n- توضیحات.\r\n\r\nبرای نشانی مزار:\r\n\r\n- قطعه.\r\n- ردیف.\r\n- شماره مزار.\r\n- نشانی کامل قابل نمایش.\r\n- منبع اطلاعات مزار.\r\n- وضعیت تأیید اطلاعات مزار.\r\n\r\nمقادیر قطعه، ردیف و شماره مزار باید به‌گونه‌ای نگهداری شوند که مقادیر متنی یا دارای صفر ابتدایی و حروف از بین نروند.\r\n\r\nنام مشابه به‌تنهایی اثبات‌کننده هویت یک شهید نیست.\r\n\r\nشناسه اختصاصی رسمی شهید باید پس از بررسی فنی سامانه موجود تعیین شود؛ تا آن زمان شناسه داخلی مستقل استفاده کن و شناسه رسمی نامعلوم را جعل نکن.\r\n\r\n### ۷.۴. ارتباط کتاب و شهید (Book-Martyr Links)\r\n\r\nرابطه میان کتاب و شهید باید چندبه‌چند باشد.\r\n\r\nیعنی:\r\n\r\n- یک کتاب می‌تواند درباره چند شهید مطلب داشته باشد.\r\n- یک شهید می‌تواند در چندین کتاب معرفی شده باشد.\r\n- هر ارتباط باید مستقل از سایر ارتباط‌ها قابل بررسی باشد.\r\n\r\nفیلدها:\r\n\r\n- شناسه ارتباط.\r\n- شناسه کتاب.\r\n- شناسه شهید.\r\n- نوع ارتباط.\r\n- شرح ارتباط.\r\n- منبع شناسایی.\r\n- نام منبع.\r\n- شیت و ردیف مبدأ در Excel، در صورت وجود.\r\n- شماره صفحه یا بازه صفحات.\r\n- درجه اطمینان یا وضعیت تطبیق.\r\n- وضعیت بررسی کارشناس.\r\n- توضیح کارشناس.\r\n- تاریخ و نام بازبین.\r\n\r\nوضعیت‌های ارتباط:\r\n\r\n- پیشنهادشده توسط سامانه.\r\n- بررسی‌نشده.\r\n- نیازمند بررسی.\r\n- تأییدشده.\r\n- ردشده با دلیل.\r\n- دارای تعارض اطلاعاتی.\r\n\r\nهیچ ارتباطی صرفاً به دلیل شباهت نام شهید با عنوان یا متن کتاب قطعی نشود.\r\n\r\n### ۷.۵. اطلاعات استخراج‌شده پژوهشی (Extracted Items)\r\n\r\nاین بخش از مهم‌ترین قابلیت‌های سامانه است.\r\n\r\nهدف آن ثبت اطلاعاتی است که پژوهشگر از داخل کتاب استخراج می‌کند.\r\n\r\nفیلدها:\r\n\r\n- شناسه مطلب.\r\n- شناسه کتاب.\r\n- شناسه شهید مرتبط.\r\n- عنوان مطلب.\r\n- نوع مطلب.\r\n- شماره صفحه یا بازه صفحات.\r\n- خلاصه پژوهشی.\r\n- متن یادداشت پژوهشگر.\r\n- نقل‌قول کوتاه مستند در صورت مجازبودن.\r\n- کلیدواژه‌ها.\r\n- نام پژوهشگر.\r\n- وضعیت بررسی.\r\n- نام بازبین.\r\n- تاریخ ثبت و تأیید.\r\n\r\nانواع مطلب می‌تواند شامل موارد زیر باشد:\r\n\r\n- زندگی‌نامه.\r\n- خاطره.\r\n- وصیت‌نامه.\r\n- نامه.\r\n- روایت عملیات.\r\n- سند تاریخی.\r\n- مصاحبه.\r\n- معرفی شخصیت.\r\n- اطلاعات خانواده.\r\n- اشاره کوتاه به شهید.\r\n- سایر.\r\n\r\nشماره صفحه باید با منبع کتاب قابل تطبیق باشد.\r\n\r\nمتن کامل کتاب یا محتوای دارای حق نشر را بدون مجوز در سامانه ذخیره یا منتشر نکن. خلاصه، یادداشت و ارجاع مستند را از متن کامل اثر تفکیک کن.\r\n\r\n---\r\n\r\n## ۸. امکانات و بخش‌های اصلی نرم‌افزار\r\n\r\nنرم‌افزار باید ساده، جمع‌وجور، قابل فهم و مناسب استفاده روزانه باشد.\r\n\r\nمنوهای پیچیده و چندلایه طراحی نکن.\r\n\r\nصفحه اصلی باید شامل جست‌وجوی سراسری و دسترسی مستقیم به پنج بخش اصلی باشد:\r\n\r\n### منوی اول: خانه\r\n\r\nامکانات:\r\n\r\n- جست‌وجوی سریع کتاب یا شهید.\r\n- ثبت سریع کتاب.\r\n- ثبت صوتی اطلاعات.\r\n- نمایش تعداد کتاب‌ها و نسخه‌های فیزیکی با تعریف دقیق.\r\n- تعداد کتاب‌های بررسی‌شده و بررسی‌نشده.\r\n- تعداد ارتباط‌های تأییدشده و منتظر بررسی.\r\n- میانبر به کارهای اخیر.\r\n- نمایش موارد دارای نقص یا نیازمند پیگیری.\r\n\r\nآمار نباید گمراه‌کننده باشد. تعداد آثار، تعداد نسخه‌های فیزیکی و تعداد ارتباط‌های پژوهشی باید جدا باشند.\r\n\r\n### منوی دوم: کتابخانه\r\n\r\nامکانات:\r\n\r\n- مشاهده فهرست کتاب‌ها.\r\n- جست‌وجو بر اساس عنوان.\r\n- جست‌وجو بر اساس نویسنده.\r\n- جست‌وجو بر اساس ناشر.\r\n- جست‌وجو بر اساس سال و نوبت چاپ.\r\n- جست‌وجو بر اساس دسته موضوعی.\r\n- جست‌وجو بر اساس قفسه و طبقه.\r\n- فیلتر کتاب‌های دیده‌شده، بررسی‌نشده و خارج از فهرست.\r\n- ثبت کتاب جدید.\r\n- ویرایش کنترل‌شده مشخصات کتاب.\r\n- مشاهده مشخصات هر کتاب.\r\n- مشاهده نسخه‌های فیزیکی آن کتاب.\r\n- مشاهده شهدا و مطالب پژوهشی مرتبط.\r\n\r\nصفحه مشخصات کتاب باید به‌صورت ساده و قابل فهم طراحی شود و اطلاعات کتاب‌شناختی را از اطلاعات هر نسخه فیزیکی جدا نشان دهد.\r\n\r\n### منوی سوم: شهدا\r\n\r\nامکانات:\r\n\r\n- فهرست شهدا.\r\n- جست‌وجوی نام و نام خانوادگی.\r\n- جست‌وجو با نام‌های جایگزین.\r\n- مشاهده پرونده هر شهید.\r\n- مشاهده نشانی مزار.\r\n- مشاهده کتاب‌های مرتبط.\r\n- مشاهده ارتباط‌های تأییدشده.\r\n- مشاهده ارتباط‌های در انتظار بررسی.\r\n- مشاهده خلاصه‌ها و مطالب استخراج‌شده از کتاب‌ها.\r\n- دسترسی به جست‌وجوی کتاب‌های جدید مرتبط با شهید.\r\n\r\n### منوی چهارم: جست‌وجوی هوشمند\r\n\r\nاین بخش موتور شناسایی کتاب‌های مرتبط با شهداست.\r\n\r\nباید امکان جست‌وجوی یک شهید یا تعداد زیادی از شهدا را فراهم کند.\r\n\r\n### منوی پنجم: پژوهش و بررسی\r\n\r\nامکانات:\r\n\r\n- ثبت خلاصه کتاب.\r\n- ثبت مطلب استخراج‌شده.\r\n- ثبت شماره صفحه.\r\n- اتصال مطلب به شهید.\r\n- مشاهده سوابق پژوهش.\r\n- بررسی پیشنهادهای هوش مصنوعی.\r\n- تأیید یا رد ارتباط کتاب و شهید.\r\n- مشاهده اطلاعات دارای مغایرت.\r\n- آماده‌سازی اطلاعات تأییدشده برای انتشار.\r\n\r\nتنظیمات، کاربران، پشتیبان‌گیری و گزارش‌ها در بخش تنظیمات مدیریتی با دسترسی ساده قرار بگیرند؛ نه اینکه منوی اصلی را شلوغ کنند.\r\n\r\n---\r\n\r\n## ۹. جست‌وجوی هوشمند کتاب‌های مرتبط با شهدا\r\n\r\nاین بخش یکی از مهم‌ترین مزیت‌های نرم‌افزار است.\r\n\r\nسامانه باید بتواند برای شناسایی منابع مرتبط با شهدا در وب جست‌وجو انجام دهد.\r\n\r\n### منابع جست‌وجو\r\n\r\nبه ترتیب اولویت:\r\n\r\n۱. سازمان اسناد و کتابخانه ملی ایران و فهرست‌های کتاب‌شناختی آن.\r\n\r\n۲. اطلاعات فیپا و شناسنامه کتاب‌ها.\r\n\r\n۳. وب‌سایت رسمی ناشران.\r\n\r\n۴. انتشارات سوره مهر.\r\n\r\n۵. سایر ناشران معتبر حوزه شهدا، دفاع مقدس، تاریخ معاصر و ادبیات مرتبط.\r\n\r\n۶. سایر منابع معتبر که در آینده به فهرست منابع مجاز اضافه می‌شوند.\r\n\r\nبرای هر منبع، روش دسترسی مجاز را بررسی کن:\r\n\r\n- API رسمی، در صورت وجود.\r\n- داده‌های عمومی و قابل استفاده.\r\n- موتور جست‌وجوی وب برای یافتن صفحه رسمی.\r\n- روش استخراج اطلاعاتی که با قوانین و شرایط استفاده منبع سازگار باشد.\r\n\r\nوجود API یا امکان استخراج خودکار را بدون بررسی فرض نکن.\r\n\r\nمحدودیت‌های فنی، حقوقی، کپچا، محدودیت نرخ درخواست و شرایط استفاده منابع را رعایت کن. هیچ مکانیزم امنیتی یا محدودیت دسترسی را دور نزن.\r\n\r\nاگر یک منبع API یا روش استخراج مجاز ندارد، آن را به‌عنوان جست‌وجوی راهنما یا بررسی دستی در سامانه معرفی کن و ادعای اتصال خودکار نداشته باش.\r\n\r\n### روش جست‌وجو\r\n\r\n۱. کاربر یک شهید را انتخاب می‌کند.\r\n\r\n۲. سامانه نام کامل، نام‌های جایگزین و شکل‌های نوشتاری شناخته‌شده او را در اختیار موتور جست‌وجو قرار می‌دهد.\r\n\r\n۳. جست‌وجو در منابع مجاز انجام می‌شود.\r\n\r\n۴. نتایج احتمالی کتاب‌ها جمع‌آوری می‌شوند.\r\n\r\n۵. مشخصات کتاب‌شناختی از منابع معتبر استخراج می‌شوند.\r\n\r\n۶. نتایج با کتاب‌های موجود در فهرست مرجع مقایسه می‌شوند.\r\n\r\n۷. موارد مشابه، تکراری، ناقص یا دارای تعارض علامت‌گذاری می‌شوند.\r\n\r\n۸. نتیجه به صف بررسی کارشناس منتقل می‌شود.\r\n\r\n### اطلاعاتی که باید از هر کتاب پیشنهادی استخراج شود\r\n\r\n- عنوان کتاب.\r\n- نویسنده یا نویسندگان.\r\n- ناشر.\r\n- سال انتشار.\r\n- نوبت چاپ یا مشخصات چاپ.\r\n- شابک.\r\n- موضوع کتاب.\r\n- توضیحات یا معرفی ناشر.\r\n- تصویر جلد فقط در صورت دسترسی و مجازبودن استفاده.\r\n- نام شهید مرتبط.\r\n- نام منبع اینترنتی.\r\n- لینک مستقیم صفحه منبع.\r\n- تاریخ و ساعت بازیابی.\r\n- شواهدی که ارتباط کتاب با شهید را نشان می‌دهد.\r\n- وضعیت اعتبار و بررسی.\r\n\r\n### صف بررسی کارشناس\r\n\r\nهیچ نتیجه‌ای که از اینترنت یا هوش مصنوعی به‌دست آمده، مستقیماً وارد اطلاعات قطعی نشود.\r\n\r\nدر صفحه بررسی، کارشناس باید بتواند:\r\n\r\n- اطلاعات پیشنهادی را ببیند.\r\n- لینک منبع را باز کند.\r\n- آن را با فهرست کتاب‌های موجود مقایسه کند.\r\n- مشخصات را اصلاح کند.\r\n- پیشنهاد را تأیید کند.\r\n- پیشنهاد را رد کند.\r\n- ارتباط با شهید را تأیید یا رد کند.\r\n- علت رد یا اصلاح را ثبت کند.\r\n\r\nفقط پس از تأیید انسانی، داده به پرونده نهایی کتاب یا شهید منتقل شود.\r\n\r\n### جست‌وجوی انبوه\r\n\r\nباید امکان اجرای جست‌وجوی گروهی برای همه شهدا وجود داشته باشد.\r\n\r\nبرای جلوگیری از فشار غیرضروری به سایت‌های بیرونی:\r\n\r\n- جست‌وجو در دسته‌های محدود انجام شود.\r\n- ابتدا یک پایلوت محدود با حداکثر ۲۰ پرونده شهید انجام بده.\r\n- تعداد نتایج، خطاها و نرخ تطبیق را گزارش کن.\r\n- امکان توقف، ادامه و ازسرگیری جست‌وجو فراهم باشد.\r\n- جست‌وجوهای تکراری بی‌دلیل دوباره اجرا نشوند.\r\n- همه پیشنهادها به صف بررسی انسانی بروند.\r\n\r\nپس از پایلوت، امکان اجرای جست‌وجوی سایر شهدا از داخل برنامه فراهم باشد.\r\n\r\n---\r\n\r\n## ۱۰. هوشمندسازی و تشخیص ارتباط‌ها\r\n\r\nهوش مصنوعی باید در این بخش نقش دستیار پژوهشی داشته باشد.\r\n\r\nقابلیت‌های مورد انتظار:\r\n\r\n- تشخیص شکل‌های مختلف نوشتاری نام شهید.\r\n- پیشنهاد کتاب‌های احتمالی مرتبط.\r\n- تشخیص شباهت عنوان‌ها.\r\n- شناسایی اطلاعات ناقص.\r\n- پیشنهاد کلیدواژه.\r\n- استخراج اطلاعات کتاب‌شناختی از صفحات مجاز.\r\n- خلاصه‌سازی توضیحات ناشر.\r\n- پیشنهاد ارتباط کتاب با شهید بر اساس شواهد.\r\n- شناسایی تکرار احتمالی کتاب.\r\n- پیشنهاد اصلاحات نگارشی.\r\n- یافتن موارد دارای تعارض.\r\n\r\nبرای جست‌وجوی فارسی، نرمال‌سازی موارد زیر را در لایه جست‌وجو در نظر بگیر:\r\n\r\n- ی و ي.\r\n- ک و ك.\r\n- فاصله و نیم‌فاصله.\r\n- اعراب و نشانه‌های اضافی.\r\n- شکل‌های رایج اختصاری و نام‌های جایگزین.\r\n\r\nمقدار خام اصلی را در هیچ‌یک از این تبدیل‌ها از بین نبر.\r\n\r\nدر نتایج تطبیق، دلیل پیشنهاد را نشان بده. صرف ارائه یک درصد اطمینان کافی نیست؛ باید معلوم باشد چرا دو رکورد مشابه تشخیص داده شده‌اند.\r\n\r\n---\r\n\r\n## ۱۱. ورود صوتی و ثبت سریع با موبایل\r\n\r\nنرم‌افزار باید در گوشی اندرویدی راحت و سریع استفاده شود.\r\n\r\nقابلیت ورود صوتی یکی از نیازهای مهم است.\r\n\r\nکاربر باید بتواند کنار قفسه بایستد، کتاب را در دست بگیرد و بدون تایپ طولانی اطلاعات آن را وارد کند.\r\n\r\nنمونه فرمان:\r\n\r\n«عنوان کتاب: دلیل. نویسنده: نام نویسنده. ناشر: انتشارات بیست و هفت. سال چاپ: ۱۳۹۸. نوبت چاپ: سوم. گروه: روایت و خاطرات. محل: قفسه یک، طبقه سه.»\r\n\r\nسامانه باید:\r\n\r\n۱. گفتار را به متن تبدیل کند.\r\n\r\n۲. اطلاعات را در فیلدهای مربوط قرار دهد.\r\n\r\n۳. عنوان، نویسنده، ناشر، سال چاپ، نوبت چاپ، گروه و محل را از هم تفکیک کند.\r\n\r\n۴. موارد نامطمئن را مشخص کند.\r\n\r\n۵. یک پیش‌نمایش برای اصلاح کاربر نمایش دهد.\r\n\r\n۶. فقط پس از تأیید کاربر اطلاعات را ذخیره کند.\r\n\r\nبرای نسخه نخست، از قابلیت‌های تایپ صوتی خود سیستم‌عامل یا صفحه‌کلید اندروید می‌توان استفاده کرد.\r\n\r\nاگر از قابلیت اختصاصی Speech Recognition استفاده می‌کنی، سازگاری آن را با Android Chrome و زبان فارسی واقعاً آزمایش کن.\r\n\r\nقابلیت تشخیص گفتار کاملاً آفلاین را بدون آزمون و اثبات، تضمین‌شده معرفی نکن.\r\n\r\nاگر تشخیص صوتی در مرورگر پشتیبانی نشد، روش جایگزین ساده‌ای مانند میکروفون صفحه‌کلید یا ورود دستی فراهم کن.\r\n\r\nضبط یا ارسال صدا به سرویس بیرونی بدون اطلاع و رضایت کاربر ممنوع است.\r\n\r\n---\r\n\r\n## ۱۲. طراحی ظاهری و تجربه کاربری\r\n\r\nظاهر نرم‌افزار باید رسمی، ساده، آرام، حرفه‌ای و مناسب یک مرکز اسناد باشد.\r\n\r\nزبان اصلی فارسی است.\r\n\r\nتمام صفحات باید راست‌به‌چپ باشند.\r\n\r\nطراحی باید ابتدا برای گوشی اندرویدی انجام شود و سپس برای صفحه بزرگ‌تر رایانه سازگار شود.\r\n\r\n### پالت رنگ پیشنهادی\r\n\r\n- آبی اصلی سازمانی: `#1F4E79`\r\n- آبی روشن برای سطوح فرعی: `#EAF1F7`\r\n- زمینه عمومی: `#F5F7FA`\r\n- کارت‌ها و فرم‌ها: سفید.\r\n- متن اصلی: `#253247`\r\n- متن ثانویه: `#697586`\r\n- سبز برای تأیید: `#2E7D5B`\r\n- نارنجی برای نیازمند بررسی: `#C58A2B`\r\n- قرمز برای خطا یا رد: `#B94A48`\r\n- خاکستری برای وضعیت نامشخص: `#7B8491`\r\n\r\nاز رنگ‌های زیاد، افکت‌های سنگین، حرکت‌های غیرضروری، تصاویر تزئینی بزرگ و کارت‌های پیچیده استفاده نکن.\r\n\r\n### تایپوگرافی\r\n\r\n- فونت فارسی خوانا و مناسب موبایل.\r\n- اندازه مناسب متن و دکمه‌ها.\r\n- فاصله کافی بین عناصر لمسی.\r\n- پشتیبانی از اعداد فارسی و انگلیسی.\r\n- نمایش صحیح نام‌های فارسی و نیم‌فاصله.\r\n\r\nدر استفاده از فونت محلی، مجوز و امکان استفاده آن را بررسی کن؛ وابستگی غیرضروری به CDN ایجاد نکن.\r\n\r\n### اصول رابط کاربری\r\n\r\n- تعداد منوهای اصلی محدود باشد.\r\n- جست‌وجوی سریع همیشه در دسترس باشد.\r\n- دکمه ثبت اطلاعات واضح باشد.\r\n- فرم‌ها کوتاه و مرحله‌ای باشند.\r\n- فیلدهای اختیاری مانع ثبت اولیه نشوند.\r\n- پیام خطا ساده و فارسی باشد.\r\n- وضعیت هر رکورد با برچسب واضح نمایش داده شود.\r\n- صفحات طولانی و پیچیده طراحی نشوند.\r\n- کاربر برای یک عملیات معمولی مجبور به جابه‌جایی بین چندین صفحه نباشد.\r\n\r\n---\r\n\r\n## ۱۳. معماری فنی و روش اجرای نرم‌افزار\r\n\r\nبا توجه به تجربه قبلی در Android Studio و دشواری کار با فایل‌های Kotlin و XML، مسیر اصلی توسعه را به‌صورت یک نرم‌افزار وب نصب‌شونده روی گوشی انتخاب کن.\r\n\r\n### فناوری اصلی پیشنهادی\r\n\r\n**Progressive Web App (PWA)**\r\n\r\nنرم‌افزار باید:\r\n\r\n- روی Android قابل نصب باشد.\r\n- از صفحه اصلی گوشی اجرا شود.\r\n- ظاهر یک برنامه مستقل داشته باشد.\r\n- در حالت آفلاین، بخش‌های محلی و ذخیره‌شده قابل استفاده باشند.\r\n- روی رایانه نیز با مرورگر قابل استفاده باشد.\r\n- به‌روزرسانی آن از طریق نسخه جدید برنامه امکان‌پذیر باشد.\r\n\r\nپشته فنی پیشنهادی:\r\n\r\n- رابط کاربری: TypeScript و یک چارچوب سبک و قابل نگهداری مانند React و Vite.\r\n- ذخیره‌سازی آفلاین: IndexedDB.\r\n- Service Worker برای فایل‌های ثابت و پوسته برنامه.\r\n- لایه مستقل برای دسترسی به داده‌ها.\r\n- API مستقل برای ارتباط آینده با پایگاه داده مرکزی.\r\n- Backend قابل استقرار روی زیرساخت اختصاصی مرکز.\r\n- پایگاه داده مرکزی قابل مهاجرت و پشتیبان‌گیری.\r\n\r\nاین فناوری‌ها را با وضعیت واقعی مخزن تطبیق بده و فقط در صورت وجود دلیل فنی مستند، آن‌ها را تغییر بده.\r\n\r\n### دو حالت عملکرد\r\n\r\n**حالت محلی و آفلاین:**\r\n\r\n- جست‌وجوی فهرست واردشده.\r\n- ثبت و ویرایش اطلاعات مجاز محلی.\r\n- مشاهده پرونده کتاب و شهید.\r\n- ثبت محل فیزیکی.\r\n- ثبت یادداشت پژوهشی.\r\n- تهیه و بازیابی پشتیبان.\r\n\r\nاین قابلیت‌ها باید بدون اینترنت قابل استفاده باشند.\r\n\r\n**حالت مرکزی و آنلاین:**\r\n\r\n- همگام‌سازی اطلاعات بین دستگاه‌ها.\r\n- مدیریت کاربران و نقش‌ها.\r\n- جست‌وجوی اینترنتی.\r\n- جست‌وجوی انبوه در منابع بیرونی.\r\n- صف بررسی کارشناسی.\r\n- اتصال کنترل‌شده به وب‌سایت.\r\n- گزارش‌گیری مرکزی و تاریخچه تغییرات.\r\n\r\nاگر زیرساخت مرکزی هنوز آماده نیست، حالت محلی را به‌صورت کامل و قابل استفاده بساز و API و لایه اتصال به سامانه مرکزی را به‌صورت مستقل و مستند آماده کن.\r\n\r\nاز سرویس‌های شخص ثالث به‌عنوان وابستگی اجباری معماری نهایی استفاده نکن.\r\n\r\nGitHub صرفاً ابزار نگهداری نسخه و توسعه است، نه منبع داده عملیاتی یا میزبان عمومی اطلاعات محرمانه کتابخانه.\r\n\r\n---\r\n\r\n## ۱۴. حفاظت از داده و امنیت\r\n\r\nاصل مهم این است که مرکز اسناد مالک اطلاعات خود باقی بماند.\r\n\r\nقواعد:\r\n\r\n۱. فایل مرجع Excel بدون نسخه پشتیبان هرگز تغییر نکند.\r\n\r\n۲. داده‌های کتابخانه نباید به‌صورت عمومی در GitHub Pages یا مسیر عمومی قرار گیرند.\r\n\r\n۳. فایل Excel، نام شهدا، یادداشت‌های پژوهشی و داده‌های داخلی را در فایل‌های عمومی یا بسته‌های قابل دسترسی عمومی قرار نده.\r\n\r\n۴. هیچ تغییری در Supabase، پایگاه داده عملیاتی یا سامانه اصلی بدون اجازه صریح کاربر انجام نده.\r\n\r\n۵. از کلیدهای API و رمزهای عبور در کد یا مخزن GitHub استفاده نکن.\r\n\r\n۶. اطلاعات کاربران و نقش‌ها باید از داده‌های کتاب‌شناختی جدا باشند.\r\n\r\n۷. ثبت‌کننده، بازبین و مدیر سامانه نقش‌های متفاوتی داشته باشند؛ اما استفاده اولیه با یک کاربر نیز ساده و بدون پیچیدگی باشد.\r\n\r\n۸. تغییرات مهم باید در Audit Log ثبت شوند.\r\n\r\n۹. هیچ اطلاعات تأییدنشده‌ای به‌طور خودکار منتشر نشود.\r\n\r\n۱۰. حذف و ادغام رکوردها باید کنترل‌شده، دارای سابقه و تا حد ممکن قابل برگشت باشد.\r\n\r\n۱۱. نسخه پشتیبان JSON کامل با شماره نسخه ساختار داده، تاریخ تهیه و شمارش رکوردها ایجاد شود.\r\n\r\n۱۲. بازیابی پشتیبان باید پیش‌نمایش، اعتبارسنجی، گزارش تعارض و امکان لغو داشته باشد.\r\n\r\n۱۳. CSV و Excel برای خروجی‌های گزارشی و بازبینی فراهم شوند؛ پشتیبان اصلی باید ساختار کامل روابط را نیز حفظ کند.\r\n\r\n۱۴. از اطلاعات حساس غیرضروری در گزارش‌های خطا و لاگ‌ها استفاده نکن.\r\n\r\n### نقش‌های پیشنهادی کاربران\r\n\r\n- مدیر سامانه.\r\n- ثبت‌کننده کتاب.\r\n- پژوهشگر.\r\n- بازبین اطلاعات.\r\n- مسئول تأیید و انتشار.\r\n\r\nدر شروع پروژه یک کاربر اصلی کافی است؛ اما مدل داده و سطح دسترسی باید برای اضافه‌شدن کاربران بعدی قابل توسعه باشد.\r\n\r\n---\r\n\r\n## ۱۵. ارتباط با وب‌سایت رسمی گلزار تهران\r\n\r\nوب‌سایت هدف:\r\n\r\n`https://golzarteh.ir`\r\n\r\nاین نرم‌افزار جایگزین وب‌سایت موجود نیست و نباید طراحی یا ساختار سایت را تغییر دهد.\r\n\r\nمرکز اسناد باید منبع اصلی اطلاعات پژوهشی و آرشیوی باشد.\r\n\r\nوب‌سایت فقط اطلاعاتی را دریافت می‌کند که بررسی، تأیید و برای انتشار مجاز شناخته شده‌اند.\r\n\r\nمعماری تبادل اطلاعات:\r\n\r\nمرکز اسناد  \r\n↓  \r\nثبت و تکمیل اطلاعات  \r\n↓  \r\nبررسی و تأیید کارشناسی  \r\n↓  \r\nدروازه انتشار  \r\n↓  \r\nبسته اطلاعاتی قابل انتشار  \r\n↓  \r\nوب‌سایت گلزار تهران\r\n\r\nدر نسخه اولیه:\r\n\r\n- امکان خروجی اطلاعات تأییدشده فراهم باشد.\r\n- ساختار API و قرارداد تبادل اطلاعات طراحی شود.\r\n- شناسه شهید و روش اتصال به سامانه فعلی قابل تنظیم باشد.\r\n- امکان مشاهده پیش‌نمایش محتوای قابل انتشار وجود داشته باشد.\r\n\r\nهیچ داده‌ای را مستقیماً به وب‌سایت زنده ارسال نکن.\r\n\r\nبرای اتصال عملیاتی، ابتدا API، سطح دسترسی، شناسه‌های مورد استفاده و مجوز مسئول فنی سایت باید بررسی شود.\r\n\r\nاطلاعات داخلی، داده‌های شخصی، یادداشت‌های پژوهشی خصوصی و ارتباط‌های تأییدنشده نباید وارد مسیر انتشار عمومی شوند.\r\n\r\n---\r\n\r\n## ۱۶. گزارش‌ها و داشبورد مدیریتی\r\n\r\nسامانه باید امکان تولید گزارش‌های ساده و کاربردی داشته باشد:\r\n\r\n- تعداد کل رکوردهای کتاب‌شناختی.\r\n- تعداد کل نسخه‌های فیزیکی.\r\n- تعداد نسخه‌های فیزیکی مشاهده و تأییدشده.\r\n- تعداد کتاب‌های خارج از فهرست.\r\n- تعداد کتاب‌های نیازمند بررسی.\r\n- آمار شش دسته موضوعی.\r\n- آمار موجودی قفسه‌ها و طبقات.\r\n- کتاب‌های دارای اطلاعات ناقص.\r\n- کتاب‌های دارای ارتباط تأییدشده با شهدا.\r\n- تعداد شهدا دارای کتاب مرتبط.\r\n- تعداد ارتباط‌های پیشنهادی و تأییدنشده.\r\n- تعداد کتاب‌های دارای اطلاعات پژوهشی استخراج‌شده.\r\n- تعداد مطالب دارای شماره صفحه.\r\n- آمار پیشنهادهای جست‌وجوی اینترنتی.\r\n- تعداد نتایج تأییدشده و ردشده.\r\n- گزارش مغایرت‌های Excel با موجودی فیزیکی.\r\n\r\nآمارها باید همراه با تعریف دقیق نمایش داده شوند.\r\n\r\nبرای مثال، «تعداد کتاب» با «تعداد جلد فیزیکی» یکی نیست.\r\n\r\nگزارش‌ها باید امکان خروجی Excel و CSV داشته باشند.\r\n\r\n---\r\n\r\n## ۱۷. مراحل اجرایی توسعه\r\n\r\nکار را به مراحل زیر تقسیم کن، اما در هیچ مرحله‌ای بدون دلیل فنی کاربر را با پرسش‌های تکراری متوقف نکن.\r\n\r\n### مرحله صفر: بررسی کامل\r\n\r\n- بررسی مخزن و تمام اسناد مرتبط.\r\n- بررسی شاخه main و شاخه‌های کاری.\r\n- بررسی درخواست‌های ادغام باز.\r\n- بررسی فایل Excel مرجع.\r\n- بررسی کد ابزار قبلی.\r\n- بررسی مدل داده و گزارش‌های ممیزی.\r\n- ثبت تصمیم‌های قطعی، پیشنهادها و موارد باز.\r\n- تهیه Recovery Point پیش از تغییر.\r\n\r\nخروجی این مرحله باید یک گزارش کوتاه و دقیق از وضعیت موجود باشد.\r\n\r\n### مرحله یک: طراحی معماری و پایگاه داده\r\n\r\n- طراحی مدل داده نهایی.\r\n- طراحی روابط کتاب، نسخه فیزیکی، شهید، مزار و مطلب پژوهشی.\r\n- طراحی گردش کار تأیید.\r\n- طراحی ورود Excel.\r\n- طراحی جست‌وجوی فارسی.\r\n- طراحی پشتیبان و بازیابی.\r\n- طراحی رابط کاربری و منوها.\r\n- طراحی PWA و حالت آفلاین.\r\n\r\n### مرحله دو: ساخت نسخه عملیاتی اولیه\r\n\r\nباید یک نسخه قابل اجرا بسازی که شامل این قابلیت‌ها باشد:\r\n\r\n- ورود کنترل‌شده فایل Excel.\r\n- جست‌وجوی کتاب.\r\n- ثبت و ویرایش کتاب.\r\n- ثبت نسخه فیزیکی.\r\n- ثبت موضوع و محل.\r\n- ثبت پرونده شهید.\r\n- ثبت ارتباط کتاب و شهید.\r\n- نمایش پرونده کتاب و شهید.\r\n- ثبت خلاصه پژوهشی و شماره صفحه.\r\n- ذخیره محلی پایدار.\r\n- پشتیبان‌گیری و بازیابی.\r\n- رابط فارسی و نصب‌پذیر روی موبایل.\r\n\r\nاین نسخه نباید فقط یک طرح نمایشی یا چند صفحه غیرعملیاتی باشد.\r\n\r\n### مرحله سه: جست‌وجوی هوشمند بیرونی\r\n\r\n- بررسی منابع رسمی.\r\n- ساخت آداپتورهای مستقل برای منابع.\r\n- جست‌وجو بر اساس نام شهید.\r\n- استخراج اطلاعات کتاب.\r\n- ذخیره پیشنهادها.\r\n- تشخیص تکرار و تعارض.\r\n- تشکیل صف بررسی کارشناس.\r\n- اجرای پایلوت محدود و گزارش کیفیت.\r\n- آماده‌سازی جست‌وجوی گروهی همه شهدا.\r\n\r\n### مرحله چهار: پژوهش و استخراج اطلاعات\r\n\r\n- تکمیل فرم پژوهش.\r\n- اتصال خلاصه و شماره صفحه به کتاب و شهید.\r\n- جست‌وجوی مطالب استخراج‌شده.\r\n- گزارش وضعیت پژوهش.\r\n- آماده‌سازی اطلاعات برای استفاده در گویاسازی و تولید محتوا.\r\n\r\n### مرحله پنج: ارتباط با وب‌سایت\r\n\r\n- طراحی قرارداد API.\r\n- تهیه بسته انتشار.\r\n- پیش‌نمایش اطلاعات مجاز.\r\n- آزمایش ارتباط در محیط غیرعملیاتی.\r\n- اتصال عملیاتی فقط پس از مجوز و هماهنگی فنی.\r\n\r\n### مرحله شش: آزمون، نصب و تحویل\r\n\r\n- آزمون گوشی اندرویدی.\r\n- آزمون رایانه.\r\n- آزمون آفلاین.\r\n- آزمون ذخیره‌سازی.\r\n- آزمون پشتیبان و بازیابی.\r\n- آزمون جست‌وجو.\r\n- آزمون ورودی صوتی.\r\n- آزمون جست‌وجوی کتاب‌های مرتبط.\r\n- بررسی امنیت و سطح دسترسی.\r\n- تهیه راهنمای ساده کاربر.\r\n\r\n---\r\n\r\n## ۱۸. آزمون‌های الزامی و معیار پذیرش\r\n\r\nهیچ قابلیتی را صرفاً با نوشتن کد موفق اعلام نکن.\r\n\r\nحداقل این آزمون‌ها باید انجام شوند:\r\n\r\n### آزمون داده\r\n\r\n- تطبیق تعداد رکوردهای واردشده با Excel.\r\n- کنترل نام شیت و سرستون.\r\n- حفظ منشأ داده.\r\n- کنترل رکوردهای خالی و ناقص.\r\n- عدم ادغام خودکار عناوین مشابه.\r\n- عدم تولید شناسه تکراری.\r\n\r\n### آزمون کتاب و نسخه فیزیکی\r\n\r\n- ثبت یک کتاب جدید.\r\n- ثبت دو نسخه فیزیکی از یک کتاب.\r\n- انتقال یک نسخه به قفسه دیگر.\r\n- بررسی ثابت‌ماندن شناسه کتاب.\r\n- ثبت کتاب خارج از فهرست.\r\n\r\n### آزمون شهدا و ارتباط‌ها\r\n\r\n- ثبت یک پرونده شهید.\r\n- ثبت اطلاعات قطعه، ردیف و شماره مزار.\r\n- اتصال یک کتاب به چند شهید.\r\n- اتصال چند کتاب به یک شهید.\r\n- بررسی ارتباط‌های تأییدنشده.\r\n- رد یک ارتباط نادرست با ثبت دلیل.\r\n\r\n### آزمون پژوهشی\r\n\r\n- ثبت یک خلاصه از کتاب.\r\n- ثبت شماره صفحه.\r\n- اتصال مطلب به یک شهید.\r\n- مشاهده مطالب از طریق پرونده شهید.\r\n- مشاهده سوابق مطلب و وضعیت تأیید.\r\n\r\n### آزمون پشتیبان\r\n\r\n- تهیه فایل پشتیبان.\r\n- بستن برنامه.\r\n- بازکردن مجدد.\r\n- بازیابی اطلاعات.\r\n- کنترل تعداد و روابط.\r\n- بررسی تعارض احتمالی.\r\n\r\n### آزمون موبایل و صوت\r\n\r\n- نصب PWA روی Android.\r\n- اجرای مستقل از نوار آدرس مرورگر.\r\n- ورود و ویرایش اطلاعات با لمس.\r\n- جست‌وجوی فارسی.\r\n- آزمایش تایپ صوتی فارسی.\r\n- آزمون قطع اینترنت و ادامه ثبت اطلاعات محلی.\r\n- کنترل ماندگاری داده پس از بستن و بازکردن برنامه.\r\n\r\n### آزمون جست‌وجوی هوشمند\r\n\r\n- آزمایش روی حداکثر ۲۰ پرونده شهید در پایلوت.\r\n- کنترل صحت اطلاعات کتاب‌شناختی.\r\n- بررسی منبع و لینک هر نتیجه.\r\n- کنترل تشخیص عناوین مشابه.\r\n- بررسی پیشنهادهای اشتباه.\r\n- تأیید اینکه هیچ ارتباطی خودکار قطعی نشده است.\r\n\r\nبرای آزمون از داده آزمایشی استفاده کن. برای استفاده با داده واقعی، ابتدا نمونه‌ای محدود و قابل بازبینی تهیه کن.\r\n\r\nهر آزمونی که اجرا نشده، صریحاً «انجام‌نشده» گزارش شود.\r\n\r\n---\r\n\r\n## ۱۹. شیوه کار با GitHub و کنترل تغییرات\r\n\r\nتمام توسعه در همان مخزن رسمی انجام شود.\r\n\r\nپروژه جدید باید در یک پوشه مستقل و تا حد امکان خارج از هسته نرم‌افزارهای قبلی قرار گیرد.\r\n\r\nمسیر پیشنهادی:\r\n\r\n`apps/library-research-pwa/`\r\n\r\nدر صورت وجود ساختار مناسب‌تر، با دلیل فنی مستند انتخاب دیگری انجام بده.\r\n\r\nقواعد:\r\n\r\n۱. قبل از تغییر، وضعیت فایل‌ها و شاخه را بررسی کن.\r\n\r\n۲. Recovery Point ایجاد کن.\r\n\r\n۳. از شاخه مستقل جدیدی بر اساس آخرین `main` استفاده کن.\r\n\r\n۴. کدهای اصلی و نرم‌افزارهای عملیاتی قفل‌شده را تغییر نده.\r\n\r\n۵. PRهای قدیمی را خودکار ادغام نکن.\r\n\r\n۶. `git add .` اجرا نکن.\r\n\r\n۷. فایل‌های کاربر را حذف یا بازنویسی نکن.\r\n\r\n۸. فایل Excel مرجع را تغییر نده.\r\n\r\n۹. Supabase را تغییر نده.\r\n\r\n۱۰. اطلاعات خصوصی را در بسته عمومی قرار نده.\r\n\r\n۱۱. پس از هر مرحله فایل‌ها، وابستگی‌ها، حجم و ساختار تغییرات را بررسی کن.\r\n\r\n۱۲. تست واقعی و Review انجام بده.\r\n\r\n۱۳. گزارش روزانه و فنی پروژه را به‌روز کن.\r\n\r\n۱۴. تغییرات را در یک PR پیش‌نویس برای بررسی نهایی آماده کن؛ ادغام بدون اجازه ممنوع است.\r\n\r\n---\r\n\r\n## ۲۰. مستندات و خروجی‌های الزامی\r\n\r\nدر پایان هر مرحله باید مستندات زیر وجود داشته باشند:\r\n\r\n- گزارش معماری نرم‌افزار.\r\n- سند مدل داده.\r\n- سند فیلدها و روابط.\r\n- سند ورود Excel.\r\n- سند جست‌وجوی هوشمند و منابع بیرونی.\r\n- سند حفاظت داده و سطح دسترسی.\r\n- راهنمای نصب روی Android.\r\n- راهنمای کاربری فارسی.\r\n- گزارش آزمون‌ها.\r\n- گزارش تغییرات.\r\n- گزارش روزانه.\r\n- گزارش فنی زنده.\r\n- فهرست محدودیت‌ها و قابلیت‌های پیاده‌سازی‌نشده.\r\n\r\nدر GitHub گزارش‌ها را در مسیرهای سازمان‌یافته نگهداری کن و به اسناد قبلی بدون ضرورت دست نزن.\r\n\r\n---\r\n\r\n## ۲۱. اصول تصمیم‌گیری بدون توقف‌های غیرضروری\r\n\r\nبرای جلوگیری از اتلاف وقت کاربر، این قواعد را رعایت کن:\r\n\r\n- اطلاعات موجود در GitHub را دوباره از کاربر نخواه.\r\n- اگر یک تصمیم در سند ثبت شده است، همان را مبنا قرار بده.\r\n- اگر چند سند با هم تعارض دارند، تعارض را استخراج کن و منبع معتبرتر و جدیدتر را با ذکر دلیل انتخاب کن.\r\n- اگر ساختار Excel نامشخص است، فایل واقعی را بررسی کن؛ سؤال درباره ستون‌ها نپرس.\r\n- اگر منبع بیرونی API ندارد، روش مجاز جایگزین را بررسی کن.\r\n- اگر امکانات صوتی مرورگر محدود است، روش جایگزین مناسب Android را پیاده‌سازی کن.\r\n- اگر زیرساخت مرکزی آماده نیست، نسخه محلی و آفلاین را کامل کن و لایه اتصال آینده را مستند ساز.\r\n- اگر اطلاعاتی در دسترس نیست، مقدار آن را نامشخص ثبت کن؛ حدس نزن.\r\n- از کاربر نخواه Android Studio را باز کند یا کدهای پیچیده را جابه‌جا کند، مگر آنکه یک اقدام واقعاً ضروری و با دستورالعمل بسیار ساده وجود داشته باشد.\r\n\r\nتنها در این شرایط مجاز به توقف و درخواست اجازه هستی:\r\n\r\n۱. تغییر داده عملیاتی یا Supabase.\r\n\r\n۲. تغییر مستقیم وب‌سایت زنده.\r\n\r\n۳. انتشار عمومی اطلاعات داخلی یا پژوهشی.\r\n\r\n۴. عملیات حذف، ادغام یا بازنویسی غیرقابل‌بازگشت.\r\n\r\n۵. نیاز به کلید یا دسترسی محرمانه‌ای که در اختیار تو نیست.\r\n\r\nدر سایر موارد، پیش‌فرض امن انتخاب کن و کار را ادامه بده.\r\n\r\n---\r\n\r\n## ۲۲. تعریف نهایی موفقیت پروژه\r\n\r\nپروژه زمانی موفق است که:\r\n\r\n۱. کاربر بتواند با گوشی اندرویدی نرم‌افزار را نصب و اجرا کند.\r\n\r\n۲. اطلاعات کتاب‌ها از Excel مرجع به‌درستی وارد شده باشند.\r\n\r\n۳. مشخصات کتاب‌شناختی و نسخه فیزیکی از هم تفکیک شده باشند.\r\n\r\n۴. هر نسخه فیزیکی محل قابل ردیابی داشته باشد.\r\n\r\n۵. پرونده شهدا و مشخصات مزار قابل مدیریت باشند.\r\n\r\n۶. ارتباط یک کتاب با چند شهید و چند کتاب با یک شهید قابل ثبت باشد.\r\n\r\n۷. پژوهشگر بتواند خلاصه و اطلاعات مستند را با شماره صفحه ثبت کند.\r\n\r\n۸. سامانه بتواند کتاب‌های مرتبط با شهدا را در منابع معتبر بیرونی جست‌وجو و به کارشناس پیشنهاد کند.\r\n\r\n۹. نتایج تأییدنشده از اطلاعات قطعی تفکیک شوند.\r\n\r\n۱۰. ورود صوتی فارسی با روش قابل اتکا و دارای روش جایگزین فراهم باشد.\r\n\r\n۱۱. اطلاعات در حالت آفلاینِ محلی قابل استفاده باشند.\r\n\r\n۱۲. پشتیبان‌گیری و بازیابی واقعی آزمایش شده باشند.\r\n\r\n۱۳. اطلاعات قابل انتشار به‌صورت کنترل‌شده برای وب‌سایت گلزار آماده شوند.\r\n\r\n۱۴. رابط کاربری ساده، فارسی، راست‌چین و مناسب پژوهشگر باشد.\r\n\r\n۱۵. نرم‌افزار مستند، قابل نگهداری و قابل توسعه باشد.\r\n\r\n---\r\n\r\n## ۲۳. دستور شروع عملیات\r\n\r\nاکنون بدون درخواست توضیحات تکراری از کاربر، مراحل زیر را آغاز کن:\r\n\r\n**گام اول:** تمام فایل‌ها و اسناد مرتبط در مخزن رسمی GitHub را شناسایی و مطالعه کن. وضعیت زنده `main`، شاخه‌های کاری و PRها را بررسی کن.\r\n\r\n**گام دوم:** فایل Excel مرجع را واقعاً بخوان و گزارش ممیزی ساختار و نگاشت داده بساز.\r\n\r\n**گام سوم:** بر اساس اسناد و داده‌های واقعی، معماری و مدل اطلاعاتی را نهایی کن.\r\n\r\n**گام چهارم:** Recovery Point و شاخه مستقل ایجاد کن.\r\n\r\n**گام پنجم:** نرم‌افزار PWA را در ماژول مستقل طراحی و پیاده‌سازی کن.\r\n\r\n**گام ششم:** قابلیت‌های اصلی کتابخانه، شهدا، ارتباط‌ها، پژوهش، ورود صوتی، پشتیبان و جست‌وجو را مرحله‌ای تکمیل کن.\r\n\r\n**گام هفتم:** آزمون واقعی را اجرا کن، مشکلات را رفع کن و گزارش Review ارائه بده.\r\n\r\n**گام هشتم:** یک نسخه قابل مشاهده و قابل نصب روی گوشی آماده کن و روش استفاده را به زبان ساده توضیح بده.\r\n\r\nدر اولین پاسخ پس از دریافت این دستور، فقط یک گزارش کوتاه از وضعیت واقعی مخزن، اسناد و فایل Excel ارائه کن و سپس اجرای پروژه را آغاز کن. برای انتخاب رنگ، منو، ساختار اولیه یا تصمیم‌هایی که در این دستور و اسناد تعیین شده‌اند، از کاربر اجازه یا نظرخواهی مجدد نکن.\r\n\r\n**هدف نهایی، تحویل یک نرم‌افزار واقعی و قابل استفاده برای کتابخانه و پژوهش مرکز اسناد گلزار شهدای تهران است؛ نه صرفاً ارائه طرح، نمونه تصویر، کد ناقص یا وعده توسعه در آینده.**";
const technicalDocV02Raw = "\uFEFF# سند فنی و مسیر توسعه مرکز اسناد گلزار شهدای تهران\r\n## نسخه 0.2\r\n\r\n**وضعیت:** سند فنی مرجع پروژه  \r\n**تاریخ:** ۱۴۰۵/۰۷/۱۶  \r\n**نسخه:** 0.2\r\n\r\n---\r\n\r\n## 1. هدف سند\r\n\r\nاین سند مرجع فنی و مهندسی پروژه «مرکز اسناد گلزار شهدای تهران» است.\r\n\r\nهدف آن ثبت اصول فنی، معماری، کنترل تغییر، حفاظت از داده، کنترل کیفیت، نقش فناوری و مسیر توسعه پروژه است.\r\n\r\nاین سند عمداً وارد انتخاب فناوری نهایی نمی‌شود.\r\n\r\n---\r\n\r\n## 2. اصل بنیادی معماری\r\n\r\nمرکز اسناد باید مستقل از ابزارهای توسعه و خدمات شخص ثالث طراحی شود.\r\n\r\nGitHub، Vercel، GitHub Pages یا هر ابزار مشابه می‌توانند در مرحله توسعه و آزمون استفاده شوند، اما نباید جزء الزامی زیرساخت نهایی مرکز اسناد تلقی شوند.\r\n\r\nزیرساخت نهایی باید قابلیت استقرار روی زیرساخت اختصاصی گلزار تهران، شامل سرور، ذخیره‌سازی، شبکه و پشتیبان‌گیری سازمانی را داشته باشد.\r\n\r\n**اصل قطعی:**\r\n\r\n> مرکز اسناد نباید به ابزار توسعه یا سرویس شخص ثالث وابسته باشد.\r\n\r\n---\r\n\r\n## 3. مرکز اسناد و وب‌سایت یکسان نیستند\r\n\r\nمرکز اسناد، منبع اصلی و مرجع نگهداری اطلاعات و اسناد است.\r\n\r\nوب‌سایت، لایه ارائه عمومی است.\r\n\r\nمعماری مفهومی:\r\n\r\nمرکز اسناد / Source of Truth\r\n↓\r\nدروازه انتشار\r\n↓\r\nنسخه قابل انتشار\r\n↓\r\nوب‌سایت گلزار تهران\r\n\r\nبنابراین تغییر، توقف یا تعویض وب‌سایت نباید موجب از بین رفتن یا وابستگی مرکز اسناد شود.\r\n\r\n---\r\n\r\n## 4. ماده، موجودیت مرکزی است\r\n\r\nماده می‌تواند شامل مواردی مانند:\r\n\r\n- کتاب\r\n- عکس\r\n- فیلم\r\n- فایل صوتی\r\n- سند\r\n- نامه\r\n- دست‌نوشته\r\n- شیء\r\n- پرونده\r\n- سایر اقلام آرشیوی\r\n\r\nباشد.\r\n\r\nشهید، شخص، مزار، مجموعه، منشأ، فایل و مجوز می‌توانند با ماده مرتبط باشند، اما ماده هسته اصلی آرشیو است.\r\n\r\n---\r\n\r\n## 5. منبع حقیقت\r\n\r\nبرای هر نوع اطلاعات باید مشخص باشد که مرجع اصلی آن کجاست.\r\n\r\nنمونه:\r\n\r\n- مشخصات ماده → رکورد آرشیوی\r\n- فایل دیجیتال → مخزن فایل\r\n- اطلاعات منشأ → رکورد منشأ\r\n- اطلاعات انتشار → رکورد انتشار\r\n- نتیجه بررسی → سابقه بررسی\r\n- اطلاعات عمومی منتشرشده → نسخه انتشار\r\n\r\nهیچ نسخه نمایشی یا گزارش فرعی نباید بدون قاعده جایگزین منبع حقیقت شود.\r\n\r\n---\r\n\r\n## 6. جداسازی داده، منطق و ارائه\r\n\r\nیکی از تجربه‌های مهم پروژه‌های عملیاتی قبلی این است که این سه لایه نباید بدون دلیل در هم ادغام شوند:\r\n\r\n### داده\r\nاطلاعات اصلی و سوابق آرشیوی.\r\n\r\n### منطق\r\nقواعد اعتبارسنجی، طبقه‌بندی، کنترل کیفیت، گردش کار و تصمیم‌گیری.\r\n\r\n### ارائه\r\nفرم‌ها، صفحات، گزارش‌ها، داشبورد و وب‌سایت.\r\n\r\nتغییر ظاهر نباید باعث تغییر ناخواسته داده شود.\r\n\r\n---\r\n\r\n## 7. تفکیک خواندن و نوشتن\r\n\r\nصرف اینکه یک بخش بتواند اطلاعات را بخواند، به معنی مجاز بودن آن برای تغییر اطلاعات نیست.\r\n\r\nبنابراین:\r\n\r\n- مشاهده ≠ ویرایش\r\n- تحلیل ≠ ثبت\r\n- پیشنهاد ≠ تأیید\r\n- تأیید ≠ انتشار\r\n\r\nهر عملیات نوشتن باید مسیر و مجوز مشخص داشته باشد.\r\n\r\n---\r\n\r\n## 8. کنترل کیفیت مستقل\r\n\r\nثبت اطلاعات و کنترل کیفیت دو مرحله متفاوت هستند.\r\n\r\nچرخه پایه:\r\n\r\nثبت\r\n→ بررسی\r\n→ تشخیص خطا\r\n→ اصلاح\r\n→ بررسی مجدد\r\n→ تأیید\r\n\r\nاطلاعاتی که صرفاً توسط سامانه یا AI پیشنهاد شده‌اند، نباید خودکار به عنوان اطلاعات قطعی تاریخی ثبت شوند.\r\n\r\n---\r\n\r\n## 9. تاریخچه و قابلیت ردیابی\r\n\r\nبرای تغییرات مهم باید بتوان مشخص کرد:\r\n\r\n- چه کسی تغییر را انجام داد؟\r\n- چه زمانی؟\r\n- چه چیزی تغییر کرد؟\r\n- مقدار قبلی چه بود؟\r\n- مقدار جدید چه بود؟\r\n- علت تغییر چه بود؟\r\n- چه کسی آن را بررسی یا تأیید کرد؟\r\n\r\nاصل مهم:\r\n\r\n> اطلاعات مهم مرکز اسناد باید قابل ردیابی باشند.\r\n\r\n---\r\n\r\n## 10. نسخه‌بندی\r\n\r\nدو مفهوم باید از هم جدا باشند:\r\n\r\n### نسخه فایل\r\nنسخه یک فایل دیجیتال، تصویر، PDF، صوت یا ویدئو.\r\n\r\n### نسخه اطلاعات\r\nتغییرات فراداده و اطلاعات ثبت‌شده درباره ماده.\r\n\r\nممکن است فایل تغییر نکند ولی اطلاعات توصیفی آن اصلاح شود؛ یا برعکس.\r\n\r\n---\r\n\r\n## 11. حفاظت دیجیتال\r\n\r\nبرای فایل‌های دیجیتال در طراحی نهایی باید موارد زیر پیش‌بینی شود:\r\n\r\n- پشتیبان‌گیری\r\n- کنترل سلامت فایل\r\n- ثبت مشخصات فایل\r\n- ثبت فرمت\r\n- امکان بازیابی\r\n- نگهداری نسخه‌های مهم\r\n- برنامه مهاجرت فرمت در آینده\r\n\r\nجزئیات فنی این بخش در مرحله طراحی تفصیلی تعیین خواهد شد.\r\n\r\n---\r\n\r\n## 12. نقطه بازگشت قبل از تغییر\r\n\r\nهر تغییر مهم فنی باید قبل از اجرا دارای نقطه بازگشت باشد.\r\n\r\nچرخه استاندارد پیشنهادی:\r\n\r\nRecovery / Backup\r\n→ بررسی و تشخیص\r\n→ تغییر حداقلی\r\n→ بررسی مجدد\r\n→ آزمون فنی\r\n→ بررسی نسخه و استقرار\r\n→ آزمون عملی کاربر\r\n→ تأیید نهایی\r\n\r\nاین اصل از تجربه عملی پروژه‌های نرم‌افزاری قبلی به مرکز اسناد منتقل می‌شود.\r\n\r\n---\r\n\r\n## 13. تغییر حداقلی\r\n\r\nدر تغییرات فنی نباید هم‌زمان چند بخش مستقل تغییر داده شوند مگر اینکه ضرورت آن ثابت شده باشد.\r\n\r\nقاعده:\r\n\r\n> ابتدا کوچک‌ترین تغییر مؤثر، سپس آزمون و بعد تغییر بعدی.\r\n\r\nاین روش امکان تشخیص خطا و بازگشت را افزایش می‌دهد.\r\n\r\n---\r\n\r\n## 14. تفکیک محیط‌ها\r\n\r\nدر معماری نهایی باید میان این سه وضعیت تمایز وجود داشته باشد:\r\n\r\n### توسعه\r\nمحل ساخت و تغییر.\r\n\r\n### آزمون\r\nمحل بررسی فنی و عملی.\r\n\r\n### بهره‌برداری\r\nنسخه مورد استفاده واقعی مرکز اسناد.\r\n\r\nتغییر آزمایشی نباید مستقیماً وارد محیط بهره‌برداری شود.\r\n\r\n---\r\n\r\n## 15. هوش مصنوعی\r\n\r\nهوش مصنوعی در مرکز اسناد یک **لایه کمکی مستقل** است.\r\n\r\nکاربردهای آینده می‌تواند شامل:\r\n\r\n- OCR\r\n- استخراج فراداده\r\n- پیشنهاد طبقه‌بندی\r\n- تشخیص شباهت\r\n- کشف تکرار\r\n- استخراج کلیدواژه\r\n- تبدیل گفتار به متن\r\n- خلاصه‌سازی\r\n- پیشنهاد ارتباط میان مواد\r\n- کنترل کیفیت\r\n- تهیه گزارش تحلیلی\r\n\r\nباشد.\r\n\r\nاما:\r\n\r\n> AI تحلیل و پیشنهاد می‌دهد؛ مرجع تاریخی و تصمیم نهایی انسان و رکورد تأییدشده آرشیوی است.\r\n\r\n---\r\n\r\n## 16. خطای AI نباید آرشیو را متوقف کند\r\n\r\nیکی از اصول مهم معماری این است که خرابی یا توقف AI نباید باعث ازکارافتادن مرکز اسناد شود.\r\n\r\nبنابراین:\r\n\r\nمرکز اسناد\r\n↓\r\nمستقل و قابل استفاده\r\n\r\nAI\r\n↓\r\nلایه کمکی و قابل اتصال/قطع\r\n\r\nAI نباید نقطه شکست اصلی آرشیو باشد.\r\n\r\n---\r\n\r\n## 17. پیشنهاد AI با حقیقت تاریخی یکسان نیست\r\n\r\nهر نتیجه‌ای که توسط AI تولید شود باید وضعیت آن مشخص باشد.\r\n\r\nبرای مثال:\r\n\r\n- پیشنهاد AI\r\n- بررسی‌نشده\r\n- بررسی انسانی\r\n- تأییدشده\r\n- ردشده\r\n\r\nتا زمانی که نتیجه توسط مسئول مربوط بررسی نشده، نباید به عنوان حقیقت قطعی آرشیوی تلقی شود.\r\n\r\n---\r\n\r\n## 18. حقوق و مجوزها\r\n\r\nاطلاعات مربوط به حقوق و مجوز باید از همان ابتدای ثبت ماده قابل نگهداری باشد، اما این موضوع نباید پروژه را متوقف کند.\r\n\r\nدر مرحله فعلی می‌توان وضعیت را به شکل ساده ثبت کرد:\r\n\r\n- مشخص\r\n- نامشخص\r\n- در حال بررسی\r\n- محدود\r\n- متوقف\r\n\r\nاصل مهم:\r\n\r\n> نبودن اطلاعات مجوز به معنی وجود مجوز انتشار نیست.\r\n\r\nیک ماده می‌تواند در آرشیو موجود باشد و برای استفاده داخلی قابل مدیریت باشد، اما تا روشن شدن وضعیت انتشار نباید عمومی شود.\r\n\r\n---\r\n\r\n## 19. دروازه انتشار\r\n\r\nانتشار عمومی باید مرحله‌ای مستقل از ثبت و نگهداری باشد.\r\n\r\nچرخه مفهومی:\r\n\r\nثبت ماده\r\n→ بررسی\r\n→ تعیین دسترسی\r\n→ بررسی حقوق و مجوز\r\n→ تأیید انتشار\r\n→ تولید نسخه عمومی\r\n→ انتشار\r\n\r\nدر نسخه‌های اولیه حتی می‌توان این دروازه را به صورت یک چک‌لیست انسانی اجرا کرد.\r\n\r\n---\r\n\r\n## 20. دسترسی\r\n\r\nسه مفهوم باید از هم جدا باشند:\r\n\r\n### وجود ماده\r\nماده در مرکز اسناد ثبت شده است.\r\n\r\n### دسترسی داخلی\r\nکارکنان یا پژوهشگران مجاز می‌توانند آن را ببینند.\r\n\r\n### انتشار عمومی\r\nماده برای عموم منتشر شده است.\r\n\r\nاین سه مفهوم نباید یکی فرض شوند.\r\n\r\n---\r\n\r\n## 21. نقش‌های کاربری\r\n\r\nدر طراحی نهایی باید نقش‌های کاربری از سطح دسترسی به خود ماده جدا باشند.\r\n\r\nنمونه نقش‌ها:\r\n\r\n- مدیر مرکز\r\n- مسئول آرشیو\r\n- ثبت‌کننده\r\n- کارشناس بررسی\r\n- تأییدکننده\r\n- مسئول انتشار\r\n- کاربر پژوهشی\r\n- کاربر عمومی\r\n- پشتیبان فنی\r\n\r\nجزئیات این نقش‌ها در مرحله طراحی گردش کار مشخص خواهد شد.\r\n\r\n---\r\n\r\n## 22. مستندسازی بخشی از مهندسی است\r\n\r\nگزارش فنی، گزارش روزانه، تصمیم‌های معماری، Recoveryها، تست‌ها و تاریخچه تغییرات بخشی از پروژه محسوب می‌شوند، نه کار جانبی.\r\n\r\nهر تغییر مهم باید قابل بازسازی باشد.\r\n\r\n---\r\n\r\n## 23. فناوری قبل از شناخت مسئله انتخاب نمی‌شود\r\n\r\nدر وضعیت فعلی انتخاب فناوری نهایی انجام نمی‌شود.\r\n\r\nابتدا باید مشخص شود:\r\n\r\n- چه موادی داریم؟\r\n- چه حجمی داریم؟\r\n- چه تعداد نیروی انسانی داریم؟\r\n- چه گردش کاری واقعاً قابل اجراست؟\r\n- چه نوع فایل‌هایی داریم؟\r\n- چه سطح دسترسی لازم است؟\r\n- چه زیرساختی در اختیار گلزار تهران خواهد بود؟\r\n\r\nبعد از این مرحله انتخاب فناوری انجام می‌شود.\r\n\r\n---\r\n\r\n## 24. تجربه منتقل‌شده از پروژه بهسازی\r\n\r\nاز پروژه عملیاتی سامانه بهسازی سنگ مزار چند اصل مهم به این پروژه منتقل می‌شود:\r\n\r\n1. قبل از تغییر مهم Recovery ایجاد شود.\r\n2. منبع حقیقت همیشه مشخص باشد.\r\n3. تغییرات کوچک و قابل کنترل باشند.\r\n4. آزمون فنی از آزمون واقعی کاربر جدا باشد.\r\n5. QA مستقل از ثبت اطلاعات باشد.\r\n6. نسخه توسعه با نسخه عملیاتی یکی نباشد.\r\n7. تاریخچه تغییرات حفظ شود.\r\n8. داده زنده با Snapshot اشتباه نشود.\r\n9. تحلیل و کنترل کیفیت الزاماً مجوز Write ایجاد نمی‌کند.\r\n10. AI باید لایه‌ای مستقل و کمکی باشد.\r\n11. خطای AI نباید سیستم اصلی را از کار بیندازد.\r\n12. مستندات فنی باید همراه توسعه به‌روز شوند.\r\n\r\n---\r\n\r\n## 25. تفاوت مهم با پروژه بهسازی\r\n\r\nنباید جزئیات فناوری پروژه بهسازی عیناً وارد مرکز اسناد شود.\r\n\r\nمواردی مانند:\r\n\r\n- Supabase\r\n- PostgreSQL\r\n- Vercel\r\n- GitHub Pages\r\n- Edge Function\r\n- JavaScript Frontend\r\n\r\nتصمیم‌های مربوط به پروژه دیگری هستند.\r\n\r\nآنچه به مرکز اسناد منتقل می‌شود **اصل فنی و تجربه مهندسی** است، نه الزاماً همان فناوری.\r\n\r\n---\r\n\r\n## 26. مسیر اصلی فنی مرکز اسناد\r\n\r\nمسیر فعلی پروژه:\r\n\r\nشناخت وضع موجود\r\n→ تصمیم‌های قطعی و باز\r\n→ اصول و قواعد پایه\r\n→ مدل اطلاعاتی\r\n→ گردش کار\r\n→ ثبت اولیه مواد واقعی\r\n→ انتخاب پایلوت\r\n→ اجرای MVP\r\n→ ارزیابی\r\n→ انتخاب فناوری\r\n→ طراحی سامانه\r\n→ طراحی انتشار عمومی\r\n\r\n---\r\n\r\n## 27. وضعیت فعلی\r\n\r\nدر حال حاضر:\r\n\r\n- مدل مفهومی اولیه تهیه شده است.\r\n- ماده به عنوان موجودیت مرکزی پذیرفته شده است.\r\n- Archive به عنوان Source of Truth پذیرفته شده است.\r\n- Publication Gate تعریف مفهومی شده است.\r\n- نقش AI مشخص شده است.\r\n- استقلال زیرساختی مرکز اسناد از ابزارهای توسعه قطعی شده است.\r\n- انتخاب فناوری هنوز انجام نشده است.\r\n- مسائل حقوقی باید ثبت‌پذیر باشند اما نباید مانع پیشرفت مراحل اولیه شوند.\r\n- شناخت وضع موجود مرکز اسناد هنوز مرحله بعدی اصلی است.\r\n\r\n---\r\n\r\n## 28. اصل حاکم بر ادامه پروژه\r\n\r\nمرکز اسناد نباید از ابتدا با یک نرم‌افزار خاص تعریف شود.\r\n\r\nابتدا باید مسئله، مواد واقعی، نیروی انسانی، گردش کار و نیازهای واقعی شناخته شوند.\r\n\r\nسپس مدل اطلاعاتی و گردش کار طراحی شود.\r\n\r\nبعد فناوری مناسب انتخاب شود.\r\n\r\nاصل حاکم:\r\n\r\n> «ابتدا آرشیو و فرآیند را درست تعریف می‌کنیم؛ سپس ابزار مناسب آن را انتخاب می‌کنیم.»\r\n\r\n---\r\n\r\n## 29. تاریخچه نسخه\r\n\r\n### نسخه 0.1\r\nایجاد نخستین سند فنی مرکز اسناد و ثبت اصول پایه معماری.\r\n\r\n### نسخه 0.2\r\nافزوده شد:\r\n\r\n- اصول مهندسی منتقل‌شده از پروژه بهسازی\r\n- Recovery و کنترل تغییر\r\n- کنترل کیفیت مستقل\r\n- تفکیک داده، منطق و ارائه\r\n- تفکیک Read / Write\r\n- نسخه‌بندی و تاریخچه\r\n- تفکیک محیط توسعه، آزمون و بهره‌برداری\r\n- اصول حفاظت دیجیتال\r\n- نقش مستقل و کمکی AI\r\n- استقلال زیرساختی مرکز اسناد\r\n- تفاوت اصل فنی با انتخاب فناوری\r\n\r\n---\r\n\r\n## 30. نقطه شروع بعدی\r\n\r\nمرحله بعدی همچنان:\r\n\r\n**شناخت وضع موجود مرکز اسناد — نسخه 0.1**\r\n\r\nاست.\r\n\r\nدر این مرحله باید ابتدا واقعیت موجود بررسی شود:\r\n\r\n- چه کتاب‌ها و اسنادی اکنون در اختیار مرکز است؟\r\n- در چه وضعیت فیزیکی هستند؟\r\n- کجا نگهداری می‌شوند؟\r\n- چه اطلاعاتی درباره آنها وجود دارد؟\r\n- چه فایل‌های دیجیتالی موجود است؟\r\n- چه چیزی قبلاً ثبت شده؟\r\n- چه چیزی ثبت نشده؟\r\n- چه نیروی انسانی برای کار در اختیار داریم؟\r\n- فرآیند فعلی دریافت، نگهداری و دسترسی چگونه است؟\r\n\r\nپس از این شناخت، مدل اطلاعاتی و گردش کار بر اساس واقعیت موجود اصلاح خواهند شد.\r\n\r\n---\r\n\r\n## اصل پایانی\r\n\r\nمرکز اسناد باید طوری ساخته شود که:\r\n\r\n**با تغییر نرم‌افزار از بین نرود،  \r\nبا تغییر وب‌سایت از بین نرود،  \r\nبا توقف یک سرویس خارجی متوقف نشود،  \r\nو با خطای AI آسیب نبیند.**\r\n\r\nمرجع نهایی باید خودِ آرشیو، داده تأییدشده و سوابق قابل ردیابی آن باشد.\r\n\r\n---\r\n\r\n# الحاقیه وضعیت پروژه ـ ۱۴۰۵/۰۷/۱۸\r\n\r\n## ۳۱. وضعیت اسناد مرجع\r\n\r\nدر این مرحله، متن کامل سند «اصول و قواعد پایه مرکز اسناد گلزار شهدای تهران ـ نسخه ۰٫۲» دریافت و برای تطبیق با گزارش فنی بررسی اولیه شده است.\r\n\r\nچهار سند مرجع اصلی پروژه عبارت‌اند از:\r\n\r\n۱. «پرسشنامه شناخت وضع موجود و دیدگاه مدیریت»\r\n۲. «پاسخ پرسش نامه دوم»\r\n۳. «طرح جامع مرکز اسناد گلزار شهدای تهران ۲»\r\n۴. «طرح اجرایی ایجاد و راه ۱»\r\n\r\nسند «اصول و قواعد پایه مرکز اسناد گلزار شهدای تهران ـ نسخه ۰٫۲» نیز مبنای حاکمیتی و مفهومی طراحی است و باید مستقل از گزارش فنی نگهداری شود.\r\n\r\n## ۳۲. وضعیت طرح جامع\r\n\r\nطبق اعلام کاربر، «طرح جامع مرکز اسناد گلزار شهدای تهران ۲» در وضعیت فعلی از نظر ایشان کامل است.\r\n\r\nاین طرح تا زمان دریافت نظر مدیر و اعلام اصلاحات موردنیاز، نباید به‌صورت خودکار بازنویسی یا تغییر داده شود.\r\n\r\nهر اصلاح بعدی باید مشخص، قابل ردیابی و با حفظ نسخه قبلی انجام شود.\r\n\r\n## ۳۳. وضعیت طرح اجرایی\r\n\r\nکاربر هنوز طرح «طرح اجرایی ایجاد و راه ۱» را به‌طور کامل مطالعه نکرده است.\r\n\r\nبنابراین بررسی نهایی، اصلاح و تأیید این طرح به پس از مطالعه کاربر و دریافت نظر ایشان موکول می‌شود.\r\n\r\nتا آن زمان، نباید پیشنهادهای کارشناسی به‌عنوان تصمیم قطعی کاربر یا مدیریت ثبت شوند.\r\n\r\n## ۳۴. اصول پایه مورد تأکید\r\n\r\nاصول زیر در اسناد مرجع تأکید شده‌اند و باید در ادامه طراحی حفظ شوند:\r\n\r\n- ماده، موجودیت مرکزی مرکز اسناد است؛ مرکز صرفاً بانک اطلاعاتی شهدا نیست.\r\n- آرشیو مرجع اصلی اطلاعات است و وب‌سایت لایه ارائه و انتشار محسوب می‌شود.\r\n- وجود ماده، دسترسی به آن و اجازه انتشار عمومی سه وضعیت مستقل‌اند.\r\n- ثبت اولیه به معنی پذیرش دائمی ماده در مجموعه نیست.\r\n- منشأ ماده با منبع اطلاعات درباره محتوای آن تفاوت دارد.\r\n- حقوق، مالکیت و مجوز استفاده یا انتشار باید از یکدیگر تفکیک شوند.\r\n- کنترل کیفیت باید از ثبت اطلاعات مستقل باشد.\r\n- پیشنهاد هوش مصنوعی به‌تنهایی مجوز اصلاح داده یا تأیید حقیقت تاریخی نیست.\r\n- فناوری نهایی و زیرساخت اجرایی هنوز انتخاب نشده‌اند.\r\n- تصمیم‌های مهم و تغییرات باید مستند و قابل ردیابی باشند.\r\n\r\n## ۳۵. موضوعات باز و نیازمند تعیین تکلیف\r\n\r\n۱. اختلاف دامنه موضوعی در پرسش‌نامه مدیریت و طرح جامع باید برای تصمیم‌گیری مدیریت ثبت شود؛ هیچ‌یک از دو بیان نباید خودسرانه جایگزین دیگری شود.\r\n\r\n۲. سیاست مجموعه، معیارهای پذیرش و عدم پذیرش مواد و محدوده زمانی و جغرافیایی باید در مراحل بعدی تعیین شوند.\r\n\r\n۳. مدل اطلاعاتی، گردش کار ثبت و بررسی، سیاست حقوق و دسترسی، حفاظت دیجیتال و دروازه انتشار هنوز به طراحی تفصیلی نیاز دارند.\r\n\r\n۴. نحوه اجرای نمونه اولیه چت‌بات و تفکیک دسترسی کارکنان و عموم باید در طرح اجرایی و مراحل طراحی بررسی شود.\r\n\r\n۵. وضعیت واقعی مواد، محل نگهداری، فهرست‌های موجود، وضعیت دیجیتال‌سازی، امکانات و نیروی انسانی باید از طریق شناخت وضع موجود مستند شود.\r\n\r\n## ۳۶. قاعده تفکیک تصمیم‌ها\r\n\r\nدر ادامه پروژه، هر موضوع باید در یکی از وضعیت‌های زیر ثبت شود:\r\n\r\n- تصمیم تأییدشده\r\n- پیشنهاد کارشناسی\r\n- موضوع نیازمند نظر کاربر\r\n- موضوع نیازمند تصمیم مدیریت\r\n- موضوع نیازمند بررسی حقوقی یا فنی\r\n- اقدام انجام‌نشده\r\n\r\nهیچ پیشنهاد یا موضوع باز نباید بدون تأیید لازم به‌عنوان تصمیم قطعی معرفی شود.\r\n\r\n## ۳۷. نقطه ادامه کار\r\n\r\nگام بعدی، تطبیق تفصیلی سند اصول و قواعد پایه و گزارش فنی با چهار سند مرجع و تکمیل گزارش فنی است.\r\n\r\nپس از آن، طرح جامع در وضعیت فعلی حفظ می‌شود تا نظر مدیریت دریافت شود. طرح اجرایی نیز تا زمان مطالعه کامل و اعلام نظر کاربر، وارد مرحله اصلاح نهایی نخواهد شد.\r\n\r\nپس از تکمیل گزارش‌ها، مسیر کار به شناخت وضع موجود، تعیین تصمیم‌های باز و سپس طراحی مدل اطلاعاتی و گردش کار بازمی‌گردد.\r\n\r\n**وضعیت این الحاقیه:** ثبت وضعیت پروژه و محدودیت‌های فعلی؛ به معنی تصویب نهایی تصمیم‌های باز یا تأیید نهایی همه اسناد نیست.\r\n\r\n---\r\n\r\n## به‌روزرسانی وضعیت — ۱۴۰۵/۰۷/۱۹\r\n\r\n### ۱. وضعیت برنامه‌ریزی اجرایی\r\n\r\nبرنامه‌ریزی تفصیلی چهار هفته نخست پروژه بر مبنای هفته‌های نسبی دنبال می‌شود. تاریخ شروع تقویمی تا زمان هماهنگی با مدیریت تعیین نخواهد شد؛ بااین‌حال، آماده‌سازی مقدماتی و طراحی برنامه نباید صرفاً به تعیین تاریخ شروع وابسته بماند.\r\n\r\n### ۲. وضعیت گانت چارت\r\n\r\nاصلاحات اعلام‌شده برای گانت چارت بررسی و از سوی کاربر انجام‌شده اعلام شده است. در نسخه برنامه، فعالیت «آماده‌سازی مواد پایلوت» برای هفته‌های ۶ و ۷ و فعالیت «تدوین نقشه راه مراحل بعد» برای هفته‌های ۸ و ۹ در نظر گرفته شده بود. سایر اصلاحات ردیف‌های اعلام‌شده نیز از سوی کاربر انجام‌شده گزارش شده‌اند.\r\n\r\n### ۳. برنامه چهار هفته نخست\r\n\r\nبرنامه تفصیلی باید حداقل این محورها را پوشش دهد:\r\n\r\n- هفته اول: سازمان‌دهی کار، مرور اسناد مبنا، استخراج پرسش‌ها و ابهام‌ها، تهیه الگوی سیاهه منابع و برنامه شناخت وضع موجود.\r\n- هفته دوم: شناسایی محل‌ها و دارندگان منابع، گردآوری اطلاعات اولیه و ثبت منشأ، محل نگهداری، وضعیت فیزیکی و وضعیت حقوقی منابع.\r\n- هفته سوم: تکمیل بررسی وضع موجود، کنترل کیفیت اطلاعات، تحلیل فرایندهای جاری، نیازهای اطلاعاتی و مسائل باز.\r\n- هفته چهارم: جمع‌بندی شناخت وضع موجود، تحلیل شکاف و ریسک، اولویت‌بندی اقدامات و تهیه گزارش شناخت وضع موجود و فهرست تصمیم‌های موردنیاز مدیریت.\r\n\r\n### ۴. قواعد و محدودیت‌های اجرایی\r\n\r\n- دو سند «طرح جامع مرکز اسناد گلزار شهدای تهران ۲» و «طرح اجرایی ایجاد مرکز اسناد گلزار شهدای تهران» به‌عنوان یک بسته برای بررسی و تأیید مدیریت در نظر گرفته می‌شوند.\r\n- پرسشنامه‌ها اسناد پشتیبان تدوین‌اند و نباید به‌عنوان اسناد مستقل نیازمند تأیید جداگانه مدیریت معرفی شوند.\r\n- شناسایی و ثبت اطلاعات موجود از ادعای مالکیت منابع یا اجازه انتشار آن‌ها جداست.\r\n- دریافت اصل اسناد، امانت‌گیری، تکثیر، دیجیتالی‌سازی یا انتشار باید تابع بررسی حقوقی و مجوزهای لازم باشد.\r\n- انتخاب فناوری، خرید تجهیزات و برآورد قطعی منابع باید پس از شناخت وضع موجود و بررسی نیازهای واقعی انجام شود.\r\n- هیچ آمار، هدف عددی یا تصمیم مدیریتی تأییدنشده نباید به‌عنوان واقعیت قطعی ثبت شود.\r\n\r\n### ۵. وضعیت اجرا و اقدام بعدی\r\n\r\nساخت و اجرای فایل اکسل برنامه تفصیلی هفته‌های اول تا چهارم هنوز تکمیل‌شده محسوب نمی‌شود. اقدام بعدی، تولید فایل با PowerShell در پوشه برنامه اجرایی، بررسی خروجی و سپس ثبت نتیجه واقعی در گزارش روزانه و سند فنی است.\r\n\r\nاین بخش، ثبت وضعیت و تصمیم‌های برنامه‌ریزی است؛ نه ادعای انجام بازدید میدانی، مصاحبه، فهرست‌برداری واقعی یا تأیید نهایی مدیریت.\r\n\r\n<!-- UPDATE-1405-07-20 -->\r\n\r\n---\r\n\r\n## به‌روزرسانی وضعیت پروژه ـ ۱۴۰۵/۰۷/۲۰\r\n\r\n### ۱. آماده‌سازی برنامه اجرایی چهار هفته نخست\r\n\r\nفایل «برنامه تفصیلی اجرایی مرکز اسناد - هفته ۱ تا ۴.xlsx» در پوشه برنامه اجرایی ساخته و بررسی اولیه شده است. طبق بررسی انجام‌شده، فایل دارای پنج شیت است:\r\n\r\n۱. راهنما و خلاصه\r\n۲. برنامه تفصیلی\r\n۳. برنامه هفتگی\r\n۴. تصمیم‌ها و ابهام‌ها\r\n۵. سیاهه اولیه منابع\r\n\r\n### ۲. محتوای برنامه تفصیلی\r\n\r\nبرنامه تفصیلی شامل ۴۰ فعالیت در چهار هفته است. ستون‌های برنامه، از جمله فعالیت، شرح اقدام، خروجی مورد انتظار، مسئول، اولویت، وضعیت، معیار پذیرش خروجی و کنترل کیفیت، برای هدایت و پیگیری فعالیت‌ها در نظر گرفته شده‌اند.\r\n\r\nنام مسئولان تا زمان مشخص‌شدن افراد خالی می‌ماند. وجود فعالیت در برنامه به‌معنای انجام آن نیست؛ وضعیت هر فعالیت باید بر اساس شواهد و خروجی واقعی به‌روزرسانی شود.\r\n\r\n### ۳. معیارهای پذیرش و کنترل کیفیت\r\n\r\nبرای فعالیت‌های برنامه، معیار پذیرش خروجی و کنترل کیفیت تدوین شده است تا تکمیل کار تنها بر اساس اعلام انجام فعالیت نباشد و امکان بررسی کفایت، کامل‌بودن، مستندبودن و قابلیت استفاده خروجی فراهم شود.\r\n\r\n### ۴. گردش‌کار میان شیت‌ها\r\n\r\nجدول گردش‌کار میان شیت‌ها تهیه شده است. بر اساس آن، برنامه تفصیلی محل اصلی پیگیری فعالیت‌ها و کنترل پذیرش است؛ سیاهه اولیه منابع برای ثبت منابع شناسایی‌شده به کار می‌رود؛ تصمیم‌ها و ابهام‌ها محل ثبت موارد نیازمند پیگیری یا تعیین تکلیف است؛ و برنامه هفتگی برای هدایت و جمع‌بندی پیشرفت استفاده می‌شود.\r\n\r\nثبت یک منبع به‌معنای اثبات مالکیت، اجازه دریافت اصل، تکثیر، دیجیتالی‌سازی یا انتشار آن نیست. گردش‌کار نیز به‌خودی‌خود مجوز هزینه‌کرد یا تصویب مدیریتی ایجاد نمی‌کند.\r\n\r\n### ۵. دستورالعمل استفاده از فایل\r\n\r\nمتن دستورالعمل استفاده از فایل اکسل برای ارائه به مدیریت آماده شده است. این دستورالعمل هدف، نحوه استفاده، زمان مراجعه و خروجی مورد انتظار هر شیت را توضیح می‌دهد و ارتباط میان شیت‌ها را تشریح می‌کند.\r\n\r\n### ۶. وضعیت اسناد و کنترل تغییر\r\n\r\nفایل گانت چارت اصلی و فایل اکسل برنامه اجرایی در این مرحله برای به‌روزرسانی گزارش‌ها تغییر داده نمی‌شوند. این به‌روزرسانی صرفاً وضعیت آماده‌سازی برنامه و مستندات مرتبط را ثبت می‌کند.\r\n\r\n### ۷. محدودیت‌ها و موضوعات باز\r\n\r\n- شناخت میدانی، بازدید، مصاحبه و فهرست‌برداری واقعی منابع در این گزارش انجام‌شده فرض نمی‌شوند.\r\n- تعیین نام مسئولان به مشخص‌شدن افراد موکول است.\r\n- تأیید نهایی مدیریت برای اسناد و برنامه، بدون اعلام مستند آن قطعی تلقی نمی‌شود.\r\n- تاریخ شروع تقویمی برنامه چهار هفته‌ای همچنان نیازمند تعیین تکلیف است.\r\n- انتخاب فناوری نهایی، خرید تجهیزات و تعیین قطعی نیازهای نیروی انسانی همچنان به شناخت وضع موجود وابسته است.\r\n\r\n### ۸. اقدام بعدی\r\n\r\n۱. حفظ فایل‌های اصلی و بررسی برنامه پیش از استفاده اجرایی.\r\n۲. تعیین مسئولان پس از مشخص‌شدن افراد.\r\n۳. شروع شناخت وضع موجود بر اساس مجوزها و دسترسی‌های لازم.\r\n۴. ثبت منابع و شواهد واقعی و تفکیک موارد قطعی از موارد نیازمند بررسی.\r\n۵. به‌روزرسانی وضعیت فعالیت‌ها و گزارش‌ها بر اساس نتایج مستند.\r\n\r\n**وضعیت این به‌روزرسانی:** ثبت خروجی‌های برنامه‌ریزی و مستندسازی؛ نه تأیید نهایی مدیریت و نه ادعای اجرای میدانی.\r\n\r\n---\r\n\r\n## به‌روزرسانی فنی — سازوکار پایان روز و ثبت گزارش‌ها — ۱۴۰۵/۰۷/۲۰\r\n\r\n### ۱. هدف\r\nایجاد روالی قابل پیگیری برای به‌روزرسانی گزارش روزانه و سند فنی زنده در پایان هر روز کاری و ثبت نسخه‌های مجاز در مخزن خصوصی GitHub، بدون وابستگی به یادآوری جداگانه کاربر.\r\n\r\n### ۲. منابع فعالیت\r\n**منبع الف — گفت‌وگوهای ChatGPT:** تصمیم‌ها، پیشنهادها، نتایج تحلیل، مسائل باز و اقدامات بعدی باید از طریق خلاصه ساختاریافته یا روش واردسازی مشخص ثبت شوند. دسترسی خودکار PowerShell به تمام گفت‌وگوهای حساب ChatGPT مفروض نیست و نباید ادعا شود.\r\n\r\n**منبع ب — فایل‌های محلی:** اسکریپت PowerShell می‌تواند مسیرهای مجاز پروژه، تغییرات فایل‌ها و وضعیت Git را بررسی کند. فایل‌های موقت Office و فایل‌های خارج از محدوده مجاز باید از پردازش خودکار کنار گذاشته شوند. تغییر فایل به‌تنهایی دلیل تأیید محتوایی یا تصمیم مدیریتی نیست.\r\n\r\n### ۳. چرخه پیشنهادی\r\n۱. گردآوری خلاصه فعالیت‌های گفت‌وگو و شواهد تغییرات محلی.\r\n۲. تطبیق دو منبع و مشخص‌کردن موارد ناقص یا متعارض.\r\n۳. تهیه یا به‌روزرسانی گزارش روزانه مستقل.\r\n۴. افزودن صرفاً تغییرات فنی و اجرایی معتبر به سند فنی زنده.\r\n۵. کنترل محتوا، وضعیت تصمیم‌ها، محرمانگی و مسیرهای مجاز.\r\n۶. ثبت تغییرات مجاز در Git و کنترل نتیجه push.\r\n۷. ثبت نتیجه اجرا در لاگ: موفق، موفق با اطلاعات ناقص، ناموفق یا بدون تغییر جدید.\r\n\r\n### ۴. کنترل‌ها و محدودیت‌ها\r\n- اجرای زمان‌بندی‌شده به‌تنهایی تضمین نمی‌کند که اطلاعات گفت‌وگوها دریافت یا گزارش‌ها کامل شده‌اند.\r\n- پیشنهاد کارشناسی، تصمیم تأییدشده و موضوع نیازمند بررسی باید وضعیت‌های جداگانه داشته باشند.\r\n- نبود شواهد، قطع شبکه یا شکست push نباید با گزارش موفقیت پوشانده شود.\r\n- گزارش‌های روزانه قبلی حفظ می‌شوند؛ سند فنی زنده با سابقه نسخه‌ها به‌روزرسانی می‌شود.\r\n- اسکریپت فقط مسیرهای مشخص و مجاز را خودکار ثبت می‌کند و نباید همه تغییرات مخزن را بدون بررسی وارد commit کند.\r\n- مخزن خصوصی به‌تنهایی مجوز بارگذاری هر سند یا اطلاعات حساس نیست.\r\n- GitHub جایگزین نسخه پشتیبان مستقل نیست.\r\n\r\n### ۵. وضعیت فعلی\r\nاین سازوکار در وضعیت **پیشنهاد طراحی‌شده؛ پیاده‌سازی‌نشده** قرار دارد. در این مرحله فقط طرح و محدودیت‌های آن مستند شده‌اند. اسکریپت، زمان‌بندی Windows Task Scheduler و آزمون عملی هنوز انجام نشده‌اند.\r\n\r\n### ۶. گام فنی بعدی\r\nابتدا قالب ثبت فعالیت‌ها تعریف شود؛ سپس اسکریپت PowerShell در حالت آزمایشی و بدون push خودکار ساخته و آزموده شود. فعال‌سازی زمان‌بندی و push فقط پس از بررسی خروجی آزمایشی انجام شود.\r\n\r\n\r\n---\r\n\r\n# الحاقیه فنی — تداوم کار میان دو سیستم و ثبت سوابق در GitHub — ۱۴۰۵/۰۷/۲۲\r\n\r\n## ۳۸. مسئله تداوم گفت‌وگو میان دو سیستم\r\n\r\nکاربر گزارش کرده است که هم‌زمان روی دو سیستم با ChatGPT کار می‌کند، اما در یکی از سیستم‌ها بخشی از پیام‌ها یا محتوای بعضی گفت‌وگوها نمایش داده نمی‌شود. این موضوع به‌عنوان مسئله تداوم دسترسی به سابقه کار ثبت می‌شود؛ علت فنی آن در این مرحله تشخیص داده نشده است.\r\n\r\nنباید فرض شود که نمای فعلی چت، تمام محتوای موجود در سیستم دیگر را در اختیار دارد. همچنین نباید ادعا شود که به تمام گفت‌وگوهای حساب یا فایل‌های محلی کاربر دسترسی کامل وجود دارد.\r\n\r\n## ۳۹. قاعده ادامه کار هنگام ناقص‌بودن سابقه چت\r\n\r\nبرای جلوگیری از تصمیم‌گیری بر پایه حافظه ناقص یا بازسازی حدسی:\r\n\r\n- اسناد مرجع و نسخه‌های ثبت‌شده در مخزن باید پیش از ادامه کار بررسی شوند.\r\n- اطلاعات موجود در سوابق گفت‌وگو، خلاصه‌های پروژه و اسناد GitHub باید از یکدیگر قابل تشخیص باشند.\r\n- موردی که شواهد کافی ندارد باید «نیازمند بررسی» ثبت شود، نه اینکه به‌عنوان تصمیم قطعی یا فعالیت انجام‌شده معرفی شود.\r\n- نبودن پیام در نمای یک سیستم، به‌تنهایی دلیل حذف یا فقدان آن در سابقه اصلی نیست.\r\n- گزارش‌های روزانه مستقل باقی می‌مانند و سند فنی، قواعد پایدار و تغییرات فنی/اجرایی مهم را در قالب الحاقیه ثبت می‌کند.\r\n\r\n## ۴۰. وضعیت مخزن و ثبت گزارش‌ها در این نوبت\r\n\r\nدر تاریخ ۱۴۰۵/۰۷/۲۲ مخزن خصوصی `forog1980-star/markaz-asnad-shohada` و شاخه `main` بررسی شد. گزارش روزانه موجود تا ۱۴۰۵/۰۷/۲۰ و سند «سند فنی و مسیر توسعه مرکز اسناد — نسخه ۰٫۲» خوانده شدند.\r\n\r\nگزارش روزانه تاریخ ۱۴۰۵/۰۷/۲۲ به‌صورت فایل مستقل ثبت شد و این الحاقیه به سند فنی افزوده شد. این تغییرات از طریق اتصال GitHub انجام شده‌اند؛ در این نوبت، همگام‌سازی پوشه محلی کاربر با مخزن یا تغییر فایل‌های رایانه کاربر بررسی و تأیید نشده است.\r\n\r\n## ۴۱. مرز میان ثبت مستقیم و خودکارسازی محلی\r\n\r\nثبت مستقیم فایل در GitHub از طریق اتصال موجود با اجرای اسکریپت PowerShell در رایانه کاربر یکسان نیست. تا زمانی که اسکریپت محلی، مسیرهای مجاز، کنترل محرمانگی، سازوکار پشتیبان، آزمون و نتیجه push به‌طور واقعی اجرا و بررسی نشده‌اند، خودکارسازی محلی همچنان «پیاده‌سازی‌نشده» محسوب می‌شود.\r\n\r\n## ۴۲. اقدامات فنی بعدی\r\n\r\n۱. در صورت نیاز، مشکل نمایش چت در هر دو سیستم جداگانه عیب‌یابی شود؛ علت آن فعلاً نامشخص است.\r\n\r\n۲. روش تداوم کار بر مبنای اسناد مرجع و گزارش‌های نسخه‌بندی‌شده حفظ شود.\r\n\r\n۳. اگر قرار است ثبت گزارش‌ها خودکار شود، ابتدا نمونه آزمایشی بدون push ساخته و خروجی آن بازبینی شود؛ سپس فعال‌سازی زمان‌بندی و ارسال فقط پس از آزمون موفق انجام شود.\r\n\r\n۴. هیچ فعالیت میدانی، تصمیم مدیریتی یا رفع اشکال فنی بدون شاهد مناسب در گزارش‌ها قطعی ثبت نشود.\r\n\r\n**وضعیت الحاقیه:** ثبت مسئله و روال مستندسازی؛ علت مشکل چت و رفع آن هنوز تعیین نشده است.\r\n\r\n\r\n---\r\n\r\n# به‌روزرسانی فنی — انتقال از برنامه‌ریزی به سامان‌دهی اجرایی کتابخانه — ۱۴۰۵/۰۷/۲۳\r\n\r\n## ۴۳. مبنای این به‌روزرسانی و وضعیت شواهد\r\n\r\nاین بخش بر پایه متن نامه ارسال‌شده به مدیریت، پیوست اجرایی آن، پاسخ‌های اعلام‌شده مدیریت به سؤال‌های ۱ تا ۶، توضیحات تکمیلی کاربر و «طرح جامع پیشنهادی مرکز اسناد گلزار شهدای تهران ـ نسخه پیشنهادی ۰٫۱» برای جلسه فنی تنظیم شده است.\r\n\r\nاین الحاقیه، ثبت وضعیت و برنامه پیشنهادی کار است؛ به‌معنای انجام فهرست‌برداری میدانی، شماره‌گذاری کتاب‌ها، استخراج کامل مطالب یا تأیید نهایی مدل نرم‌افزار نیست.\r\n\r\n## ۴۴. تغییر اولویت اجرایی\r\n\r\nاولویت نزدیک پروژه از برنامه‌ریزی کلی به دو مسیر موازی اما مستقل منتقل می‌شود:\r\n\r\n۱. **مسیر فوری و عملیاتی:** سامان‌دهی کتاب‌ها و آثار مکتوبی که اکنون در مرکز موجودند؛ ثبت شناسه، مشخصات، موضوع، محل نگهداری و ارتباط‌های مستند با شهدا؛ سپس ثبت گزیده‌های قابل استناد با ارجاع دقیق.\r\n\r\n۲. **مسیر فنی موازی:** آماده‌سازی جلسه با مسئولان برنامه‌نویسی برای انتقال نیازها، بررسی گردش کار و تعیین شیوه اتصال آینده مرکز اسناد به وب‌سایت. جلسه فنی نباید به انتخاب شتاب‌زده فناوری یا نرم‌افزار منجر شود.\r\n\r\nاولویت اجرایی فعلی، مسیر اول است. مسیر دوم باید از نیازهای واقعی کتابخانه و نمونه‌های عملی آن تغذیه شود.\r\n\r\n## ۴۵. وضعیت فعلی کتابخانه بر اساس گزارش کاربر\r\n\r\n- حدود ۵۰۰ کتاب در محل موجود است و قبلاً در شش دسته موضوعی قرار گرفته‌اند.\r\n- این کتاب‌ها هنوز شماره‌گذاری/شناسه‌گذاری یکتای نهایی نشده‌اند.\r\n- برای بخشی از کتاب‌ها، نام شهدا یا ارتباط‌های احتمالی شناسایی شده است؛ این اطلاعات باید هنگام ثبت به‌عنوان «اولیه/نیازمند راستی‌آزمایی» از روابط تأییدشده جدا شوند.\r\n- عنوان حدود ۴۰۰ کتاب دیگر استخراج شده، اما کتاب‌های فیزیکی هنوز تحویل نشده‌اند. تا زمان دریافت واقعی، آن‌ها در برنامه ثبت جداگانه «عنوان‌های مورد انتظار/تحویل‌نشده» باقی می‌مانند و در شمار موجودی فیزیکی یا آمار کتاب‌های ثبت‌شده و قفسه‌بندی‌شده وارد نمی‌شوند.\r\n- این وضعیت از توضیح کاربر ثبت شده و در این نوبت، شمارش فیزیکی مستقل یا بررسی تک‌تک کتاب‌ها انجام نشده است.\r\n\r\n## ۴۶. پاسخ‌های مدیریت که فعلاً قابل ثبت‌اند\r\n\r\n| سؤال | پاسخ اعلام‌شده | وضعیت ثبت |\r\n|---|---|---|\r\n| ۱. مرجع اطلاعات هویتی شهدا | گزینه ب: اطلاعات پایه شهدا در مرکز اسناد نیز ثبت و نگهداری شود و با سامانه فعلی ارتباط داشته باشد | پاسخ انتخابی مدیریت؛ جزئیات اتصال نیازمند طراحی فنی |\r\n| ۲. شناسه اختصاصی شهید | گزینه الف علامت خورده، اما توضیح مدیریت: «باید در این مورد در جلسه فنی سایت صحبت شود» | **تصمیم نهایی نیست؛ موضوع جلسه فنی** |\r\n| ۳. دامنه اولیه منابع | گزینه الف: ابتدا کتاب‌ها، مکتوبات، خاطرات و اسناد متنی | اولویت آغازین ثبت‌شده |\r\n| ۴. ثبت مطالب استخراج‌شده | هر دو گزینه الف و ب: مشخصات منبع و کلیدواژه‌ها، و نیز گزیده‌های مهم همراه با صفحه/نشانی دقیق | هر دو روش در مدل کار پیش‌بینی شوند؛ حجم و ضوابط انتشار جداگانه تعیین شود |\r\n| ۵. اولویت سامان‌دهی | گزینه الف: ابتدا کتاب‌ها و مکتوبات به‌طور کامل سامان‌دهی و ثبت شوند، سپس سایر منابع | اولویت اجرایی ثبت‌شده |\r\n| ۶. دسته‌بندی کتاب‌ها | گزینه الف: حفظ دسته‌بندی فعلی شش‌گانه و تعریف کد داخلی | دسته‌بندی فعلی حفظ شود؛ ساختار شناسه‌ها جداگانه نهایی شود |\r\n\r\nمدیریت اعلام کرده است که برای سؤال‌های دیگر قبلاً پاسخ داده است. متن دقیق پاسخ‌های قبلی سؤال‌های ۷ تا ۱۳ در گفت‌وگوی فعلی بازنویسی نشده؛ بنابراین قبل از ثبت جزئیات آن‌ها به‌عنوان پاسخ قطعی، باید با سند «پاسخ پرسش‌نامه دوم» و سایر اسناد مرجع تطبیق داده شوند.\r\n\r\n## ۴۷. دسته‌بندی کتابخانه و اصول شناسه‌گذاری\r\n\r\nدسته‌بندی شش‌گانه موجود باید حفظ شود:\r\n\r\n- **R — روایت و خاطرات**\r\n- **A — ادبیات و هنر**\r\n- **H — تاریخ و اسناد**\r\n- **P — پژوهش و تحلیل**\r\n- **K — کودک و نوجوان**\r\n- **M — متفرقه و متنوع**\r\n\r\nدر گفت‌وگوهای قبلی، رویکرد «کدگذاری داخلی اختصاصی با الهام از منطق رده‌بندی کتابخانه‌ای» و نمونه پیشوندهای کوتاه **RAV / HON / TAR / PAJ / KOD / MOT** مطرح شده است. همچنین نمونه‌هایی مانند شناسه ثبت **GS-L-000001**، شناسه نمونه شهید **GSA-P-000001** و کد محل **Q01-S02** بررسی شده‌اند. این رشته‌ها در این مرحله نمونه‌اند و نباید بدون تأیید نهایی به‌عنوان کدهای قطعی روی همه کتاب‌ها نصب شوند.\r\n\r\nاصول پایدار عبارت‌اند از:\r\n\r\n۱. شناسه اثر/رکورد کتاب‌شناختی با شناسه هر نسخه فیزیکی یکی نیست؛ چند نسخه از یک عنوان باید بتوانند زیر یک اثر ثبت شوند و هر نسخه شناسه مستقل داشته باشد.\r\n\r\n۲. کد دسته‌بندی موضوعی، شناسه اثر، شناسه نسخه فیزیکی و کد محل نگهداری چهار مفهوم جدا هستند.\r\n\r\n۳. جابه‌جایی کتاب به قفسه دیگر نباید شناسه پایدار نسخه را تغییر دهد.\r\n\r\n۴. محل نگهداری باید ساختاریافته و قابل بازیابی باشد. ساختار گزارش‌شده فعلی شامل چهار قفسه با شش طبقه برای هر قفسه است؛ کدگذاری نهایی قفسه/طبقه باید پس از بررسی وضعیت واقعی محل تأیید شود.\r\n\r\n۵. پیش از برچسب‌گذاری انبوه، یک نمونه کوچک از هر شش دسته ثبت و آزمایش شود؛ سپس قالب شناسه و محل، پس از کنترل، برای کل موجودی به کار رود.\r\n\r\n## ۴۸. گردش کار پیشنهادی برای ۵۰۰ کتاب موجود\r\n\r\n### گام ۱ — تثبیت موجودی اولیه\r\n\r\nبرای هر قلم موجود، عنوان روی جلد/صفحه عنوان، پدیدآورنده، ناشر، سال/نوبت چاپ در صورت وجود، دسته فعلی، تعداد نسخه‌های فیزیکی، وضعیت ظاهری و محل فعلی ثبت شود. موارد نامعلوم با مقدار صریح «نامشخص/نیازمند بررسی» علامت بخورند؛ اطلاعات حدسی به‌عنوان واقعیت وارد نشوند.\r\n\r\n### گام ۲ — تفکیک اثر و نسخه فیزیکی\r\n\r\nبرای هر عنوان، رکورد اثر یا مشخصات کتاب‌شناختی ساخته شود و برای هر نسخه موجود، رکورد مستقل شامل شناسه نسخه، محل نگهداری، وضعیت و منشأ دریافت ایجاد شود. در صورت وجود شماره ثبت قبلی، آن شماره حفظ و به رکورد جدید متصل شود.\r\n\r\n### گام ۳ — ثبت دسته و محل\r\n\r\nدسته شش‌گانه فعلی بدون تغییر حفظ شود. کد دسته، شناسه پایدار و کد محل در فیلدهای مستقل ثبت شوند. پیش از نهایی‌کردن کد محل، چهار قفسه و شش طبقه هرکدام در محل واقعی بررسی و نقشه ساده محل تهیه شود.\r\n\r\n### گام ۴ — ارتباط با شهدا\r\n\r\nنام شهدا و اشاره‌های شناخته‌شده برای هر کتاب به‌عنوان ارتباط اولیه وارد شوند. تطبیق نام‌ها با رکورد هویتی شهید، نام‌های جایگزین و شناسه سامانه موجود باید با کنترل انسانی انجام شود. تصمیم درباره شناسه یکتای شهید و مرجع نهایی آن همچنان به جلسه فنی موکول است.\r\n\r\n### گام ۵ — استخراج گزیده‌ها و مطالب مستند\r\n\r\nبرای هر مطلب انتخاب‌شده، متن یا شرح، شناسه منبع، جلد/صفحه/بند دقیق، شهید یا موضوع مرتبط، نوع ارتباط، استخراج‌کننده و وضعیت بررسی ثبت شود. «ذکر نام»، «موضوع اصلی اثر» و «خاطره یا گزیده مستقیم» نباید یک نوع ارتباط تلقی شوند. ثبت مشخصات کتاب و کلیدواژه‌ها جایگزین ثبت گزیده‌های مهم نیست؛ طبق پاسخ مدیریت، هر دو روش باید پشتیبانی شوند.\r\n\r\n### گام ۶ — کنترل کیفیت و گزارش پیشرفت\r\n\r\nموارد تکراری، اطلاعات ناقص، نام‌های مبهم، ارجاعات بدون صفحه و اختلاف میان منابع جداگانه علامت‌گذاری شوند. آمار «کتاب فیزیکی دریافت‌شده»، «اثر ثبت‌شده»، «نسخه شماره‌گذاری‌شده»، «قفسه‌بندی‌شده»، «ارتباط شهید بررسی‌شده» و «گزیده ثبت‌شده» جدا گزارش شوند.\r\n\r\n### گام ۷ — انتشار کنترل‌شده\r\n\r\nانتقال اطلاعات به وب‌سایت، مرحله‌ای جدا از ثبت داخلی است. تنها داده و محتوایی که از نظر حقوق استفاده، محدودیت دسترسی و تأیید مسئول مجاز شده است می‌تواند از مسیر کنترل‌شده انتشار به سایت برسد. ثبت یا استخراج متن به‌خودی‌خود اجازه انتشار عمومی ایجاد نمی‌کند.\r\n\r\n## ۴۹. پایلوت پیش از اجرای کامل\r\n\r\nپیشنهاد اجرایی این است که ابتدا یک نمونه کوچک و نماینده از هر شش دسته ثبت شود؛ برای مثال دو عنوان از هر دسته، در مجموع ۱۲ عنوان. در صورت وجود چند نسخه از یک عنوان، دست‌کم یک مورد چندنسخه‌ای نیز در نمونه گنجانده شود. این پایلوت باید موارد زیر را آزمایش کند:\r\n\r\n- کفایت فیلدهای کتاب‌شناختی و ثبت نسخه فیزیکی؛\r\n- خوانایی و یکتایی شناسه‌ها و کد محل؛\r\n- قابلیت ثبت نام شهید و نام جایگزین؛\r\n- ثبت ارتباط مستقیم/غیرمستقیم و گزیده همراه با صفحه؛\r\n- امکان پیدا کردن کتاب از روی عنوان، دسته، محل و شهید؛\r\n- ثبت جداگانه وضعیت بررسی و مجوز انتشار.\r\n\r\nپس از رفع ایرادهای نمونه، ثبت انبوه موجودی آغاز شود. عدد ۱۲ پیشنهاد روش کار است، نه سهمیه یا تصمیم تأییدشده مدیریت.\r\n\r\n## ۵۰. نیازهای جلسه فنی سایت\r\n\r\nدر جلسه با مسئولان برنامه‌نویسی، ابتدا سناریوی واقعی کتابخانه ارائه شود: یک اثر، چند نسخه فیزیکی، چند شهید مرتبط، یک گزیده با ارجاع صفحه و یک فایل دیجیتال. سپس درباره این موارد گفت‌وگو شود:\r\n\r\n۱. مرجع شناسه و اطلاعات پایه شهدا و روش اتصال به سامانه فعلی؛\r\n۲. تفکیک اثر، نسخه فیزیکی، فایل دیجیتال و محتوای استخراج‌شده؛\r\n۳. فرم ثبت، جست‌وجو، گزارش‌گیری و کنترل کیفیت؛\r\n۴. گردش کار ثبت، بررسی، تأیید و انتشار؛\r\n۵. روش تبادل داده با سایت و جلوگیری از دسترسی مستقیم سایت عمومی به آرشیو داخلی؛\r\n۶. مقایسه عملی نرم‌افزار آماده، توسعه یک محصول موجود و طراحی اختصاصی؛\r\n۷. خروجی قابل انتقال، امنیت، پشتیبان‌گیری و برآورد مرحله‌ای هزینه و زمان.\r\n\r\nهیچ فناوری، محصول یا مدل نهایی پایگاه داده در این الحاقیه انتخاب نشده است.\r\n\r\n## ۵۱. موارد باز و اقدام‌های بعدی\r\n\r\n- بازیابی/تطبیق دقیق پاسخ‌های قبلی مدیریت به سؤال‌های ۷ تا ۱۳؛\r\n- نهایی‌کردن معنای هر شناسه نمونه و قاعده شماره‌گذاری نسخه فیزیکی؛\r\n- بررسی واقعی چیدمان چهار قفسه و شش طبقه؛\r\n- تعیین مرجع هویت شهدا و روش اتصال به سامانه فعلی در جلسه فنی؛\r\n- تعیین شیوه ثبت حقوق و مجوز استفاده از کتاب‌ها و گزیده‌ها؛\r\n- تعیین مسیر تأیید محتوای قابل انتشار در سایت؛\r\n- طراحی فرم/فایل ثبت آزمایشی و معیارهای کنترل کیفیت؛\r\n- اجرای واقعی پایلوت و سپس شماره‌گذاری انبوه، با ثبت نتایج مستند.\r\n\r\n**وضعیت در پایان این به‌روزرسانی:** برنامه اجرایی کتابخانه و نیازهای جلسه فنی مستند شده‌اند؛ شماره‌گذاری، فهرست‌برداری واقعی، استخراج نظام‌مند مطالب، اجرای پایلوت و انتشار سایت هنوز انجام‌شده تلقی نمی‌شوند.\r\n";
const executiveAndCodingDocRaw = "PS C:\\Windows\\System32> $path = \"C:\\مهدی\\گلزار\\مرکز اسناد\"\r\nPS C:\\Windows\\System32> $targets = @(\r\n>>   \"\\نرم‌افزار کتابخانه\\README.md\",\r\n>>   \"\\نرم‌افزار کتابخانه\\برچسب‌های قفسه و طبقه.md\",\r\n>>   \"\\نرم‌افزار کتابخانه\\گزارش تغییرات.md\",\r\n>>   \"\\نرم‌افزار کتابخانه\\index.html\",\r\n>>   \"\\کتابخانه\\گزارش‌ها\\نقطه شروع برنامه‌نویسی ثبت سریع موجودی فیزیکی کتابخانه - نسخه 0.1.md\",\r\n>>   \"\\کتابخانه\\گزارش‌ها\\گزارش فنی ابزار تطبیق فیزیکی کتابخانه - نسخه 0.1.md\",\r\n>>   \"\\کتابخانه\\گزارش‌ها\\گزارش روزانه کتابخانه - 1405-08-03.md\",\r\n>>   \"\\کتابخانه\\گزارش‌ها\\گزارش روزانه کتابخانه - 1405-08-04.md\",\r\n>>   \"\\نرم‌افزار ثبت کتاب‌ها و شهدا\\docs\\طرح-اجرایی-نسخه-اول-برنامه-کتابخانه-نسخه-۰٫۱.md\",\r\n>>   \"\\نرم‌افزار ثبت کتاب‌ها و شهدا\\docs\\طرح-کدگذاری-و-فیلدهای-فهرست-کتابخانه-نسخه-۰٫۱.md\",\r\n>>   \"\\مستندات\\پروتکل-تداوم-کار-و-تفکیک-مسیرهای-کتابخانه.md\",\r\n>>   \"\\مستندات\\ثبت تکمیلی دیدگاه‌های مدیریت و وضعیت کتابخانه - 1405-07-28.md\"\r\n>> )\r\nPS C:\\Windows\\System32>\r\nPS C:\\Windows\\System32> foreach ($rel in $targets) {\r\n>>   $full = $path + $rel\r\n>>   if (Test-Path $full) {\r\n>>     Write-Host \"`r`n================ FILE: $rel ================\" -ForegroundColor Yellow\r\n>>     Get-Content $full -Encoding UTF8 -ErrorAction SilentlyContinue\r\n>>   }\r\n>> }\r\n\r\n================ FILE: \\نرم‌افزار کتابخانه\\README.md ================\r\n# نرم‌افزار کتابخانه — ابزار موقت تطبیق فیزیکی\r\n\r\n## هدف\r\nابزار وب مستقل و موقت برای استفاده با یک گوشی اندرویدی و یک ثبت‌کننده. در این مرحله فقط اطلاعات پایه کتاب، موضوع کلی، محل فیزیکی و توضیح کوتاه ثبت می‌شود. ارتباط کتاب‌ها با اسامی شهدا در مرحله بعد طراحی خواهد شد.\r\n\r\n## اجرای سریع\r\n1. فایل `index.html` را در مرورگر باز کنید؛ برای استفاده از گوشی، نسخه میزبانی‌شده باید از طریق HTTPS در دسترس باشد.\r\n2. فایل `کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx` را از مخزن دریافت و در گوشی انتخاب کنید.\r\n3. شیت حاوی عنوان کتاب را انتخاب کنید؛ شیت «فهرست کتاب‌ها» یا «عنوان کتاب‌ها» را مطابق نام واقعی فایل انتخاب کنید.\r\n4. ستون عنوان را اجباری و ستون‌های نویسنده، ناشر و سال چاپ را در صورت وجود تعیین کنید.\r\n5. عنوان را جست‌وجو کنید، نتیجه درست را انتخاب کنید، موضوع، قفسه، طبقه، وضعیت مشاهده و توضیح را وارد و ذخیره کنید.\r\n6. پایان هر نوبت کاری «پشتیبان JSON» و «خروجی CSV» بگیرید و فایل‌ها را در محل امن نگه دارید.\r\n\r\n## شناسه محل فیزیکی مورد توافق\r\nچهار قفسه عملیاتی:\r\n- `SH-01`\r\n- `SH-02`\r\n- `SH-03`\r\n- `SH-04`\r\n\r\nهر قفسه شش طبقه دارد که از بالا به پایین با `T01` تا `T06` مشخص می‌شوند. قالب نشانی کامل محل:\r\n- `SH-01-T01`\r\n- `SH-03-T04`\r\n\r\nقفسه‌های `SH-01` و `SH-02` برای گروه R (روایت و خاطرات) در نظر گرفته شده‌اند. گروه‌های A، H، P، K و M در `SH-03` و `SH-04` قرار می‌گیرند؛ جانمایی نهایی این گروه‌ها در طبقات هنوز باید در محل تثبیت شود. قفسه پنجم فعلاً خارج از نقشه عملیاتی این ابزار است.\r\n\r\n## اطلاعات ثبت‌شده\r\nعنوان، نویسنده، ناشر، سال چاپ، موضوع، قفسه، طبقه، کد محل، وضعیت مشاهده، توضیح کوتاه و زمان آخرین ثبت.\r\n\r\n## حفاظت از داده\r\n- فایل اکسل در مرورگر پردازش می‌شود و به سرور ارسال نمی‌شود.\r\n- اطلاعات ثبت‌شده در حافظه مرورگر همان دستگاه نگهداری می‌شود؛ داده مرورگر را پاک نکنید.\r\n- هر نوبت کاری از JSON پشتیبان و CSV خروجی بگیرید.\r\n- برای بازگرداندن ثبت‌ها از بخش «بازیابی/ادغام پشتیبان JSON» استفاده کنید؛ کلیدهای تکراری عمداً بازنویسی نمی‌شوند.\r\n- از «خروجی تغییرات برای بررسی Excel» برای تهیه فهرست تغییرات پیشنهادی استفاده کنید. این خروجی فقط پیشنهاد است و فایل Excel را تغییر نمی‌دهد.\r\n- این ابزار به Supabase یا نرم‌افزار اصلی متصل نیست و هیچ داده‌ای در آن‌ها تغییر نمی‌دهد.\r\n- قبل از استفاده انبوه، با ۲۰ کتاب واقعی آزمایش کنید.\r\n- این ابزار شناسه پایدار نهایی کتاب تولید نمی‌کند؛ کلیدهای ثبت موقت صرفاً برای پیگیری‌اند و ارتباط شهید–کتاب را فعلاً ثبت نمی‌کند.\r\n\r\n## وضعیت نسخه ۰٫۲ — ۱۴۰۵/۰۸/۰۴\r\n- افزوده شد: بازیابی/ادغام پشتیبان JSON با اعتبارسنجی ساختار و بدون بازنویسی کلیدهای موجود.\r\n- افزوده شد: خروجی مستقل «تغییرات پیشنهادی برای بررسی Excel»؛ فایل مرجع همچنان دست‌نخورده می‌ماند.\r\n- افزوده شد: کنترل اجباری انتخاب موضوع، قفسه و طبقه برای ثبت کتابی که وضعیت آن «دیده شد» است.\r\n- بررسی ایستای نحوی JavaScript انجام شد و موفق بود؛ آزمون واقعی گوشی، بازیابی در مرورگر واقعی و تطبیق با فایل Excel هنوز انجام نشده‌اند.\r\n\r\n## محدودیت مهم\r\nبرای خواندن فایل Excel از کتابخانه JavaScript با CDN استفاده می‌شود؛ در نخستین بارگذاری اتصال اینترنت لازم است. فایل اصلی به هیچ‌وجه تغییر نمی‌کند. استقرار آنلاین و آزمون واقعی در گوشی هنوز تأیید نشده است.\r\n\r\n================ FILE: \\نرم‌افزار کتابخانه\\برچسب‌های قفسه و طبقه.md ================\r\n# برچسب‌های قفسه و طبقه — مرکز اسناد\r\n\r\n**عنوان بخش:** نرم‌افزار کتابخانه / سامان‌دهی فیزیکی کتابخانه\r\n**قاعده طبقه‌بندی:** قفسه‌ها با شناسه مستقل و طبقات از بالا به پایین شماره‌گذاری می‌شوند.\r\n\r\n## قفسه‌های عملیاتی\r\n- `SH-01`\r\n- `SH-02`\r\n- `SH-03`\r\n- `SH-04`\r\n\r\n## طبقات هر قفسه\r\n- `T01` — طبقه اول از بالا\r\n- `T02` — طبقه دوم از بالا\r\n- `T03` — طبقه سوم از بالا\r\n- `T04` — طبقه چهارم از بالا\r\n- `T05` — طبقه پنجم از بالا\r\n- `T06` — طبقه ششم از بالا\r\n\r\n## قالب نشانی کامل\r\nنمونه: **`SH-01-T01`**؛ یعنی قفسه SH-01، طبقه اول از بالا.\r\n\r\n## جانمایی گروه‌های موضوعی\r\n- قفسه‌های `SH-01` و `SH-02`: گروه R — روایت و خاطرات.\r\n- قفسه‌های `SH-03` و `SH-04`: گروه‌های A، H، P، K و M.\r\n\r\nجانمایی نهایی گروه‌های A، H، P، K و M در طبقات هنوز تأیید نشده و باید هنگام چیدمان فیزیکی مشخص شود. قفسه پنجم در حال حاضر خارج از نقشه عملیاتی این ابزار است.\r\n\r\n================ FILE: \\نرم‌افزار کتابخانه\\گزارش تغییرات.md ================\r\n# گزارش تغییرات — نرم‌افزار کتابخانه\r\n\r\n## ۱۴۰۵/۰۸/۰۳ — نسخه آزمایشی ۰٫۱\r\n- ایجاد ابزار مستقل برای تطبیق فیزیکی کتاب‌ها با یک گوشی اندرویدی و یک کاربر.\r\n- افزودن بارگذاری فایل Excel، انتخاب شیت و نگاشت ستون عنوان/نویسنده/ناشر/سال.\r\n- افزودن جست‌وجوی عنوان، ثبت موضوع، محل (قفسه و طبقه)، وضعیت مشاهده و توضیحات.\r\n- افزودن ثبت جداگانه کتاب‌های دیده‌شده‌ای که در فهرست مرجع پیدا نمی‌شوند.\r\n- افزودن خروجی CSV و پشتیبان JSON.\r\n- فایل مرجع و Supabase دست‌نخورده می‌مانند.\r\n- وضعیت: کد اولیه ثبت شده؛ آزمون واقعی در گوشی و میزبانی وب هنوز انجام نشده است.\r\n\r\n================ FILE: \\نرم‌افزار کتابخانه\\index.html ================\r\n<!doctype html>\r\n<html lang=\"fa\" dir=\"rtl\">\r\n<head>\r\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\r\n<meta name=\"theme-color\" content=\"#1f4e79\"><title>نرم‌افزار کتابخانه | مرکز اسناد</title>\r\n<style>\r\n:root{font-family:Tahoma,\"Segoe UI\",sans-serif;color:#162b3b;background:#f2f5f8}*{box-sizing:border-box}body{margin:0}header{background:#1f4e79;color:#fff;padding:17px 15px}h1{font-size:1.18rem;margin:0 0 6px}header p{margin:0;font-size:.84rem;line-height:1.8}main{max-width:860px;margin:auto;padding:12px;display:grid;gap:12px}.card{background:#fff;border:1px solid #dce4eb;border-radius:13px;padding:13px}h2{font-size:1rem;margin:0 0 10px}.hint{font-size:.8rem;line-height:1.8;color:#53697b}label{display:block;font-size:.82rem;font-weight:700;margin:9px 0 5px}input,select,textarea,button{width:100%;font:inherit;border:1px solid #c4d0db;border-radius:9px;padding:11px;background:white;color:#172b3a}textarea{min-height:62px}button{border:0;background:#1f4e79;color:white;font-weight:700;margin-top:8px;cursor:pointer}button.alt{background:#e8eef4;color:#1f4e79;border:1px solid #ccd8e2}button.warn{background:#8a3333}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.full{grid-column:1/-1}.status{background:#edf4fa;border-radius:9px;padding:10px;font-size:.82rem;line-height:1.8;margin-top:8px}.results{display:grid;gap:7px;margin-top:8px}.result{text-align:right;background:white;color:#183147;border:1px solid #ccd8e2;border-radius:9px;padding:10px;margin:0}.result strong,.result small{display:block;line-height:1.7}.result small{font-weight:400;color:#5a6d7c}.result.chosen{border:2px solid #1f4e79;background:#f2f7fb}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.stat{text-align:center;background:#edf3f7;border-radius:9px;padding:9px}.stat b{display:block;font-size:1.1rem}.stat span{font-size:.72rem;color:#526777}.hidden{display:none!important}.tag{display:inline-block;padding:3px 7px;border-radius:20px;background:#e9eff5;font-size:.74rem;margin:2px}.foot{font-size:.73rem;line-height:1.8;color:#617383}@media(min-width:700px){main{grid-template-columns:1fr 1fr}.full{grid-column:1/-1}}\r\n</style>\r\n<script src=\"https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js\"><\/script>\r\n</head>\r\n<body>\r\n<header><h1>نرم‌افزار کتابخانه</h1><p>مرکز اسناد گلزار شهدای تهران · ابزار موقت تطبیق فیزیکی کتاب‌ها</p></header>\r\n<main>\r\n<section class=\"card full\">\r\n<h2>۱. ورود فهرست اکسل</h2>\r\n<p class=\"hint\">فایل اکسل از داخل همین گوشی انتخاب می‌شود و به سرور ارسال نمی‌شود. پس از انتخاب فایل، شیت مربوط به عنوان کتاب و ستون‌های موجود را مشخص کنید. فایل مرجع اصلی دست‌نخورده می‌ماند.</p>\r\n<label for=\"workbook\">انتخاب فایل Excel</label><input id=\"workbook\" type=\"file\" accept=\".xlsx,.xls,.csv\">\r\n<div id=\"loadMsg\" class=\"status\">ابتدا فایل فهرست کاری کتابخانه را انتخاب کنید.</div>\r\n<div id=\"sheetArea\" class=\"hidden\"><label for=\"sheet\">شیت مورد استفاده</label><select id=\"sheet\"></select><button id=\"loadSheet\">بارگذاری شیت انتخاب‌شده</button></div>\r\n<div id=\"mapArea\" class=\"grid hidden\">\r\n<div class=\"full\"><label for=\"titleCol\">ستون عنوان کتاب (ضروری)</label><select id=\"titleCol\"></select></div>\r\n<div><label for=\"authorCol\">نویسنده</label><select id=\"authorCol\"></select></div>\r\n<div><label for=\"publisherCol\">ناشر</label><select id=\"publisherCol\"></select></div>\r\n<div><label for=\"yearCol\">سال چاپ</label><select id=\"yearCol\"></select></div>\r\n<button id=\"applyMap\" class=\"full\">تأیید ستون‌ها و شروع جست‌وجو</button></div>\r\n</section>\r\n<section class=\"card full\"><h2>۲. جست‌وجوی عنوان کتاب</h2>\r\n<label for=\"search\">عنوان یا بخشی از عنوان</label><input id=\"search\" placeholder=\"چند واژه از عنوان کتاب را بنویسید\" autocomplete=\"off\">\r\n<div id=\"searchMsg\" class=\"hint\">پس از بارگذاری شیت، جست‌وجو فعال می‌شود.</div><div id=\"results\" class=\"results\"></div>\r\n</section>\r\n<section class=\"card\"><h2>۳. ثبت کتاب انتخاب‌شده</h2>\r\n<div id=\"selectedInfo\" class=\"status\">یک کتاب را از نتایج جست‌وجو انتخاب کنید.</div>\r\n<label for=\"category\">موضوع / گروه</label><select id=\"category\"><option value=\"\">انتخاب نشده</option><option>R ـ روایت و خاطرات</option><option>A ـ ادبیات و هنر</option><option>H ـ تاریخ و اسناد</option><option>P ـ پژوهش و تحلیل</option><option>K ـ کودک و نوجوان</option><option>M ـ متفرقه</option><option>نیازمند تعیین موضوع</option></select>\r\n<div class=\"grid\"><div><label for=\"shelf\">قفسه</label><select id=\"shelf\"><option value=\"\">انتخاب کنید</option><option>SH-01</option><option>SH-02</option><option>SH-03</option><option>SH-04</option></select></div>\r\n<div><label for=\"level\">طبقه از بالا</label><select id=\"level\"><option value=\"\">انتخاب کنید</option><option value=\"T01\">طبقه ۱</option><option value=\"T02\">طبقه ۲</option><option value=\"T03\">طبقه ۳</option><option value=\"T04\">طبقه ۴</option><option value=\"T05\">طبقه ۵</option><option value=\"T06\">طبقه ۶</option></select></div></div>\r\n<label for=\"physical\">وضعیت مشاهده</label><select id=\"physical\"><option value=\"verified\">کتاب دیده شد و ثبت شد</option><option value=\"review\">نیازمند بررسی مشخصات</option><option value=\"not_found\">در این نوبت پیدا نشد</option></select>\r\n<label for=\"notes\">توضیحات کوتاه</label><textarea id=\"notes\" placeholder=\"مثلاً موضوع دقیق، چاپ متفاوت، یادداشت کوتاه (اختیاری)\"></textarea>\r\n<div class=\"grid\"><button id=\"save\">ذخیره ثبت</button><button id=\"clear\" class=\"alt\">کتاب بعدی / پاک‌کردن</button></div>\r\n</section>\r\n<section class=\"card\"><h2>۴. کتابی که در اکسل پیدا نشد</h2><p class=\"hint\">اگر کتاب را واقعاً در قفسه دیده‌اید اما در فهرست رکورد مناسبی ندارد، آن را اینجا جداگانه ثبت کنید؛ فهرست مرجع تغییر نمی‌کند.</p>\r\n<label for=\"outsideTitle\">عنوان روی کتاب</label><input id=\"outsideTitle\" placeholder=\"عنوان کتاب\">\r\n<label for=\"outsideAuthor\">نویسنده (اگر مشخص است)</label><input id=\"outsideAuthor\" placeholder=\"اختیاری\">\r\n<button id=\"addOutside\" class=\"alt\">ثبت کتاب خارج از فهرست</button></section>\r\n<section class=\"card full\"><h2>۵. آمار، پشتیبان و خروجی</h2>\r\n<div class=\"stats\"><div class=\"stat\"><b id=\"countRows\">۰</b><span>ردیف‌های شیت</span></div><div class=\"stat\"><b id=\"countSaved\">۰</b><span>ثبت‌ها</span></div><div class=\"stat\"><b id=\"countVerified\">۰</b><span>کتاب‌های دیده‌شده</span></div></div>\r\n<p class=\"hint\">ثبت‌ها فقط در حافظه مرورگر همین گوشی ذخیره می‌شوند؛ پاک‌کردن داده‌های مرورگر می‌تواند آن‌ها را از بین ببرد. پایان هر نوبت کاری، پشتیبان JSON و خروجی CSV بگیرید.</p>\r\n<div class=\"grid\"><button id=\"csv\">خروجی CSV ثبت‌ها</button><button id=\"json\" class=\"alt\">پشتیبان JSON</button><button id=\"restore\" class=\"alt\">بازیابی/ادغام پشتیبان JSON</button><button id=\"delta\" class=\"alt\">خروجی تغییرات برای بررسی Excel</button><button id=\"combined\" class=\"alt full\">خروجی شیت + ثبت‌ها</button><input id=\"backupFile\" type=\"file\" accept=\".json,application/json\" class=\"hidden\"></div>\r\n<div id=\"saveMsg\" class=\"status\">آمادهٔ ثبت پس از بارگذاری فهرست.</div>\r\n<p class=\"foot\">نسخهٔ موقت و مستقل است: به Supabase، نرم‌افزار اصلی یا داده‌های آنلاین متصل نیست. این ابزار محل فیزیکی و مشخصات کتاب را ثبت می‌کند؛ ارتباط با اسامی شهدا در مرحله بعد و جداگانه انجام خواهد شد.</p>\r\n</section>\r\n</main>\r\n<script>\r\n(()=>{'use strict';\r\nconst $=id=>document.getElementById(id), STORE='shohada_markaz_asnad_library_audit_v1';\r\nlet workbook=null,headers=[],rows=[],selected=null,records={},currentSheet='';\r\nconst norm=s=>String(s??'').normalize('NFKC').replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[ۀة]/g,'ه').replace(/[\\u064B-\\u065F\\u0670]/g,'').replace(/\\u200c/g,' ').replace(/\\s+/g,' ').trim().toLocaleLowerCase('fa');\r\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\r\nconst val=(row,id)=>{const i=Number($(id).value);return Number.isInteger(i)&&i>=0?String(row.values[i]??''):''};\r\nfunction loadRecords(){try{records=JSON.parse(localStorage.getItem(STORE)||'{}')||{}}catch{records={}}}\r\nfunction persist(){try{localStorage.setItem(STORE,JSON.stringify(records));$('saveMsg').textContent='ثبت در حافظه مرورگر ذخیره شد. برای اطمینان، پشتیبان JSON بگیرید.';return true}catch(e){$('saveMsg').textContent='ذخیره ناموفق بود؛ فوراً خروجی بگیرید و ادامه ندهید.';return false}}\r\nfunction metrics(){$('countRows').textContent=rows.length.toLocaleString('fa-IR');$('countSaved').textContent=Object.keys(records).length.toLocaleString('fa-IR');$('countVerified').textContent=Object.values(records).filter(r=>r.physical==='verified').length.toLocaleString('fa-IR')}\r\nfunction setOptions(id,blank){const el=$(id);el.innerHTML='';if(blank){const o=document.createElement('option');o.value='';o.textContent='ثبت نشده';el.appendChild(o)}headers.forEach((h,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=h||('ستون '+(i+1));el.appendChild(o)})}\r\nfunction infer(id,patterns){const idx=headers.findIndex(h=>patterns.some(p=>p.test(h)));if(idx>=0)$(id).value=String(idx)}\r\nfunction loadSheet(){currentSheet=$('sheet').value;const ws=workbook.Sheets[currentSheet];const data=XLSX.utils.sheet_to_json(ws,{header:1,defval:'',raw:false});if(!data.length){$('loadMsg').textContent='این شیت خالی است.';return}headers=data[0].map((h,i)=>String(h||'ستون '+(i+1)).trim());rows=data.slice(1).map((r,i)=>({id:'ROW-'+(i+2),values:headers.map((_,j)=>String(r[j]??''))})).filter(r=>r.values.some(v=>String(v).trim()));['titleCol','authorCol','publisherCol','yearCol'].forEach(id=>setOptions(id,true));infer('titleCol',[/عنوان/,/نام کتاب/,/^کتاب$/]);infer('authorCol',[/نویسنده/,/مولف/,/مؤلف/]);infer('publisherCol',[/ناشر/,/انتشارات/]);infer('yearCol',[/سال چاپ/,/سال انتشار/,/^سال$/,/چاپ/]);$('mapArea').classList.remove('hidden');$('loadMsg').textContent='شیت «'+currentSheet+'» خوانده شد؛ '+rows.length.toLocaleString('fa-IR')+' ردیف داده. ستون‌ها را بررسی کنید.';metrics();render()}\r\nfunction key(row){return currentSheet+'::'+row.id}\r\nfunction render(){const box=$('results'),q=norm($('search').value);box.innerHTML='';if(!headers.length){$('searchMsg').textContent='ابتدا فایل و شیت را انتخاب کنید.';return}if(q.length<2){$('searchMsg').textContent='حداقل دو حرف از عنوان وارد کنید.';return}const found=rows.filter(r=>norm(val(r,'titleCol')).includes(q)).slice(0,35);$('searchMsg').textContent=found.length.toLocaleString('fa-IR')+' نتیجهٔ اول نمایش داده می‌شود.';if(!found.length){box.innerHTML='<div class=\"status\">عنوانی پیدا نشد. اگر کتاب را در قفسه می‌بینید، از بخش «کتاب خارج از فهرست» استفاده کنید.</div>';return}found.forEach(r=>{const b=document.createElement('button');b.className='result'+(selected&&selected.id===r.id?' chosen':'');b.innerHTML='<strong>'+esc(val(r,'titleCol')||'(بدون عنوان)')+'</strong><small>'+esc([val(r,'authorCol'),val(r,'publisherCol'),val(r,'yearCol')].filter(Boolean).join(' · '))+'</small><small>'+(records[key(r)]?'ثبت قبلی موجود است':'هنوز ثبت نشده')+'</small>';b.onclick=()=>choose(r);box.appendChild(b)})}\r\nfunction choose(r){selected=r;const rec=records[key(r)]||{};$('selectedInfo').innerHTML='<strong>'+esc(val(r,'titleCol'))+'</strong><br><span class=\"hint\">'+esc([val(r,'authorCol'),val(r,'publisherCol'),val(r,'yearCol')].filter(Boolean).join(' · ')||'اطلاعات تکمیلی در شیت خالی است')+'</span>'; $('category').value=rec.category||'';$('shelf').value=rec.shelf||'';$('level').value=rec.level||'';$('physical').value=rec.physical||'verified';$('notes').value=rec.notes||'';render()}\r\nfunction recordBase(title,author,publisher,year,k,source){return {key:k,source,sheet:currentSheet,title,author,publisher,year,category:$('category').value,shelf:$('shelf').value,level:$('level').value,location:$('shelf').value&&$('level').value?$('shelf').value+'-'+$('level').value:'',physical:$('physical').value,notes:$('notes').value.trim(),updatedAt:new Date().toISOString()}}\r\nfunction save(){if(!selected){alert('ابتدا کتابی از نتایج جست‌وجو انتخاب کنید.');return}if($('physical').value==='verified'&&(!$('shelf').value||!$('level').value)){alert('برای کتابی که دیده شده، قفسه و طبقه واقعی را انتخاب کنید.');return}if(!$('category').value){alert('گروه موضوعی را انتخاب کنید؛ اگر نامشخص است «نیازمند تعیین موضوع» را بزنید.');return}records[key(selected)]=recordBase(val(selected,'titleCol'),val(selected,'authorCol'),val(selected,'publisherCol'),val(selected,'yearCol'),key(selected),'catalog');if(persist()){metrics();render();$('saveMsg').textContent='ثبت ذخیره شد: '+val(selected,'titleCol')}}\r\nfunction clearForm(){selected=null;$('selectedInfo').textContent='یک کتاب را از نتایج جست‌وجو انتخاب کنید.';$('category').value='';$('shelf').value='';$('level').value='';$('physical').value='verified';$('notes').value='';$('search').value='';render()}\r\nfunction outside(){const title=$('outsideTitle').value.trim();if(!title){alert('عنوان کتاب را وارد کنید.');return}if(!$('category').value){alert('گروه موضوعی را انتخاب کنید؛ اگر نامشخص است «نیازمند تعیین موضوع» را بزنید.');return}if(!$('shelf').value||!$('level').value){alert('برای کتابی که دیده شده، قفسه و طبقه واقعی را انتخاب کنید.');return}const k='OUT-'+Date.now()+'-'+Math.random().toString(36).slice(2,7);const r=recordBase(title,$('outsideAuthor').value.trim(),'','',k,'outside-list');r.physical='verified';records[k]=r;if(persist()){metrics();$('outsideTitle').value='';$('outsideAuthor').value='';$('saveMsg').textContent='کتاب خارج از فهرست ذخیره شد؛ اکسل مرجع تغییر نکرد.'}}\r\nconst fields=[['key','کلید ثبت'],['source','منبع رکورد'],['sheet','شیت مرجع'],['title','عنوان کتاب'],['author','نویسنده'],['publisher','ناشر'],['year','سال چاپ'],['category','موضوع'],['shelf','قفسه'],['level','طبقه'],['location','کد محل'],['physical','وضعیت مشاهده'],['notes','توضیحات'],['updatedAt','زمان ثبت']];\r\nconst cell=v=>'\"'+String(v??'').replace(/\"/g,'\"\"')+'\"';\r\nfunction download(name,body,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\\uFEFF',body],{type:type||'text/plain;charset=utf-8'}));a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}\r\nfunction exportCsv(){download('ثبت-فیزیکی-کتابخانه.csv',[fields.map(f=>cell(f[1])).join(','),...Object.values(records).map(r=>fields.map(f=>cell(r[f[0]])).join(','))].join('\\r\\n'),'text/csv;charset=utf-8')}\r\nfunction exportJson(){download('پشتیبان-نرم‌افزار-کتابخانه.json',JSON.stringify({app:'markaz-asnad-library-audit',version:1,exportedAt:new Date().toISOString(),records},null,2),'application/json;charset=utf-8')}\r\nfunction importJsonFile(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(String(reader.result||''));if(!data||typeof data!=='object'||!data.records||typeof data.records!=='object'||Array.isArray(data.records)){throw new Error('ساختار پشتیبان معتبر نیست.')}const entries=Object.entries(data.records);if(!entries.length){alert('پشتیبان هیچ ثبتی ندارد.');return}if(!entries.every(([k,r])=>typeof k==='string'&&r&&typeof r==='object'&&typeof r.title==='string'&&r.title.trim())){throw new Error('برخی ثبت‌ها کلید یا عنوان معتبر ندارند.')}const conflicts=entries.filter(([k])=>Object.prototype.hasOwnProperty.call(records,k)).length;const msg='تعداد ثبت در فایل: '+entries.length+'\\\\nکلیدهای موجود که بازنویسی نمی‌شوند: '+conflicts+'\\\\nثبت‌های جدید اضافه شوند؟';if(!confirm(msg))return;let added=0;for(const [k,r] of entries){if(!Object.prototype.hasOwnProperty.call(records,k)){records[k]=r;added++}}if(persist()){metrics();render();$('saveMsg').textContent='بازیابی/ادغام انجام شد: '+added+' ثبت تازه افزوده شد؛ '+conflicts+' مورد تکراری بدون بازنویسی باقی ماند.'}}catch(err){alert('بازیابی انجام نشد: '+err.message)}finally{$('backupFile').value=''}};reader.readAsText(file,'utf-8')}\r\nfunction exportDelta(){const list=Object.values(records);if(!list.length){alert('هنوز ثبتی برای خروجی وجود ندارد.');return}const cols=[['key','کلید تطبیق/ردیف'],['source','نوع رکورد'],['sheet','شیت مرجع'],['title','عنوان کتاب'],['author','نویسنده'],['publisher','ناشر'],['year','سال چاپ'],['category','موضوع'],['shelf','قفسه'],['level','طبقه'],['location','کد محل'],['physical','وضعیت مشاهده'],['notes','توضیحات'],['updatedAt','زمان ثبت']];const lines=[cols.map(x=>cell(x[1])).join(','),...list.map(r=>cols.map(x=>cell(r[x[0]])).join(','))];download('پیشنهاد-تغییرات-برای-بررسی-اکسل.csv',lines.join('\\r\\n'),'text/csv;charset=utf-8')}\r\nfunction combined(){const head=[...headers,'گروه موضوعی','قفسه','طبقه','کد محل','وضعیت مشاهده','توضیحات','زمان ثبت'];const lines=[head.map(cell).join(',')];rows.forEach(r=>{const x=records[key(r)]||{};lines.push([...r.values,x.category||'',x.shelf||'',x.level||'',x.location||'',x.physical||'',x.notes||'',x.updatedAt||''].map(cell).join(','))});download('فهرست-همراه-با-ثبت-فیزیکی.csv',lines.join('\\r\\n'),'text/csv;charset=utf-8')}\r\n$('workbook').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(!window.XLSX){$('loadMsg').textContent='کتابخانهٔ خواندن Excel بارگذاری نشد؛ اینترنت را بررسی و صفحه را دوباره باز کنید.';return}try{const data=await f.arrayBuffer();workbook=XLSX.read(data,{type:'array'});$('sheet').innerHTML='';workbook.SheetNames.forEach(n=>{const o=document.createElement('option');o.value=n;o.textContent=n;$('sheet').appendChild(o)});const likely=workbook.SheetNames.find(n=>/عنوان.*کتاب|فهرست کتاب|کتاب‌ها/.test(n));if(likely)$('sheet').value=likely;$('sheetArea').classList.remove('hidden');$('loadMsg').textContent='فایل خوانده شد: '+f.name+'؛ '+workbook.SheetNames.length+' شیت. شیت درست را انتخاب کنید.'}catch(err){$('loadMsg').textContent='خواندن فایل ناموفق بود: '+err.message}});\r\n$('loadSheet').onclick=loadSheet;$('applyMap').onclick=()=>{if(!headers.length||$('titleCol').value===''||!headers[Number($('titleCol').value)]){alert('ستون عنوان را مشخص کنید.');return}render();metrics();$('loadMsg').textContent='آمادهٔ جست‌وجو. وجود فیزیکی فقط پس از مشاهده ثبت می‌شود.'};$('search').addEventListener('input',render);$('save').onclick=save;$('clear').onclick=clearForm;$('addOutside').onclick=outside;$('csv').onclick=exportCsv;$('json').onclick=exportJson;$('restore').onclick=()=>$('backupFile').click();$('backupFile').addEventListener('change',e=>importJsonFile(e.target.files[0]));$('delta').onclick=exportDelta;$('combined').onclick=combined;\r\nloadRecords();metrics();\r\n})();\r\n<\/script>\r\n</body></html>\r\n\r\n================ FILE: \\کتابخانه\\گزارش‌ها\\نقطه شروع برنامه‌نویسی ثبت سریع موجودی فیزیکی کتابخانه - نسخه 0.1.md ================\r\n# نقطه شروع برنامه‌نویسی ثبت سریع موجودی فیزیکی کتابخانه\r\n**نسخه:** ۰٫۱\r\n**تاریخ:** ۱۴۰۵/۰۸/۰۴\r\n**مخزن رسمی:** `forog1980-star/markaz-asnad-shohada`\r\n**شاخه فعلی گزارش:** `feature/software-ketabkhane-physical-audit-20261025`\r\n**وضعیت:** تعریف نقطه شروع؛ هنوز کدنویسی نسخه جدید انجام نشده است.\r\n\r\n## مأموریت\r\nساخت یک ابزار کوچک و سریع برای ثبت فیزیکی کتاب‌های موجود در کتابخانه با یک گوشی اندرویدی و یک کاربر. هدف فوری، فهرست‌برداری از کتاب‌های واقعاً موجود، ثبت یا تطبیق عنوان و اطلاعات پایه، تعیین گروه موضوعی و محل واقعی، ایجاد شناسه قابل ردیابی در صورت نیاز، و آماده‌سازی خروجی برای به‌روزرسانی کنترل‌شده فایل Excel است.\r\n\r\nاین کار از سامانه جامع «ثبت کتاب‌ها و شهدا» جدا نگه داشته می‌شود. در نسخه نخست، ارتباط کتاب و شهید، هوش مصنوعی، داشبورد مدیریتی، ورود چندکاربره و اتصال به پایگاه داده آنلاین لازم نیستند.\r\n\r\n## محیط و محدودیت‌های شناخته‌شده\r\n- دستگاه هدف: گوشی اندرویدی؛ کاربر واحد.\r\n- زبان و رابط: فارسی، راست‌به‌چپ، مناسب لمس.\r\n- اینترنت: ممکن است برای بارگذاری اولیه لازم باشد، اما نباید ثبت‌های ذخیره‌شده را وابسته به اتصال دائمی فرض کرد.\r\n- رایانه کاربر ویندوز است و برای کارهای پشتیبان از PowerShell استفاده می‌شود.\r\n- فایل مرجع: `کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx`.\r\n- مسیر ابزار آزمایشی موجود: `نرم‌افزار کتابخانه/index.html`.\r\n- ابزار قبلی در مرورگر از `localStorage` استفاده می‌کند و خروجی CSV/JSON دارد؛ بازیابی JSON هنوز تأیید نشده است.\r\n- تغییرات ابزار قبلی در شاخه `feature/software-ketabkhane-physical-audit-20261025` و PR پیش‌نویس #3 قرار دارند. `main` را بدون بازبینی و تصمیم جداگانه تغییر نده.\r\n- فایل Excel مرجع و Supabase در تغییرات قبلی دست‌نخورده باقی مانده‌اند.\r\n\r\n## نقشه فیزیکی مورد توافق\r\nچهار قفسه عملیاتی، هرکدام با شش طبقه از بالا به پایین:\r\n- `SH-01-T01` تا `SH-01-T06`\r\n- `SH-02-T01` تا `SH-02-T06`\r\n- `SH-03-T01` تا `SH-03-T06`\r\n- `SH-04-T01` تا `SH-04-T06`\r\n\r\nجانمایی موضوعی:\r\n- `SH-01` و `SH-02`: گروه R — روایت و خاطرات.\r\n- `SH-03-T01`: H — تاریخ و اسناد.\r\n- `SH-03-T02`: A — ادبیات و هنر.\r\n- `SH-03-T03` و `SH-03-T04`: P — پژوهش و تحلیل.\r\n- `SH-03-T05` و `SH-03-T06`: M — متفرقه.\r\n- `SH-04-T01`: K — کودک و نوجوان.\r\n- `SH-04-T02` تا `SH-04-T06`: آزاد برای توسعه یا جابه‌جایی آینده.\r\n\r\nگروه‌ها: R، A، H، P، K، M. شناسه کتاب و کد محل دو مقدار مستقل‌اند؛ جابه‌جایی کتاب فقط محل را تغییر می‌دهد.\r\n\r\n## جریان کاری موردنظر نسخه اول\r\n1. کاربر کتاب فیزیکی را در دست دارد.\r\n2. برنامه جست‌وجوی سریع در فهرست مرجعِ انتخاب‌شده را فراهم می‌کند.\r\n3. اگر رکورد منطبق پیدا شد، کاربر آن را تأیید می‌کند و داده‌های میدانی را ثبت می‌کند.\r\n4. اگر کتاب پیدا نشد، یک رکورد جدید با وضعیت «نیازمند تطبیق با Excel» ساخته می‌شود؛ برنامه نباید رکورد مشابه را خودکار حذف یا ادغام کند.\r\n5. اطلاعات پایه تا حد ممکن ثبت می‌شود: عنوان (برای ثبت تازه لازم)، نویسنده، ناشر، سال چاپ، گروه موضوعی، محل، وضعیت تطبیق و یادداشت کوتاه. فیلدهای نامعلوم به‌صورت خالی/نامشخص نگهداری می‌شوند، نه اینکه حدس زده شوند.\r\n6. داده‌ها محلی ذخیره می‌شوند و کاربر می‌تواند پشتیبان بگیرد.\r\n7. خروجی برای بازبینی و اعمال کنترل‌شده در Excel تولید می‌شود؛ فایل مرجع نباید بی‌صدا بازنویسی شود.\r\n\r\n## سیاست شناسه‌گذاری\r\nنمونه‌های قبلی `GS-R-01`، `GS-A-01` و مانند آن صرفاً پیشنهاد بوده‌اند؛ تخصیص سراسری شناسه دائمی هنوز تأیید نشده است. در شروع برنامه‌نویسی:\r\n- شناسه موجود در فایل مرجع، اگر وجود داشته باشد، حفظ شود.\r\n- شناسه کتاب با محل فیزیکی یکی نشود.\r\n- برای کتاب تازه، تا زمان تأیید قاعده دائمی، از شناسه موقت/ردیف قابل پیگیری استفاده شود یا شناسه پیشنهادی با برچسب «موقت» ذخیره شود.\r\n- تولید شناسه تکراری، ادغام خودکار و بازنویسی شناسه‌های موجود ممنوع باشد.\r\n- قبل از ساخت شماره‌گذار دائمی، ستون‌های واقعی Excel و وجود/عدم وجود شناسه در آن بررسی شود.\r\n\r\n## حفاظت از Excel و داده‌ها\r\nکاربر اکنون اولویت به‌روزرسانی فهرست Excel را هم صریحاً مطرح کرده است. این به معنی مجوز بازنویسی مستقیم بدون پشتیبان نیست. راهکار امن نسخه اول:\r\n- خواندن فایل مرجع بدون تغییر.\r\n- ذخیره ثبت‌های میدانی در فایل داده مستقل.\r\n- تولید خروجی پیشنهادی تغییرات و گزارش رکوردهای جدید/تطبیق‌یافته/مبهم.\r\n- پیش از هر مرحله اعمال روی Excel، ساخت نسخه پشتیبان با نام تاریخ‌دار.\r\n- حفظ رکوردهای تکراری یا مشکوک برای بازبینی انسانی.\r\n- عدم اتصال و عدم تغییر Supabase در این مرحله.\r\n\r\n## تعریف موفقیت نسخه اول\r\n- استفاده‌پذیری روی گوشی اندرویدی واقعی.\r\n- ثبت یک کتاب با حداقل لمس و بدون نیاز به تکمیل فیلدهای غیرضروری.\r\n- جست‌وجوی عنوان با رفتار قابل پیش‌بینی.\r\n- ثبت محل فقط از فهرست معتبر کدهای `SH-xx-Txx`.\r\n- ذخیره و بازیابی قابل آزمون یا حداقل خروجی پشتیبان قابل اعتبارسنجی.\r\n- خروجی قابل بازکردن و تطبیق در Excel، بدون تغییر ناخواسته فایل اصلی.\r\n- آزمون عملی با ۱۰ تا ۲۰ کتاب واقعی و ثبت نتایج.\r\n- مستندکردن محدودیت‌ها؛ عدم ادعای استقرار یا آزمون تا زمان انجام واقعی.\r\n\r\n## دستورالعمل آغاز در گفت‌وگوی جدید\r\n1. این سند و گزارش روزانه `گزارش روزانه کتابخانه - 1405-08-04.md` را بخوان.\r\n2. از GitHub وضعیت فعلی شاخه و PR #3 را دوباره بررسی کن؛ این گزارش وضعیت فعلی زمان ثبت را منعکس می‌کند و ممکن است شاخه بعداً تغییر کرده باشد.\r\n3. فایل `نرم‌افزار کتابخانه/index.html` و `README.md` را بخوان و قابلیت‌های واقعی را از قابلیت‌های صرفاً توصیف‌شده تفکیک کن.\r\n4. ساختار واقعی فایل Excel مرجع را با نام شیت‌ها و سرستون‌ها بررسی کن؛ چیزی را حدس نزن.\r\n5. پیش از کدنویسی تصمیم بگیر نسخه جدید به‌صورت ابزار مستقل ساخته شود یا از ابزار موجود در شاخه کاری جداگانه استفاده کند؛ انتخاب باید بر اساس بررسی کد و اولویت «سرعت فهرست‌برداری» باشد.\r\n6. در یک شاخه کاری جدید/مناسب کار کن، تغییرات را کوچک و قابل بازبینی نگه دار و به `main` مستقیم commit نکن.\r\n7. ابتدا نمونه حداقلی ثبت/جست‌وجو/ذخیره/خروجی بساز؛ سپس با داده آزمایشی تست کن.\r\n8. هیچ فایل یا داده‌ای را بدون نسخه پشتیبان حذف یا بازنویسی نکن.\r\n9. پس از هر مرحله، گزارش فنی و روزانه را به‌روز کن و وضعیت آزمون را دقیقاً «انجام‌شده» یا «انجام‌نشده» ثبت کن.\r\n\r\n## پیوندهای اصلی\r\n- مخزن: https://github.com/forog1980-star/markaz-asnad-shohada\r\n- شاخه فعلی ابزار: https://github.com/forog1980-star/markaz-asnad-shohada/tree/feature/software-ketabkhane-physical-audit-20261025\r\n- PR #3: https://github.com/forog1980-star/markaz-asnad-shohada/pull/3\r\n- ابزار موجود: `نرم‌افزار کتابخانه/index.html`\r\n- راهنمای ابزار: `نرم‌افزار کتابخانه/README.md`\r\n- گزارش فنی قبلی: `کتابخانه/گزارش‌ها/گزارش فنی ابزار تطبیق فیزیکی کتابخانه - نسخه 0.1.md`\r\n\r\n**نقطه پایان این سند:** در آغاز گفت‌وگوی جدید، کار را از بررسی وضعیت واقعی مخزن و Excel شروع کن و سپس مستقیماً وارد ساخت نسخه حداقلی ابزار ثبت سریع شو؛ از کاربر نخواه تصمیم‌ها و نقشه قفسه‌ها را دوباره توضیح دهد.\r\n\r\n================ FILE: \\کتابخانه\\گزارش‌ها\\گزارش فنی ابزار تطبیق فیزیکی کتابخانه - نسخه 0.1.md ================\r\n# گزارش فنی ابزار موقت تطبیق فیزیکی کتابخانه مرکز اسناد\r\n**نسخه سند:** ۰٫۱\r\n**تاریخ تنظیم و وضعیت ثبت:** ۱۴۰۵/۰۸/۰۳\r\n**مخزن رسمی:** `forog1980-star/markaz-asnad-shohada`\r\n**شاخه کاری:** `feature/software-ketabkhane-physical-audit-20261025`\r\n**وضعیت:** گزارش فنی جاری؛ ابزار آزمایشی و هنوز تأییدنشده برای استفاده انبوه\r\n**دامنه:** رویدادها و تصمیم‌های ثبت‌شده در گفت‌وگوهای اخیر درباره سامان‌دهی فیزیکی، برچسب‌ها و ابزار موقت کتابخانه\r\n\r\n---\r\n\r\n## ۱. خلاصه مدیریتی و فنی\r\n\r\nبرای کمک به تطبیق کتاب‌های فیزیکی کتابخانه با فهرست کاری موجود، ابزار وب مستقلی در مسیر `نرم‌افزار کتابخانه/` آماده شده است. هدف ابزار این است که یک کاربر با یک گوشی اندرویدی بتواند عنوان را در فایل Excel جست‌وجو کند، کتاب را با نسخه فیزیکی موجود تطبیق دهد و موضوع، قفسه، طبقه، وضعیت مشاهده و توضیح لازم را ثبت کند. در صورت پیدا نشدن کتاب در فهرست، ثبت جداگانه‌ای نیز پیش‌بینی شده است.\r\n\r\nدر ادامه کار، نقشه قفسه‌ها و کدهای محل بازبینی شد. کدهای قدیمی موجود در منوی برنامه با نقشه عملیاتی تأییدشده در گفت‌وگو جایگزین شدند و راهنمای برنامه و مستند برچسب‌ها نیز هماهنگ شدند. فایل Word برچسب‌ها در رایانه کاربر ساخته و از نظر کادرها و صفحه‌بندی بازبینی شده است.\r\n\r\n**مرز مهم وضعیت:** تغییرات کد و مستندات روی شاخه کاری ثبت شده‌اند؛ `main` تغییر نکرده و PR شماره ۳ هنوز پیش‌نویس است. اجرای موفق روی گوشی واقعی، آزمون با ۲۰ کتاب، بازیابی پشتیبان JSON و استقرار HTTPS هنوز تأیید نشده‌اند. فایل مرجع Excel و Supabase نیز تغییر داده نشده‌اند.\r\n\r\n## ۲. هدف، کاربران و محدوده ابزار\r\n\r\n### هدف عملیاتی\r\n- کوتاه‌کردن زمان تطبیق نسخه‌های فیزیکی با فهرست کاری.\r\n- ثبت محل واقعی کتاب و موضوع آن، بدون تغییر دادن فایل مرجع.\r\n- مشخص‌کردن کتاب‌های مشاهده‌شده، پیدا‌نشده یا خارج از فهرست.\r\n- فراهم‌کردن خروجی قابل نگهداری برای بررسی و انتقال بعدی.\r\n\r\n### فرض‌های طراحی فعلی\r\n- یک کاربر و یک گوشی اندرویدی.\r\n- اینترنت نسبتاً پایدار برای بارگذاری اولیه صفحه و کتابخانه JavaScript مربوط به Excel.\r\n- استفاده موقت و کم‌ریسک؛ نه سامانه نهایی کتابخانه.\r\n- نگهداری ثبت‌ها در مرورگر همان دستگاه و تهیه خروجی پشتیبان در پایان کار.\r\n\r\n### موارد خارج از دامنه این ابزار\r\n- ویرایش مستقیم فایل Excel مرجع.\r\n- اتصال به Supabase یا تغییر پایگاه داده.\r\n- تأیید نهایی شناسه دائمی تمام کتاب‌ها.\r\n- پیاده‌سازی کامل رابطه کتاب و شهید.\r\n- انتشار عمومی اطلاعات یا جایگزینی نرم‌افزار جامع ثبت کتاب‌ها و شهدا.\r\n\r\n## ۳. قواعد فیزیکی تثبیت‌شده\r\n\r\n### ۳.۱. نقشه قفسه‌ها و طبقات\r\nچهار قفسه در نقشه عملیاتی فعلی قرار دارند:\r\n\r\n| شناسه قفسه | کاربرد گروهی فعلی |\r\n|---|---|\r\n| `SH-01` | R — روایت و خاطرات |\r\n| `SH-02` | R — روایت و خاطرات |\r\n| `SH-03` | A، H، P، K و M |\r\n| `SH-04` | A، H، P، K و M |\r\n\r\nهر قفسه شش طبقه دارد. کدها از بالا به پایین عبارت‌اند از `T01`، `T02`، `T03`، `T04`، `T05` و `T06`.\r\n\r\nالگوی نشانی کامل محل:\r\n\r\n- `SH-01-T01`\r\n- `SH-02-T06`\r\n- `SH-03-T04`\r\n- `SH-04-T02`\r\n\r\nقفسه پنجم در نقشه عملیاتی فعلی ابزار قرار ندارد. جهت دقیق حرکت بین قفسه‌ها و جانمایی نهایی گروه‌های A، H، P، K و M باید با مشاهده محل واقعی تثبیت شود؛ نمونه‌های چاپی برای این گروه‌ها به معنی تأیید جانمایی نهایی نیستند.\r\n\r\n### ۳.۲. گروه‌های موضوعی\r\n- **R:** روایت و خاطرات\r\n- **A:** ادبیات و هنر\r\n- **H:** تاریخ و اسناد\r\n- **P:** پژوهش و تحلیل\r\n- **K:** کودک و نوجوان\r\n- **M:** متفرقه\r\n\r\nبرآوردهای کاری مطرح‌شده برای تقسیم فیزیکی عبارت‌اند از حدود ۵۸۰ عنوان در R و مجموع حدود ۳۶۲ عنوان برای A/H/P/K/M. این اعداد تا انجام ممیزی نهایی، آمار قطعی و تأییدشده موجودی محسوب نمی‌شوند.\r\n\r\n### ۳.۳. شناسه کتاب و محل فیزیکی\r\nشناسه کتاب و محل فیزیکی دو مفهوم مستقل‌اند. نمونه‌های پیشنهادی شناسه گروهی عبارت‌اند از `GS-R-01`، `GS-A-01`، `GS-H-01`، `GS-P-01`، `GS-K-01` و `GS-M-01`. این نمونه‌ها به معنی اختصاص شناسه پایدار به همه کتاب‌ها نیستند.\r\n\r\nاگر کتاب جابه‌جا شود، محل آن تغییر می‌کند؛ شناسه کتاب نباید صرفاً به علت جابه‌جایی تغییر کند.\r\n\r\n## ۴. سابقه تغییر کدهای محل و اصلاح ناسازگاری\r\n\r\nدر نسخه قبلی ابزار و مستندات، قالب قدیمی `SHSF-01-Q01` تا `SHSF-01-Q06` دیده می‌شد. این قالب با نقشه جدید چهار قفسه `SH-01` تا `SH-04` و شش طبقه برای هر قفسه سازگار نبود.\r\n\r\nدر تاریخ ۱۴۰۵/۰۸/۰۳ تغییرات زیر در شاخه کاری ثبت شدند:\r\n\r\n| فایل | اقدام | شناسه commit |\r\n|---|---|---|\r\n| `نرم‌افزار کتابخانه/index.html` | جایگزینی منوی قفسه‌های قدیمی با `SH-01` تا `SH-04` | `6dc3826b8f3dab7aa232e3265d78a057c6dd3d05` |\r\n| `نرم‌افزار کتابخانه/README.md` | هماهنگ‌سازی راهنما با نقشه و کدهای جدید | `50d4fefb60d3983b0bfd1317294f1dd3db738903` |\r\n| `نرم‌افزار کتابخانه/برچسب‌های قفسه و طبقه.md` | اصلاح مستند کدگذاری محل و ثبت بازبودن جانمایی گروه‌های غیر R | `80818ed7ba9ee07f6c9382d6cb9905698c184aa5` |\r\n\r\nدر رابط فعلی، قفسه و طبقه جدا انتخاب می‌شوند و محل با الگوی `SH-xx-Txx` نمایش داده می‌شود.\r\n\r\n**ریسک سازگاری باز:** این تغییر رابط به‌خودی‌خود داده‌های قدیمی احتمالی ذخیره‌شده در `localStorage` با کدهای `SHSF-01-Qxx` را مهاجرت نمی‌دهد. پیش از استفاده میدانی باید این وضعیت بررسی و راهکار حفظ داده تعیین شود. هیچ داده قدیمی نباید بدون نسخه پشتیبان یا تصمیم روشن بازنویسی یا حذف شود.\r\n\r\n## ۵. قابلیت‌های فعلی ثبت‌شده در کد ابزار\r\n\r\nبر پایه بررسی اولیه کد و مستندات، قابلیت‌های موجود یا پیش‌بینی‌شده در نسخه فعلی عبارت‌اند از:\r\n\r\n1. انتخاب فایل Excel محلی.\r\n2. انتخاب شیت موردنظر.\r\n3. نگاشت ستون عنوان و در صورت وجود، نویسنده، ناشر و سال چاپ.\r\n4. جست‌وجوی عنوان و انتخاب رکورد.\r\n5. ثبت موضوع، قفسه، طبقه، وضعیت مشاهده و توضیح کوتاه.\r\n6. ثبت جداگانه کتابی که در فهرست مناسب پیدا نشده است.\r\n7. نگهداری ثبت‌ها در حافظه محلی مرورگر همان دستگاه.\r\n8. تولید خروجی CSV و فایل پشتیبان JSON.\r\n\r\nوجود قابلیت در کد یا راهنما به‌تنهایی به معنی آزمون موفق آن در شرایط واقعی نیست. مواردی مانند صحت نگاشت فایل مرجع، رفتار در ورودی‌های ناقص، بازیابی پشتیبان و پایداری در گوشی باید جداگانه آزموده شوند.\r\n\r\n## ۶. برچسب‌های چاپی و اجرای محلی\r\n\r\nفایل Word زیر روی رایانه کاربر با PowerShell و Microsoft Word COM تولید شد:\r\n\r\n`C:\\Users\\Mahdi\\Desktop\\برچسب‌های کتابخانه مرکز اسناد.docx`\r\n\r\nمحتوای فایل:\r\n- ۶ برچسب نمونه کتاب با ساختار کادربندی‌شده سه‌ردیفه.\r\n- ۲۴ برچسب محل برای چهار قفسه و شش طبقه هر قفسه.\r\n\r\nاسکریپت اولیه به‌علت تنظیم نامعتبر ویژگی `ParagraphFormat.ReadingOrder` خطا داد. در نسخه اصلاح‌شده، آن تنظیم حذف شد و کاربر اجرای موفق را تأیید کرد. کاربر فایل را در Word بازبینی کرد و کادرها، ساختار و صفحه‌بندی را درست دانست. جای علامت دونقطه در برخی عبارت‌های فارسی نیازمند اصلاح دستی بود؛ جایگزینی آن با خط تیره به‌عنوان راه‌حل ساده پیشنهاد شد.\r\n\r\nاین فایل فقط در رایانه کاربر ایجاد شده و طبق وضعیت فعلی در GitHub ثبت نشده است. محل‌های درج‌شده برای گروه‌های A/H/P/K/M نمونه‌ای و غیرنهایی هستند.\r\n\r\n## ۷. مرجع داده و حفاظت از اطلاعات\r\n\r\n- مرجع جاری کتابخانه طبق تصمیم قبلی کاربر: `کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx`.\r\n- ابزار موقت نباید فایل مرجع را بازنویسی کند؛ فایل فقط برای خواندن و جست‌وجو استفاده می‌شود.\r\n- داده‌های ثبت‌شده در مرورگر همان دستگاه ذخیره می‌شوند؛ پاک‌کردن داده‌های مرورگر یا تغییر دستگاه می‌تواند خطر از دست‌رفتن ثبت‌ها را ایجاد کند.\r\n- خروجی JSON در حال حاضر به‌عنوان پشتیبان قابل دریافت است؛ قابلیت واردکردن/بازیابی آن هنوز پیاده‌سازی و آزمون نشده است.\r\n- ابزار به Supabase متصل نیست و هیچ جدول، رکورد یا تنظیمی در Supabase تغییر نکرده است.\r\n- ارتباط کتاب و شهید و تأیید اعتبار این ارتباط‌ها خارج از دامنه مرحله فعلی است.\r\n- ثبت یک نام یا ارتباط در فایل‌های دیگر به‌تنهایی اثبات وجود فیزیکی کتاب نیست.\r\n- خروجی‌های قدیمی استخراج‌شده از فایل‌های اولیه در بایگانی تاریخی قرار دارند و نباید بدون ممیزی تازه جایگزین فایل مرجع جاری شوند.\r\n\r\n## ۸. وضعیت شاخه، PR و استقرار\r\n\r\n- مخزن رسمی: `forog1980-star/markaz-asnad-shohada`\r\n- شاخه کاری: `feature/software-ketabkhane-physical-audit-20261025`\r\n- PR شماره ۳: [بررسی تغییرات ابزار تطبیق فیزیکی کتابخانه](https://github.com/forog1980-star/markaz-asnad-shohada/pull/3)\r\n- وضعیت PR: پیش‌نویس؛ ادغام نشده است.\r\n- شاخه `main`: برای این مجموعه تغییرات دست‌نخورده باقی مانده است.\r\n- میزبانی آنلاین: URL عملیاتی HTTPS تأیید نشده است. تلاش پیشین برای ایجاد پروژه Vercel با خطای 403 مواجه شده بود؛ علت رفع نشده و استقرار موفق ادعا نمی‌شود.\r\n- آزمون میدانی: اجرای واقعی در گوشی اندرویدی با فایل مرجع و حداقل ۲۰ کتاب هنوز انجام نشده است.\r\n\r\n## ۹. ماتریس وضعیت فنی\r\n\r\n| مورد | وضعیت فعلی | اقدام لازم |\r\n|---|---|---|\r\n| هماهنگی کد قفسه در رابط | تغییر کد ثبت شده | بازبینی در مرورگر |\r\n| هماهنگی README و مستند برچسب‌ها | تغییر مستندات ثبت شده | بازبینی نهایی |\r\n| فایل Word برچسب‌ها | تولید و توسط کاربر بازبینی شده | اصلاح دستی نشانه‌گذاری در صورت نیاز |\r\n| سازگاری داده‌های قدیمی مرورگر | نامشخص؛ مهاجرت انجام نشده | بررسی و حفاظت از داده |\r\n| پشتیبان JSON | خروجی موجود | ساخت واردکردن/بازیابی امن |\r\n| اعتبارسنجی قفسه و طبقه | نیازمند تکمیل یا آزمون | جلوگیری از ثبت محل ناقص/نامعتبر |\r\n| آزمون با ۲۰ کتاب واقعی | انجام نشده | اجرای سناریوهای میدانی |\r\n| آزمون اندروید و ماندگاری داده | انجام نشده | آزمون بستن/بازکردن مرورگر و خروجی |\r\n| میزبانی HTTPS | تأیید نشده | رفع مجوز و بررسی گزینه استقرار |\r\n| ادغام PR | انجام نشده | بازبینی پس از آزمون |\r\n| تغییر فایل Excel مرجع | انجام نشده | حفظ وضعیت فقط‌خواندنی |\r\n| تغییر Supabase | انجام نشده | اتصال در این مرحله ممنوع/خارج از دامنه |\r\n\r\n## ۱۰. برنامه فنی مرحله بعد\r\n\r\n### اولویت ۱ — حفاظت از داده‌های قبلی\r\n1. بررسی ساختار فعلی ذخیره‌سازی مرورگر و شناسایی کدهای قدیمی احتمالی.\r\n2. قبل از هر مهاجرت، ایجاد خروجی پشتیبان و نمایش تعداد رکوردهای تحت تأثیر.\r\n3. تعریف تبدیل کد قدیمی فقط در صورت وجود نگاشت روشن؛ موارد مبهم باید برای بررسی انسانی علامت‌گذاری شوند.\r\n4. ممنوعیت پاک‌سازی یا جایگزینی خودکار داده‌های ناشناخته.\r\n\r\n### اولویت ۲ — بازیابی امن JSON\r\n1. بررسی ساختار فایل JSON ورودی و نسخه/نوع داده.\r\n2. پیش‌نمایش تعداد رکوردها و موارد ناسازگار پیش از اعمال.\r\n3. ارائه گزینه روشن برای لغو عملیات.\r\n4. جلوگیری از ادغام یا جایگزینی خاموش؛ سیاست برخورد با رکورد تکراری باید مشخص باشد.\r\n5. آزمون خروجی‌گیری، پاک‌کردن فقط داده آزمایشی و بازیابی از نسخه پشتیبان.\r\n\r\n### اولویت ۳ — اعتبارسنجی و آزمون میدانی\r\n1. الزام انتخاب قفسه و طبقه معتبر برای ثبت مکانی که کتاب در آن مشاهده شده است.\r\n2. آزمون کتاب موجود در فهرست، کتاب پیدا‌نشده، عنوان مشابه، فیلد ناقص، رکورد تکراری و توضیح فارسی.\r\n3. آزمون با ۲۰ کتاب واقعی در گوشی اندرویدی.\r\n4. کنترل CSV و JSON خروجی و تطبیق تعداد رکوردهای ثبت‌شده با تعداد رکوردهای خروجی.\r\n5. بررسی رفتار با قطع اینترنت پس از بارگذاری اولیه و روشن‌کردن مجدد مرورگر؛ این رفتار باید آزموده شود و نباید از پیش تضمین‌شده فرض شود.\r\n\r\n### اولویت ۴ — بازبینی و انتشار\r\n1. ثبت نتیجه آزمون‌ها در `نرم‌افزار کتابخانه/گزارش تغییرات.md` و این گزارش.\r\n2. بازبینی diff و PR شماره ۳.\r\n3. تصمیم جداگانه درباره ادغام؛ تا پیش از آن `main` تغییر نکند.\r\n4. حل مسئله میزبانی HTTPS و آزمون نشانی عملیاتی پیش از استفاده روی گوشی از راه دور.\r\n\r\n## ۱۱. معیار پذیرش نسخه آزمایشی\r\n\r\nنسخه آزمایشی زمانی برای اجرای محدود میدانی آماده تلقی می‌شود که:\r\n- کد محل در همه قسمت‌های برنامه و مستندات با نقشه فعلی یکسان باشد.\r\n- داده‌های قدیمی احتمالی شناسایی و بدون از دست‌رفتن اطلاعات مدیریت شده باشند.\r\n- خروجی JSON قابل بازیابی و قابل راستی‌آزمایی باشد.\r\n- ثبت محل نامعتبر یا ناقص به‌طور کنترل‌شده رد یا علامت‌گذاری شود.\r\n- آزمون حداقل ۲۰ کتاب و بررسی خروجی‌ها مستند شده باشد.\r\n- محدودیت‌های اتصال، ذخیره محلی و میزبانی برای کاربر روشن باشد.\r\n\r\nتا پیش از تحقق معیارهای فوق، ابزار باید «نسخه آزمایشی» باقی بماند و برای ثبت انبوه یا جایگزینی فهرست مرجع تأییدشده تلقی نشود.\r\n\r\n## ۱۲. اسناد مرتبط\r\n\r\n- [گزارش روزانه کتابخانه — ۱۴۰۵/۰۸/۰۳](گزارش%20روزانه%20کتابخانه%20-%201405-08-03.md)\r\n- [گزارش هفتگی کتابخانه — ۱۴۰۵/۰۸/۰۳](گزارش%20هفتگی%20کتابخانه%20-%201405-08-03.md)\r\n- [راهنمای ابزار](../../نرم‌افزار%20کتابخانه/README.md)\r\n- [کد برنامه](../../نرم‌افزار%20کتابخانه/index.html)\r\n- [مستند برچسب‌های قفسه و طبقه](../../نرم‌افزار%20کتابخانه/برچسب‌های%20قفسه%20و%20طبقه.md)\r\n- [گزارش تغییرات برنامه](../../نرم‌افزار%20کتابخانه/گزارش%20تغییرات.md)\r\n- [PR شماره ۳](https://github.com/forog1980-star/markaz-asnad-shohada/pull/3)\r\n\r\n---\r\n\r\n## ۱۳. جمع‌بندی نهایی\r\n\r\nدر این مرحله، نقشه عملیاتی قفسه‌ها و طبقات مشخص شده، برچسب‌های چاپی نمونه تولید و توسط کاربر بازبینی شده، و کدهای محل در ابزار و مستندات شاخه کاری هماهنگ شده‌اند. گزارش‌های روزانه و هفتگی نیز ثبت شده‌اند. بااین‌حال، آزمون واقعی، بازیابی JSON، مدیریت داده‌های قدیمی مرورگر و استقرار عملیاتی هنوز باز هستند. اولویت ادامه کار، حفاظت از داده و آزمون محدود و قابل بازگشت است؛ نه ادغام سریع یا اتصال به سامانه‌های عملیاتی.\r\n\r\n\r\n---\r\n\r\n## الحاقیه فنی — نسخه حداقلی ۰٫۲ و کنترل بازگشت (۱۴۰۵/۰۸/۰۴)\r\n\r\n### مبنای تغییر\r\nنسخه مبنا در شاخه `feature/software-ketabkhane-physical-audit-20261025` و commit `09c8e08bef2b58dc63952bcc2731e45d82ed83d8` باقی مانده است. تغییر جدید روی شاخه مستقل `feature/library-quick-inventory-v02-20261026` انجام شد؛ این شاخه از همان commit مبنا ساخته شد. `main` و PR شماره ۳ مستقیماً تغییر نکردند.\r\n\r\n### تغییرات کد\r\nفایل `نرم‌افزار کتابخانه/index.html` از ۱۵٬۲۵۳ به ۱۸٬۰۸۲ نویسه رسید. blob پیشین `c0d39576ff61b8bc05792ad225ce7b7264c30df0` و blob جدید `049beb48dbec6e42183a363f0b43fc198e538c50` است؛ commit تغییر `567f727d9a3586ddef425e99a222c7a3965a966a`.\r\n\r\n- بازیابی/ادغام JSON: ساختار پشتیبان بررسی می‌شود، رکوردهای بدون عنوان معتبر رد می‌شوند و کلیدهایی که از قبل در حافظه وجود دارند بازنویسی نمی‌شوند.\r\n- خروجی «تغییرات پیشنهادی برای بررسی Excel»: داده‌های ثبت‌شده را به CSV مستقل تبدیل می‌کند؛ خروجی، فایل مرجع را تغییر نمی‌دهد.\r\n- برای ذخیره رکوردی که «کتاب دیده شد» است، انتخاب قفسه و طبقه الزامی شد؛ انتخاب گروه موضوعی نیز برای ذخیره الزامی است.\r\n- برای ثبت کتاب خارج از فهرست، عنوان، موضوع و محل فیزیکی واقعی الزامی‌اند؛ رکورد همچنان جدا از فهرست مرجع می‌ماند.\r\n\r\n### نتیجه آزمون‌های انجام‌شده\r\n- کامپایل ایستای کد JavaScript بدون خطای نحوی: موفق.\r\n- بررسی وجود کنترل‌های جدید در HTML و قواعد اعتبارسنجی در کد: موفق.\r\n\r\n### آزمون‌های انجام‌نشده\r\n- اجرای واقعی در Chrome اندروید.\r\n- انتخاب و نگاشت شیت/ستون‌های فایل مرجع واقعی.\r\n- ذخیره و بازیابی JSON در مرورگر واقعی.\r\n- ثبت میدانی ۱۰ تا ۲۰ کتاب.\r\n- بازکردن CSV در Excel و تطبیق با رکوردهای مرجع.\r\n- آزمون پایداری `localStorage` پس از بستن/بازکردن مرورگر.\r\n\r\n### ملاحظه مرجع Excel\r\nفایل مرجع با مسیر `کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx` و commit ثبت اولیه `b93eaca408c3d921a8596dfdaf5f8c992bbf4bc` شناسایی شد. محتوای باینری از طریق ابزار موجود به‌صورت ساختاری بازخوانی نشد؛ بنابراین نام شیت، سرستون‌ها، شمار ردیف‌ها و شناسه‌های واقعی هنوز راستی‌آزمایی نشده‌اند. تا تکمیل این بررسی، هیچ تغییر Excel اعمال نمی‌شود.\r\n\r\n================ FILE: \\کتابخانه\\گزارش‌ها\\گزارش روزانه کتابخانه - 1405-08-03.md ================\r\n# گزارش روزانه کتابخانه مرکز اسناد\r\n**تاریخ:** ۱۴۰۵/۰۸/۰۳\r\n**مخزن رسمی:** `forog1980-star/markaz-asnad-shohada`\r\n**شاخه کاری:** `feature/software-ketabkhane-physical-audit-20261025`\r\n**موضوع:** تکمیل ابزار موقت تطبیق فیزیکی کتابخانه، برچسب‌های چاپی و هماهنگ‌سازی شناسه مکان\r\n\r\n## ۱. خلاصه اجرایی\r\nدر ادامه کارهای سامان‌دهی فیزیکی کتابخانه، برچسب‌های نمونه کتاب و برچسب‌های مکان با PowerShell و Microsoft Word تولید شدند. سپس کد ابزار وب کتابخانه و مستندات همان شاخه در GitHub بررسی شد. مشخص شد برنامه هنوز از شناسه‌های قدیمی قفسه استفاده می‌کند؛ این شناسه‌ها در ابزار و مستندات با نقشه عملیاتی جدید هماهنگ شدند. تغییرات فقط روی شاخه کاری انجام شده و به `main` ادغام نشده‌اند.\r\n\r\n## ۲. تصمیم‌ها و قواعد عملیاتی تثبیت‌شده\r\n- چهار قفسه عملیاتی: `SH-01`، `SH-02`، `SH-03` و `SH-04`.\r\n- هر قفسه شش طبقه دارد؛ از بالا به پایین: `T01` تا `T06`.\r\n- قالب نشانی کامل محل: `SH-01-T01`، `SH-03-T04` و مانند آن.\r\n- قفسه‌های `SH-01` و `SH-02` برای گروه R (روایت و خاطرات) در نظر گرفته شده‌اند؛ برآورد فعلی حدود ۵۸۰ عنوان است.\r\n- قفسه‌های `SH-03` و `SH-04` برای گروه‌های A، H، P، K و M در نظر گرفته شده‌اند؛ برآورد فعلی مجموع این گروه‌ها حدود ۳۶۲ عنوان است.\r\n- قفسه پنجم در حال حاضر خارج از نقشه عملیاتی این ابزار است.\r\n- شناسه کتاب و نشانی فیزیکی دو فیلد مستقل‌اند. جابه‌جایی کتاب باید محل را تغییر دهد، نه شناسه کتاب را.\r\n- نمونه شناسه‌های گروهی پیشنهادی: `GS-R-01`، `GS-A-01`، `GS-H-01`، `GS-P-01`، `GS-K-01` و `GS-M-01`. این نمونه‌ها به‌تنهایی به معنی ثبت شناسه پایدار برای همه کتاب‌ها نیستند.\r\n- جانمایی دقیق گروه‌های A، H، P، K و M در طبقات هنوز نهایی نشده است؛ محل‌های درج‌شده در نمونه‌های چاپی برای این گروه‌ها صرفاً نمایشی هستند.\r\n\r\n## ۳. کارهای انجام‌شده امروز\r\n### ۳.۱. فایل برچسب Word\r\n- اسکریپت PowerShell با Microsoft Word COM اجرا شد.\r\n- فایل خروجی با موفقیت ذخیره شد:\r\n  `C:\\Users\\Mahdi\\Desktop\\برچسب‌های کتابخانه مرکز اسناد.docx`\r\n- فایل شامل ۶ برچسب نمونه کتاب و ۲۴ برچسب مکان برای چهار قفسه و شش طبقه هر قفسه است.\r\n- کاربر فایل را در Word بررسی کرد و تأیید کرد ساختار، کادرها و صفحه‌بندی درست است.\r\n- جای علامت دونقطه در بعضی عبارت‌های فارسی نیازمند اصلاح دستی بود؛ پیشنهاد استفاده از خط تیره به‌جای دونقطه مطرح شد.\r\n- فایل Word روی رایانه کاربر ساخته شده است؛ فایل در مخزن GitHub بارگذاری نشده است.\r\n\r\n### ۳.۲. بررسی و اصلاح ابزار وب در GitHub\r\nفایل `نرم‌افزار کتابخانه/index.html` در شاخه کاری بررسی شد. منوی قفسه‌ها هنوز از شناسه‌های قدیمی `SHSF-01-Q01` تا `SHSF-01-Q06` استفاده می‌کرد. منوی انتخاب قفسه با چهار گزینه `SH-01` تا `SH-04` جایگزین شد. با انتخاب قفسه و طبقه، کد مکان به قالب `SH-xx-Txx` ساخته می‌شود.\r\n\r\nهمچنین این مستندات هماهنگ شدند:\r\n- `نرم‌افزار کتابخانه/README.md`\r\n- `نرم‌افزار کتابخانه/برچسب‌های قفسه و طبقه.md`\r\n\r\nسه تغییر در شاخه کاری ثبت شده‌اند:\r\n- اصلاح برنامه: commit `6dc3826b8f3dab7aa232e3265d78a057c6dd3d05`\r\n- اصلاح راهنما: commit `50d4fefb60d3983b0bfd1317294f1dd3db738903`\r\n- اصلاح مستند برچسب‌ها: commit `80818ed7ba9ee07f6c9382d6cb9905698c184aa5`\r\n\r\n## ۴. وضعیت ابزار موقت\r\nقابلیت‌های موجود در کد اولیه:\r\n- انتخاب فایل Excel و انتخاب شیت.\r\n- نگاشت ستون عنوان، نویسنده، ناشر و سال چاپ.\r\n- جست‌وجوی عنوان و انتخاب رکورد.\r\n- ثبت موضوع، محل فیزیکی، وضعیت مشاهده و توضیح کوتاه.\r\n- ثبت جداگانه کتابی که در فهرست پیدا نشده است.\r\n- نگهداری ثبت‌ها در حافظه مرورگر همان دستگاه.\r\n- خروجی CSV و پشتیبان JSON.\r\n\r\n## ۵. محدودیت‌ها و کارهای انجام‌نشده\r\n- برنامه هنوز روی گوشی واقعی با فایل مرجع و حداقل ۲۰ کتاب آزمایش نشده است.\r\n- استقرار آنلاین/HTTPS عملیاتی تأیید نشده است؛ تلاش پیشین برای ایجاد پروژه Vercel با خطای 403 مواجه شده بود.\r\n- بازیابی یا واردکردن پشتیبان JSON هنوز پیاده‌سازی و آزمون نشده است.\r\n- اعتبارسنجی اجباری محل فیزیکی برای ثبت کتاب دیده‌شده هنوز نیازمند بررسی/تکمیل است.\r\n- پس از تغییر کدهای قفسه، سازگاری ثبت‌های احتمالی قدیمی در حافظه مرورگر که با کدهای `SHSF-01-Qxx` ذخیره شده‌اند، باید بررسی شود؛ مهاجرت خودکار انجام نشده است.\r\n- ارتباط کتاب و شهید و تولید شناسه پایدار برای همه کتاب‌ها در این مرحله خارج از محدوده است.\r\n- فایل مرجع Excel و Supabase تغییر داده نشده‌اند.\r\n\r\n## ۶. گام بعدی پیشنهادی\r\n۱. بررسی سازگاری باقیمانده کدهای قدیمی و تعیین روش امن برای ثبت‌های موجود در مرورگر.\r\n۲. افزودن بازیابی پشتیبان JSON با کنترل نسخه و جلوگیری از جایگزینی ناخواسته داده‌ها.\r\n۳. اعتبارسنجی ثبت فیزیکی و کنترل انتخاب قفسه/طبقه.\r\n۴. آزمایش آفلاین/آنلاین در گوشی اندرویدی با ۲۰ کتاب واقعی، همراه با آزمون خروجی و بازیابی.\r\n۵. پس از آزمون موفق، بازبینی PR شماره ۳ و تصمیم جداگانه درباره ادغام و استقرار.\r\n\r\n## ۷. پیوندها\r\n- شاخه کاری: `feature/software-ketabkhane-physical-audit-20261025`\r\n- PR پیش‌نویس شماره ۳: https://github.com/forog1980-star/markaz-asnad-shohada/pull/3\r\n- ابزار: `نرم‌افزار کتابخانه/index.html`\r\n\r\n**وضعیت پایان روز:** تولید برچسب Word موفق؛ شناسه‌های مکان در کد و مستندات شاخه کاری هماهنگ شدند؛ آزمون واقعی و استقرار هنوز انجام نشده‌اند.\r\n\r\n================ FILE: \\کتابخانه\\گزارش‌ها\\گزارش روزانه کتابخانه - 1405-08-04.md ================\r\n# گزارش روزانه کتابخانه مرکز اسناد\r\n**تاریخ گزارش:** ۱۴۰۵/۰۸/۰۴ (۲۶ اکتبر ۲۰۲۶)\r\n**مخزن رسمی:** `forog1980-star/markaz-asnad-shohada`\r\n**شاخه کاری مورد استفاده:** `feature/software-ketabkhane-physical-audit-20261025`\r\n**موضوع:** تثبیت جانمایی و برچسب‌های کتابخانه؛ تغییر اولویت به ثبت سریع موجودی فیزیکی با گوشی\r\n\r\n## ۱. خلاصه اجرایی\r\nدر ادامه سامان‌دهی فیزیکی کتابخانه مرکز اسناد، نقشه چهار قفسه و شش طبقه هر قفسه تثبیت شد. نسخه Word برچسب‌ها با PowerShell و Microsoft Word روی رایانه کاربر تولید شد و کاربر بازشدن فایل و درست‌بودن کلی چیدمان را تأیید کرد. اکنون اولویت اصلی، ساخت یک ابزار کوچک و سریع برای گوشی اندرویدی جهت فهرست‌برداری موجودی واقعی کتاب‌ها، ثبت/تعیین شناسه و موضوع، ثبت محل فیزیکی و آماده‌سازی اطلاعات برای به‌روزرسانی کنترل‌شده فهرست Excel است.\r\n\r\nاین گزارش برای ادامه در گفت‌وگوی جدید نوشته شده تا وضعیت، تصمیم‌ها، محدودیت‌ها و گام آغاز برنامه‌نویسی بدون نیاز به بازگویی از سوی کاربر در دسترس باشد.\r\n\r\n## ۲. تصمیم‌های فیزیکی قطعی\r\n\r\n### ۲.۱ نقشه قفسه‌ها\r\n- چهار قفسه عملیاتی: `SH-01`، `SH-02`، `SH-03` و `SH-04`.\r\n- هر قفسه شش طبقه دارد؛ شماره‌گذاری از بالا به پایین: `T01` تا `T06`.\r\n- کد محل کامل از ترکیب قفسه و طبقه ساخته می‌شود؛ نمونه: `SH-01-T01`.\r\n- قفسه پنجم در نقشه جاری این مرحله وارد نشده است.\r\n- شناسه کتاب با کد محل فیزیکی یکی نیست. جابه‌جایی کتاب باید محل را تغییر دهد، نه شناسه کتاب را.\r\n\r\n### ۲.۲ جانمایی گروه‌ها\r\n| محل | گروه | عنوان موضوع |\r\n|---|---|---|\r\n| `SH-01`، همه طبقات | R | روایت و خاطرات |\r\n| `SH-02`، همه طبقات | R | روایت و خاطرات |\r\n| `SH-03-T01` | H | تاریخ و اسناد |\r\n| `SH-03-T02` | A | ادبیات و هنر |\r\n| `SH-03-T03` و `SH-03-T04` | P | پژوهش و تحلیل |\r\n| `SH-03-T05` و `SH-03-T06` | M | متفرقه |\r\n| `SH-04-T01` | K | کودک و نوجوان |\r\n| `SH-04-T02` تا `SH-04-T06` | آزاد | ظرفیت توسعه یا جابه‌جایی آتی |\r\n\r\nتقسیم بالا طبق تصمیم کاربر تثبیت شده است. تخصیص ظرفیت طبقه‌ای با نیاز تقریبی کتاب‌ها تنظیم شده و ممکن است بخشی از ظرفیت هر طبقه خالی بماند. این فضا عمداً برای نظم و امکان توسعه نگه داشته می‌شود.\r\n\r\n### ۲.۳ تعداد برچسب‌های نهایی\r\n- برچسب موضوعی R: دو عدد؛ یکی بالای `SH-01` و دیگری بالای `SH-02`.\r\n- برچسب موضوعی H، A و K: هرکدام یک عدد.\r\n- برچسب موضوعی P و M: هرکدام دو عدد، مطابق طبقات تخصیص‌یافته.\r\n- مجموع برچسب موضوعی: **۹ عدد**.\r\n- برچسب محل فیزیکی: **۲۴ عدد** برای چهار قفسه × شش طبقه.\r\n- نمونه برچسب کتاب در فایل: **۶ عدد**.\r\n- نسخه Word نهایی محلی شامل مجموعاً ۳۹ کادر برچسب در سه بخش است: ۶ نمونه کتاب، ۹ موضوعی و ۲۴ محل.\r\n\r\n## ۳. وضعیت فایل Word برچسب‌ها\r\n- اسکریپت PowerShell با Word COM اجرا شد.\r\n- فایل خروجی جدید: `C:\\Users\\Mahdi\\Desktop\\برچسب‌های کتابخانه مرکز اسناد - نسخه نهایی.docx`.\r\n- کاربر تأیید کرد فایل باز می‌شود و چیدمان کلی درست است.\r\n- فایل قبلی با نام متفاوت نگه داشته شده و خروجی جدید روی فایل قبلی نوشته نشده است.\r\n- خطای پایانی که هنگام اجرای جداگانه کلمه `finally` رخ داد، ناشی از واردکردن بلوک `finally` پس از پایان بلوک `try/catch` به‌صورت مستقل بود؛ فایل پیش از آن ذخیره شده بود و کاربر بازشدن آن را تأیید کرد.\r\n- هنوز چاپ آزمایشی کاغذی تأیید نشده است.\r\n- فایل Word روی رایانه کاربر ساخته شده و در مخزن GitHub ثبت نشده است؛ این کار عمدی است و نیازی به بارگذاری فایل محلی در مخزن نیست مگر اینکه کاربر بعداً بخواهد.\r\n\r\n## ۴. سابقه ابزار موقت تطبیق فیزیکی\r\nابزار فعلی در مسیر `نرم‌افزار کتابخانه/index.html` یک صفحه وب مستقل و آزمایشی است. در نسخه موجود قابلیت‌هایی مانند انتخاب فایل Excel و شیت، نگاشت ستون عنوان/نویسنده/ناشر/سال، جست‌وجوی عنوان، ثبت موضوع و محل، وضعیت مشاهده، توضیح، ثبت کتاب پیدا‌نشده، ذخیره محلی در مرورگر و خروجی CSV/JSON وجود دارد یا در کد پیش‌بینی شده است. این قابلیت‌ها هنوز به‌طور کامل در گوشی واقعی آزمون نشده‌اند.\r\n\r\nدر شاخه کاری، منوی مکان از قالب قدیمی `SHSF-01-Q01` به چهار قفسه `SH-01` تا `SH-04` و طبقات `T01` تا `T06` هماهنگ شده است. تغییرات مربوط در commits پیشین شاخه ثبت شده‌اند؛ `main` تغییر نکرده است.\r\n\r\n## ۵. وضعیت فنی و ریسک‌های ابزار قبلی\r\n- شاخه کاری: `feature/software-ketabkhane-physical-audit-20261025`.\r\n- PR پیش‌نویس شماره ۳: https://github.com/forog1980-star/markaz-asnad-shohada/pull/3\r\n- برنامه: `نرم‌افزار کتابخانه/index.html`.\r\n- راهنما: `نرم‌افزار کتابخانه/README.md`.\r\n- تغییرات کد و مستندات به `main` ادغام نشده‌اند.\r\n- اجرای واقعی در گوشی اندرویدی با فایل مرجع و ۲۰ کتاب هنوز مستند نشده است.\r\n- استقرار HTTPS عملیاتی تأیید نشده است؛ تلاش قبلی برای ایجاد پروژه Vercel با خطای 403 مواجه شد.\r\n- بازیابی/ورود JSON هنوز پیاده‌سازی و آزمون نشده است.\r\n- ذخیره محلی مرورگر می‌تواند با پاک‌شدن داده‌های مرورگر از دست برود.\r\n- داده‌های احتمالی قدیمی با کدهای `SHSF-01-Qxx` باید پیش از هر مهاجرت یا پاک‌سازی بررسی و پشتیبان‌گیری شوند.\r\n- فایل Excel مرجع و Supabase در تغییرات پیشین دست‌نخورده باقی مانده‌اند.\r\n\r\n## ۶. مرجع Excel و اصول داده\r\nفایل مرجع کاری فعلی:\r\n`کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx`\r\n\r\nاین فایل مرجع معتبر کاری است و داده‌های آن باید با احتیاط حفظ شوند. کاربر اکنون صریحاً اولویت را روی فهرست‌برداری موجودی فیزیکی، نام‌گذاری/شناسه‌گذاری کتاب‌ها و به‌روزرسانی فهرست Excel قرار داده است. بنابراین برنامه جدید باید برای ورود اطلاعات میدانی و تهیه خروجی به‌روزرسانی طراحی شود؛ اما تا زمانی که ساختار شیت‌ها و روش امن اعمال تغییرات روشن نشده، نباید بی‌اجازه فایل مرجع را بازنویسی کند. ابتدا نسخه پشتیبان جداگانه، تطبیق ستون‌ها، پیش‌نمایش تغییرات و خروجی قابل بازبینی در نظر گرفته شود.\r\n\r\nقواعد ثابت:\r\n- ثبت فیزیکی باید با خود کتاب روی قفسه تطبیق داده شود؛ صرف وجود عنوان در فهرست، وجود فیزیکی را ثابت نمی‌کند.\r\n- شناسه کتاب و نشانی محل مستقل‌اند.\r\n- رکوردهای ناقص، تکراری یا مشکوک نباید خودکار حذف یا ادغام شوند.\r\n- ارتباط کتاب و شهید فعلاً در اولویت این مرحله نیست و نباید باعث پیچیده‌شدن ابزار ثبت موجودی شود.\r\n- این ابزار موقت، به‌خودی‌خود مجوز تغییر Supabase یا انتشار عمومی داده‌ها ایجاد نمی‌کند.\r\n\r\n## ۷. اولویت جدید کاربر: برنامه کوچک ثبت کتاب با گوشی\r\nکاربر می‌خواهد در همان روز، کار برنامه‌نویسی ابزار کوچک ثبت فیزیکی کتاب‌ها را آغاز کند. هدف فوری، ساخت سامانه جامع یا قابلیت هوش مصنوعی نیست؛ هدف ابزار عملیاتی بسیار ساده برای یک نفر و یک گوشی اندرویدی است تا هنگام برداشتن کتاب بتواند سریع آن را پیدا/ثبت کند، عنوان و اطلاعات کتاب را ثبت یا تطبیق دهد، موضوع و محل را تعیین کند و در پایان داده‌ها را برای به‌روزرسانی Excel آماده کند.\r\n\r\n### نیازهای حداقلی که باید در شروع کدنویسی بررسی و تثبیت شوند\r\n1. رابط فارسی و راست‌به‌چپ، مناسب صفحه گوشی و ورودی لمسی.\r\n2. ثبت سریع عنوان کتاب و در صورت موجودبودن: نویسنده، ناشر، سال چاپ؛ فیلدهای اختیاری نباید ثبت اولیه را متوقف کنند.\r\n3. ثبت گروه موضوعی R/A/H/P/K/M.\r\n4. ثبت محل با کدهای معتبر `SH-xx-Txx` مطابق نقشه تثبیت‌شده.\r\n5. امکان ثبت کتابی که در Excel پیدا نمی‌شود، بدون ساختن رکورد جعلی یا حذف رکوردهای مشابه.\r\n6. شناسه موقت/پیشنهادی قابل ردیابی برای رکوردهای تازه، با جلوگیری از تکرار؛ قاعده نهایی شناسه دائمی باید پیش از اعمال انبوه مشخص شود.\r\n7. ذخیره پایدار محلی و امکان تهیه پشتیبان؛ راهکار نباید به اینترنت دائمی وابسته فرض شود.\r\n8. خروجی مناسب بررسی و به‌روزرسانی Excel، با کنترل تعداد رکوردها و نگهداری اطلاعات اصلی.\r\n9. کمترین تعداد لمس/صفحه برای ثبت یک کتاب؛ تمرکز بر سرعت فهرست‌برداری، نه داشبورد یا امکانات جانبی.\r\n10. آزمون با نمونه کوچک واقعی پیش از ثبت انبوه.\r\n\r\n### نکته تصمیم‌گیری فنی\r\nپیش از نوشتن کد جدید، در گفت‌وگوی بعدی باید وضعیت فعلی شاخه، فایل‌های موجود و کد ابزار قبلی دوباره بررسی شوند تا کار تکراری انجام نشود. سپس تصمیم گرفته شود ابزار فعلی در یک شاخه جدید و جداگانه ساده‌سازی/تکمیل شود یا یک صفحه مستقل جدید ساخته شود. تا قبل از بررسی، فرض نکنیم که ابزار قبلی قابل استفاده کامل است یا باید دور انداخته شود.\r\n\r\n## ۸. گام‌های آغازین در گفت‌وگوی جدید\r\n1. ابتدا همین گزارش و `نرم‌افزار کتابخانه/index.html`، `README.md` و گزارش فنی جاری را بخوان.\r\n2. وضعیت branch، آخرین commitها و PR شماره ۳ را از GitHub بررسی کن؛ تغییرات را روی `main` انجام نده.\r\n3. ساختار واقعی فایل Excel مرجع و شیت «فهرست کتاب‌ها» را بررسی کن؛ تا وقتی ساختار دقیق دیده نشده، نام ستون یا شماره ستون را حدس نزن.\r\n4. محدوده نسخه اول را به فرم ثبت سریع و خروجی قابل بررسی محدود کن.\r\n5. داده‌ها را ابتدا در یک فایل/فضای کاری مستقل نگه دار؛ برای به‌روزرسانی Excel، ابتدا نسخه پشتیبان و گزارش تغییرات بساز.\r\n6. یک نمونه آزمایشی ۱۰ تا ۲۰ کتاب را ثبت و خروجی را با Excel تطبیق بده؛ پس از موفقیت، استفاده وسیع‌تر.\r\n7. همه تغییرات، آزمون‌های واقعی و موارد تأییدنشده را در گزارش روزانه و فنی ثبت کن.\r\n\r\n## ۹. نقطه ادامه\r\n**اولویت فعلی:** ساخت ابزار سریع ثبت موجودی فیزیکی کتابخانه با گوشی و آماده‌سازی داده برای به‌روزرسانی کنترل‌شده Excel.\r\n**اولویت‌های تعویق‌افتاده:** بازیابی JSON ابزار قبلی، مدیریت داده‌های قدیمی مرورگر، استقرار HTTPS و ادغام PR #3؛ این‌ها باید در صورت نیاز به ابزار قبلی بررسی شوند، اما نباید تمرکز کاربر را از فهرست‌برداری سریع کتاب‌ها منحرف کنند.\r\n**حفاظت از داده:** هیچ فایل مرجع، داده ذخیره‌شده یا رکوردی را بدون نسخه پشتیبان و بررسی حذف یا بازنویسی نکن.\r\n**وضعیت برچسب‌ها:** فایل Word محلی ساخته شده و کاربر چیدمان آن را تأیید کرده است؛ چاپ آزمایشی هنوز تأیید نشده.\r\n\r\n---\r\n\r\n**یادداشت وضعیت:** این گزارش تصمیم‌ها و وضعیت شناخته‌شده تا تاریخ فوق را ثبت می‌کند. آزمون‌هایی که هنوز اجرا نشده‌اند، موفق تلقی نمی‌شوند.\r\n\r\n---\r\n\r\n## الحاقیه اجرایی — نسخه حداقلی ۰٫۲ ابزار ثبت فیزیکی (۱۴۰۵/۰۸/۰۴)\r\n\r\n### بررسی پیش از تغییر\r\n- شاخه مبنای بررسی: `feature/software-ketabkhane-physical-audit-20261025`؛ commit مبنا `09c8e08bef2b58dc63952bcc2731e45d82ed83d8`.\r\n- PR شماره ۳ همچنان پیش‌نویس و ادغام‌نشده است؛ `main` تغییر داده نشد.\r\n- فایل ابزار موجود `نرم‌افزار کتابخانه/index.html` بررسی شد. قابلیت‌های قبلی شامل بارگذاری Excel، انتخاب شیت، نگاشت ستون‌ها، جست‌وجو، ثبت میدانی، ذخیره `localStorage` و خروجی CSV/JSON بود؛ بازیابی JSON در نسخه پیشین وجود نداشت.\r\n- فایل مرجع در مخزن `main` با مسیر `کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx` و commit مرجع `b93eaca408c3d921a8596dfdaf5f8c992bbf4bc` شناسایی شد. محتوای باینری فایل از طریق ابزار بررسی GitHub به‌صورت ساختاری بازخوانی نشد؛ بنابراین نام شیت‌ها و ستون‌های واقعی در این مرحله هنوز راستی‌آزمایی نشده‌اند و به‌روزرسانی Excel انجام نشده است.\r\n\r\n### نقطه بازگشت و تغییر\r\n- شاخه جدید و جداگانه: `feature/library-quick-inventory-v02-20261026`، ساخته‌شده از commit مبنای بالا؛ شاخه `main` و فایل مرجع تغییر نکردند.\r\n- فایل تغییرکرده: `نرم‌افزار کتابخانه/index.html`؛ نسخه قبل ۱۵٬۲۵۳ نویسه و blob `c0d39576ff61b8bc05792ad225ce7b7264c30df0`؛ نسخه پس از تغییر ۱۸٬۰۸۲ نویسه و blob `049beb48dbec6e42183a363f0b43fc198e538c50`.\r\n- commit تغییر کد: `567f727d9a3586ddef425e99a222c7a3965a966a`.\r\n- قابلیت‌های افزوده‌شده: ادغام امن پشتیبان JSON بدون بازنویسی کلیدهای موجود، خروجی CSV تغییرات پیشنهادی برای بررسی Excel، الزام ثبت گروه موضوعی و الزام محل واقعی برای ثبت کتاب دیده‌شده، و کلید تصادفی‌تر برای ثبت خارج از فهرست.\r\n\r\n### آزمون و محدودیت\r\n- بررسی نحوی JavaScript با کامپایل ایستا انجام شد: موفق.\r\n- کنترل حضور دکمه‌ها و کنترل‌های جدید و قواعد اعتبارسنجی در فایل انجام شد: موفق.\r\n- آزمون واقعی در مرورگر/گوشی اندرویدی، بازیابی JSON واقعی، آزمون با ۱۰ تا ۲۰ کتاب، و بازکردن خروجی در Excel هنوز انجام نشده‌اند.\r\n- فایل Excel مرجع، Supabase و `main` تغییر نکردند.\r\n\r\n### گام بعدی\r\n۱. بررسی ساختار واقعی شیت و سرستون‌های Excel با نسخه محلی/دریافت‌شده و ثبت تعداد ردیف‌ها.\r\n۲. اجرای آزمایش مرورگر با فایل نمونه و پشتیبان آزمایشی.\r\n۳. آزمون میدانی ۱۰ تا ۲۰ کتاب و گرفتن پشتیبان در پایان.\r\n۴. بازبینی CSV تغییرات و تهیه روش اعمال تغییرات روی یک کپی تاریخ‌دار از Excel؛ هرگز روی فایل مرجع بدون پشتیبان اعمال نشود.\r\n۵. ثبت نتایج واقعی و سپس تصمیم درباره PR و استقرار HTTPS.\r\n\r\n================ FILE: \\نرم‌افزار ثبت کتاب‌ها و شهدا\\docs\\طرح-اجرایی-نسخه-اول-برنامه-کتابخانه-نسخه-۰٫۱.md ================\r\n# طرح اجرایی نسخه اول برنامه کتابخانه مرکز اسناد گلزار شهدای تهران\r\n\r\n**نسخه پیشنهادی ۰٫۱ — مبنای شروع پیاده‌سازی**\r\n\r\nبا توجه به تصمیمی که گرفتیم، پیشنهاد می‌کنم نسخه اول را به‌عنوان یک سامانه سبک مدیریت کتاب‌ها و منابع مرتبط با شهدا بسازیم؛ نه یک نرم‌افزار کتابخانه عمومی و نه هنوز سامانه جامع مرکز اسناد.\r\n\r\nهدف این است که چند نفر بتوانند از چند رایانه اطلاعات را ثبت و جست‌وجو کنند، مطالب مرتبط با شهدا را مستند کنند و گزارش بگیرند؛ درحالی‌که شماره‌گذاری کتاب‌ها و دسته‌بندی فیزیکی هنوز در حال انجام است.\r\n\r\nیک نکته فنی مهم: چون برنامه باید از چند رایانه استفاده شود، نسخه اصلی را نباید به‌صورت چند فایل پایگاه داده جداگانه روی هر رایانه بسازیم. پیشنهاد من برنامه تحت وب داخلی با پایگاه داده مرکزی است که در شبکه محل کار اجرا شود و در صورت نیاز، بعداً برای دسترسی کنترل‌شده از راه دور توسعه پیدا کند.\r\n\r\n## ۱. معماری پیشنهادی\r\n\r\n- **رایانه کاربران:** ثبت کتاب، جست‌وجو، استخراج مطالب و گزارش‌ها.\r\n- **برنامه مرکزی در شبکه داخلی:** رابط فارسی و راست‌چین، قواعد اعتبارسنجی، کاربران و سطح دسترسی.\r\n- **پایگاه داده مشترک:** کتاب‌ها، شهدا، ارتباط‌ها، مطالب استخراج‌شده، تاریخچه و وضعیت بررسی.\r\n- **ورود اولیه از Excel:** واردسازی کنترل‌شده همراه با گزارش مبدأ و خطاها.\r\n- **خروجی و پشتیبان:** خروجی گزارش‌ها و نسخه پشتیبان قابل بازیابی.\r\n\r\nبرای شروع، گزینه فنی مناسب می‌تواند Python + رابط وب سبک + PostgreSQL باشد. PostgreSQL برای استفاده هم‌زمان چند کاربر مناسب‌تر از این است که فایل SQLite را بین چند رایانه به اشتراک بگذاریم.\r\n\r\nاین انتخاب هنوز قطعی نیست؛ ابتدا باید مشخص شود شبکه داخلی و رایانه‌ای که قرار است برنامه روی آن اجرا شود، چه امکاناتی دارند. همچنین در این مرحله نیازی به GitHub، Vercel یا اینترنت عمومی نداریم.\r\n\r\n## ۲. امکانات نسخه اول\r\n\r\nنسخه اول را به شش بخش محدود می‌کنیم تا در زمان کوتاه قابل ساخت و آزمون باشد.\r\n\r\n### الف) مدیریت کتاب‌ها\r\n\r\n- ثبت عنوان، ناشر، نویسنده و توضیحات\r\n- شناسه داخلی ثابت برای هر رکورد\r\n- ثبت وضعیت بررسی فیزیکی و محل فعلی\r\n- نگهداری دسته‌بندی موضوعی و امکان تغییر آن\r\n- علامت‌گذاری عنوان‌های مشابه برای بررسی، بدون حذف خودکار\r\n\r\n### ب) پرونده شهدا و ارتباط‌ها\r\n\r\n- ثبت نام و نام خانوادگی شهید\r\n- اتصال یک کتاب به یک یا چند شهید\r\n- اتصال یک شهید به چند کتاب\r\n- ثبت قطعه، ردیف و شماره مزار با وضعیت تأیید\r\n- نگهداری اطلاعات اولیه فایل‌ها حتی اگر هنوز تأیید نشده باشند\r\n\r\n### ج) ثبت مطالب استخراج‌شده\r\n\r\n- اتصال مطلب به کتاب و شهید مربوط\r\n- شماره صفحه یا بازه صفحات\r\n- متن استخراج‌شده یا خلاصه پژوهشگر\r\n- نوع مطلب: زندگی‌نامه، خاطره، وصیت‌نامه، سند، اشاره کوتاه و مانند آن\r\n- وضعیت بررسی و تأیید علمی، همراه با نام ثبت‌کننده\r\n\r\n### د) جست‌وجوی سریع\r\n\r\n- جست‌وجو بر اساس عنوان، ناشر، شهید، دسته‌بندی یا شناسه\r\n- نمایش همه کتاب‌های مرتبط با یک شهید\r\n- نمایش صفحات و مطالب استخراج‌شده برای هر شهید\r\n- فیلتر اطلاعات ناقص، بررسی‌نشده و تأییدشده\r\n\r\n### هـ) گزارش‌گیری\r\n\r\n- تعداد رکوردهای کتاب و تعداد کتاب‌های دارای موجودی تأییدشده\r\n- کتاب‌های مرتبط با شهدا\r\n- مطالب استخراج‌شده و مطالب تأییدشده\r\n- کتاب‌های فاقد دسته‌بندی یا محل مشخص\r\n- ارتباط‌های ناقص و عنوان‌های مشابه\r\n- خروجی Excel برای گزارش‌های مدیریتی\r\n\r\n### و) کاربران و حفاظت از داده\r\n\r\n- ورود با حساب کاربری\r\n- نقش‌های اولیه: مدیر سامانه، ثبت‌کننده و بازبین\r\n- ثبت زمان و کاربر ایجادکننده یا ویرایش‌کننده\r\n- پشتیبان‌گیری و امکان بازیابی آزمایشی\r\n- جلوگیری از حذف ناخواسته و ثبت تغییرات مهم\r\n\r\n## ۳. ساختار داده‌ها\r\n\r\nپیشنهاد می‌کنم اطلاعات در چند جدول مرتبط ذخیره شوند، نه یک جدول بزرگ که اطلاعات شهید و کتاب در آن تکرار شود.\r\n\r\n| جدول | اطلاعات اصلی |\r\n|---|---|\r\n| books | شناسه ثابت کتاب، عنوان، ناشر، نویسنده، توضیحات، دسته و وضعیت فیزیکی |\r\n| martyrs | شناسه داخلی شهید، نام و نام خانوادگی و وضعیت بررسی هویت |\r\n| book_martyr_links | ارتباط کتاب و شهید، نوع ارتباط و وضعیت تأیید |\r\n| extracted_items | متن یا خلاصه، صفحات، نوع مطلب، کتاب و شهید مرتبط |\r\n| locations | محل فیزیکی فعلی کتاب و تاریخ آخرین بررسی |\r\n| grave_locations | قطعه، ردیف و شماره مزار، منبع داده و وضعیت تأیید |\r\n| categories | دسته‌بندی شش‌گانه و تغییرات بعدی آن |\r\n| users | حساب کاربری، نقش و وضعیت دسترسی |\r\n| audit_log | تغییرات مهم و سابقه عملیات |\r\n| import_records | فایل مبدأ، شیت، ردیف اصلی و نتیجه ورود اطلاعات |\r\n\r\n### چند قاعده مهم در طراحی\r\n\r\n۱. شناسه داخلی کتاب از شماره نهایی کتابخانه جداست. می‌توانیم از روز اول شناسه‌ای مانند **BK-000001** بسازیم؛ این فقط شناسه سامانه است و به معنی شماره‌گذاری نهایی فیزیکی نیست.\r\n\r\n۲. هر کتاب می‌تواند به چند شهید متصل باشد. در شیت «چند شهید»، باید ردیف‌های ادامه‌دار به کتاب مربوط متصل شوند؛ نه اینکه هر ردیف به‌عنوان یک کتاب مستقل وارد شود.\r\n\r\n۳. عنوان مشابه مساوی کتاب تکراری نیست. تفاوت ناشر، نویسنده، چاپ و مشخصات نسخه باید بررسی شود.\r\n\r\n۴. موجودی واقعی از آمار خرید اولیه جدا می‌ماند. تعداد نسخه موجود فقط پس از بررسی فیزیکی تأیید می‌شود. مقدار اولیه ستون «تعداد» در صورت نیاز، صرفاً در اطلاعات خام واردشده از فایل حفظ می‌شود و مبنای گزارش موجودی فعلی نیست.\r\n\r\n۵. دسته‌بندی و محل کتاب قابل تغییرند. تغییر قفسه یا دسته‌بندی نباید شناسه و سابقه ارتباط‌های پژوهشی کتاب را از بین ببرد.\r\n\r\n۶. هر مطلب استخراج‌شده باید ردّ منبع داشته باشد. حداقل شناسه کتاب و صفحه، و در صورت ارتباط با شهید، شناسه شهید ثبت می‌شود. متن استخراج‌شده تا زمان تأیید بازبین، قطعی تلقی نمی‌شود.\r\n\r\n## ۴. روش ورود اطلاعات از سه فایل Excel\r\n\r\nورود داده باید کنترل‌شده باشد. پیشنهاد نمی‌کنم فایل‌ها مستقیماً در جداول اصلی وارد شوند؛ ابتدا یک مرحله ورود موقت داشته باشیم.\r\n\r\n۱. از هر سه فایل یک نسخه اصلی و دست‌نخورده نگه می‌داریم.\r\n۲. برنامه، اطلاعات هر شیت را همراه با نام فایل، نام شیت و شماره ردیف مبدأ وارد مرحله بررسی می‌کند.\r\n۳. عنوان‌های مشابه، فیلدهای خالی، مقادیر غیرعادی و ردیف‌های ادامه‌دار علامت‌گذاری می‌شوند.\r\n۴. قواعد هر فایل جداگانه اعمال می‌شود؛ مخصوصاً ساختار «یک شهید» و «چند شهید» و شیت نشانی مزار.\r\n۵. رکوردهای قابل ورود ثبت می‌شوند و موارد مبهم برای بررسی دستی باقی می‌مانند.\r\n۶. گزارش ورود شامل تعداد ردیف‌های خوانده‌شده، واردشده، نیازمند بررسی و خطادار تهیه می‌شود.\r\n\r\nدر این مرحله نباید صرفاً بر اساس نام شهید یا عنوان کتاب، دو رکورد را خودکار یکی کنیم. تطبیق خودکار می‌تواند پیشنهاد بدهد، اما ادغام نهایی باید قابل بررسی و برگشت باشد.\r\n\r\nهمچنین چون تا اینجا فقط ساختار و بخشی از ردیف‌های فایل‌ها را مشاهده کرده‌ایم، تعداد نهایی رکوردهای قابل ورود را باید پس از خواندن کامل فایل‌ها اعلام کنیم.\r\n\r\n## ۵. مراحل پیاده‌سازی و زمان‌بندی\r\n\r\n### روز ۱ — مرحله صفر: بررسی محیط و تثبیت طرح\r\n\r\nبررسی رایانه میزبان، شبکه داخلی، نسخه Python و امکانات پشتیبان‌گیری؛ نهایی‌کردن ساختار داده و تهیه نسخه آزمایشی از سه فایل.\r\n\r\n### روز ۲–۳ — مرحله اول: پایگاه داده و ورود اولیه\r\n\r\nساخت جداول، شناسه‌های داخلی، ابزار ورود Excel و گزارش خطاها و موارد مشکوک.\r\n\r\n### روز ۴–۶ — مرحله دوم: رابط کاربری\r\n\r\nصفحه کتاب‌ها، پرونده شهدا، ثبت ارتباط‌ها، فرم استخراج مطلب و جست‌وجوی فارسی.\r\n\r\n### روز ۷–۸ — مرحله سوم: گزارش و دسترسی چندکاربره\r\n\r\nداشبورد، خروجی Excel، نقش‌های کاربران، سابقه تغییرات و پشتیبان‌گیری.\r\n\r\n### روز ۹–۱۰ — مرحله چهارم: آزمون و اجرای آزمایشی\r\n\r\nبررسی صحت ورود اطلاعات، آزمون هم‌زمانی کاربران، بازیابی پشتیبان و اصلاح خطاها.\r\n\r\nاین زمان‌بندی برای یک نسخه اولیه محدود، با فرض آماده‌بودن محیط و نبود مانع جدی، برآورد است. آماده‌سازی شبکه، ورود کامل داده‌ها یا اصلاح ساختارهای پیچیده Excel ممکن است زمان بیشتری بخواهد. بهتر است ابتدا روی نمونه داده آزمایش کنیم و سپس ورود کامل را انجام دهیم.\r\n\r\n## ۶. آزمون‌هایی که پیش از استفاده واقعی باید بگذرند\r\n\r\n| آزمون | معیار قبولی |\r\n|---|---|\r\n| ورود Excel | تعداد رکوردهای خوانده‌شده با گزارش ورود قابل تطبیق باشد؛ خطاها پنهان نشوند. |\r\n| عنوان‌های مشابه | هیچ رکوردی صرفاً به‌دلیل تشابه عنوان خودکار حذف نشود. |\r\n| ارتباط چندشهیدی | یک کتاب به چند شهید متصل شود و هر ارتباط جداگانه قابل مشاهده باشد. |\r\n| استخراج مطالب | صفحه، منبع و شهید مرتبط بدون اشتباه ثبت و بازیابی شوند. |\r\n| جست‌وجوی فارسی | جست‌وجو با «ی/ي»، «ک/ك» و فاصله‌های متداول نتایج قابل انتظار بدهد، بدون حذف تفاوت‌های واقعی نام‌ها. |\r\n| استفاده هم‌زمان | دو کاربر بتوانند اطلاعات متفاوت را ثبت کنند، بدون اینکه تغییرات یکدیگر را ناخواسته از بین ببرند. |\r\n| سطح دسترسی | کاربر ثبت‌کننده نتواند عملیات مخصوص مدیر را انجام دهد. |\r\n| پشتیبان و بازیابی | نسخه پشتیبان در محیط آزمایشی بازیابی و صحت داده‌ها کنترل شود. |\r\n| تغییر محل کتاب | محل جدید ثبت شود و شناسه کتاب و سابقه مطالب آن ثابت بماند. |\r\n| گزارش‌گیری | اعداد داشبورد با داده‌های واقعی پایگاه داده تطبیق داشته باشند. |\r\n\r\n## ۷. حفاظت از اطلاعات و امکان توسعه\r\n\r\nچون این سامانه قرار است به‌تدریج به مرکز اسناد متصل شود، از ابتدا این اصول را رعایت می‌کنیم:\r\n\r\n- نسخه اصلی داده‌ها روی یک میزبان مشخص و تحت مدیریت مرکز نگهداری شود.\r\n- دسترسی شبکه محدود و حساب‌های کاربری مجزا باشند.\r\n- پشتیبان‌گیری منظم و بازیابی آزمایش‌شده داشته باشیم.\r\n- اطلاعات خام ورودی، سوابق تغییرات و وضعیت تأیید پژوهشی حفظ شوند.\r\n- فعلاً هیچ انتشار عمومی، اتصال به چت‌بات یا انتشار متن کتاب‌ها در اینترنت انجام نشود.\r\n- ساختار داده طوری طراحی شود که بعداً منابعی مانند اسناد، عکس‌ها، فایل‌های صوتی و سایر مواد آرشیوی نیز قابل افزودن باشند.\r\n\r\n## ۸. برای شروع عملی، یک موضوع فنی باید مشخص شود\r\n\r\nپیش از نوشتن کد، لازم است بدانیم برنامه مرکزی کجا اجرا خواهد شد؛ چون انتخاب پایگاه داده، روش دسترسی کاربران و نحوه پشتیبان‌گیری به این تصمیم وابسته است.\r\n\r\n### ۱. کدام رایانه قرار است میزبان برنامه باشد؟\r\n\r\n- یکی از رایانه‌های موجود در محل کتابخانه\r\n- یک رایانه یا سرور اختصاصی که بعداً تهیه می‌شود\r\n- هنوز مشخص نیست؛ ابتدا محیط را بررسی کنیم\r\n\r\n### ۲. رایانه‌های کاربران چه وضعیتی دارند؟\r\n\r\n- به یک شبکه داخلی مشترک متصل‌اند\r\n- در محل‌های جدا هستند و شبکه مشترک ندارند\r\n- هنوز بررسی نکرده‌ام\r\n\r\n### ۳. محدودیت اینترنت چگونه است؟\r\n\r\n- باید کاملاً بدون اینترنت کار کند\r\n- اینترنت محدود است، ولی شبکه داخلی داریم\r\n- اینترنت و دسترسی شبکه در دسترس است\r\n\r\n**وضعیت تصمیم:** گزینه‌های بالا پرسش‌های بازِ زمان تدوین طرح‌اند. تصمیم معماری نهایی باید پس از بررسی محیط و تأیید صریح ثبت شود؛ تا آن زمان فناوری‌های پیشنهادی قطعی نیستند.\r\n\r\n## الحاقیه وضعیت جاری و حدود اعتبار طرح — ۱۴۰۵/۰۷/۲۸\r\n\r\nاین سند طرح پیشنهادی نسخه اول است؛ به‌تنهایی تصویب فناوری یا اثبات اجرای فعالیت‌ها نیست. فایل مرجع جاری `کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx` است و نگاشت ورود باید پس از بررسی سه شیت باقی‌مانده، در برابر همین فایل به‌روز شود. فرض‌های قدیمی درباره سه Excel اولیه فقط به‌عنوان تاریخچه حفظ شوند.\r\n\r\nقواعد فعلی: دسته‌بندی R/A/H/P/K/M حفظ شود؛ رابطه کتاب–شهید دوطرفه و قابل ردیابی باشد؛ شناسه نهایی و محل واقعی بدون تأیید ساخته نشود؛ نامزد الگوریتمی تأیید انسانی نیست؛ ورود آزمایشی باید گزارش قابل تطبیق بسازد.\r\n\r\nبرای تصمیم‌های یگانه و پرسش‌های واقعی باز به [دفتر تصمیم‌ها](../../مستندات/دفتر%20تصمیم‌ها%20و%20ابهام‌های%20باز%20مرکز%20اسناد%20-%201405-07-28.md) مراجعه شود.\r\n\r\n================ FILE: \\نرم‌افزار ثبت کتاب‌ها و شهدا\\docs\\طرح-کدگذاری-و-فیلدهای-فهرست-کتابخانه-نسخه-۰٫۱.md ================\r\n# طرح پیشنهادی کدگذاری و فیلدهای فهرست کتابخانه — نسخه ۰٫۱\r\n\r\n**پروژه:** نرم‌افزار ثبت کتاب‌ها و شهدا — مرکز اسناد گلزار شهدای تهران\r\n**وضعیت:** پیش‌نویس غیرنهایی؛ ابتدا بر پایه سه فایل Excel اولیه تدوین شده و باید در برابر فایل تلفیقی مبنای جاری بازبینی شود. هیچ شناسه یا کد فیزیکی با این سند به‌تنهایی مصوب نمی‌شود.\r\n**هدف:** جداکردن شناسه نرم‌افزار، اطلاعات کتاب‌شناختی، نسخه‌های فیزیکی، طبقه‌بندی موضوعی و محل نگهداری؛ به‌گونه‌ای که با تغییر قفسه یا دسته‌بندی، پیوندهای پژوهشی از بین نروند.\r\n\r\n## ۱. اصل طراحی\r\n\r\nسه مفهوم نباید با هم اشتباه شوند:\r\n\r\n1. **رکورد کتاب‌شناختی:** یک عنوان/اثر و مشخصات چاپی قابل شناسایی.\r\n2. **نسخه فیزیکی:** هر جلد واقعی که در کتابخانه وجود دارد؛ نسخه‌های متعدد یک کتاب، کد جدا دارند.\r\n3. **محل فیزیکی:** قفسه/طبقه/موقعیت فعلی هر نسخه؛ جابه‌جایی محل، شناسه کتاب یا نسخه را عوض نمی‌کند.\r\n\r\nستون «تعداد» در Excel، شماره ردیف اکسل، نام شیت یا نام ناشر هیچ‌کدام نباید به‌عنوان شناسه پایدار نرم‌افزار یا کد قفسه استفاده شوند.\r\n\r\n## ۲. پیشنهاد کدگذاری\r\n\r\n### ۲.۱ شناسه‌های داخلی سامانه\r\n\r\n| موجودیت | پیشوند پیشنهادی | نمونه | کاربرد |\r\n|---|---|---|---|\r\n| رکورد کتاب‌شناختی | `BK` | `BK-000001` | شناسه ثابت یک اثر/رکورد کتاب |\r\n| نسخه فیزیکی | `CP` | `CP-000001` | شناسه مستقل هر جلد واقعی |\r\n| پرونده شهید | `MT` | `MT-000001` | شناسه ثابت پرونده شهید پس از ایجاد رکورد |\r\n| ارتباط کتاب و شهید | شناسه داخلی سامانه | خودکار | ثبت هر پیوند با منشأ و وضعیت بازبینی |\r\n| ارجاع/مطلب استخراج‌شده | شناسه داخلی سامانه | خودکار | ثبت مطلب، صفحه و منبع |\r\n\r\nاین شناسه‌ها **معنادار نیستند و نباید شامل نام ناشر، دسته موضوعی، نام شهید یا قفسه باشند**. اگر کتاب از دسته R به H منتقل شود یا به قفسه دیگری برود، شناسه BK و CP ثابت می‌ماند. شماره‌های نمونه صرفاً نمونه قالب‌اند؛ نباید شناسه‌های واقعی از پیش رزرو شوند.\r\n\r\n### ۲.۲ کد دسته‌بندی موضوعی\r\n\r\nدسته‌های فعلی که در سوابق پروژه ثبت شده‌اند، تا زمان تصمیم رسمی جدید حفظ شوند:\r\n\r\n| کد | عنوان دسته |\r\n|---|---|\r\n| R | روایت و خاطرات |\r\n| A | ادبیات و هنر |\r\n| H | تاریخ و اسناد |\r\n| P | پژوهش و تحلیل |\r\n| K | کودک و نوجوان |\r\n| M | متفرقه |\r\n\r\n- این کد، **کد موضوعی** است؛ شناسه کتاب و کد قفسه نیست.\r\n- دسته‌بندی باید بر اساس محتوای کتاب انجام شود، نه ناشر.\r\n- برای نسخه اول می‌توان یک دسته اصلی و در صورت نیاز چند برچسب موضوعی داشت؛ دسته اصلی در ابتدا «نیازمند تعیین» باشد تا وقتی بازبین آن را انتخاب کند.\r\n- کدهای فعلی نباید بدون ثبت تصمیم و نگاشت، تغییر یا حذف شوند.\r\n\r\n### ۲.۳ کد محل فیزیکی\r\n\r\nقالب نهایی کد محل هنوز قابل تثبیت نیست، چون نقشه قفسه‌ها، تعداد طبقات و نحوه چیدمان فیزیکی باید مشاهده و تأیید شود. پیشنهاد اولیه برای بحث:\r\n\r\n`Z01-S003-L02`\r\n\r\nکه به‌صورت پیشنهادی به معنی «ناحیه/فضا ۰۱، قفسه ۰۰۳، طبقه ۰۲» است. اگر موقعیت دقیق روی طبقه لازم شد، می‌توان جزء جایگاه را افزود. این فقط نمونه قالب است، نه کد واقعی قفسه‌های مرکز.\r\n\r\n- کد مکان از دسته موضوعی مستقل است.\r\n- محل فعلی باید روی هر **نسخه فیزیکی** ثبت شود.\r\n- تاریخچه جابه‌جایی در صورت نیاز حفظ شود.\r\n- تا پیش از بررسی قفسه‌های واقعی، برچسب چاپی با این قالب تولید نشود.\r\n\r\n## ۳. فیلدهای پیشنهادی رکورد کتاب‌شناختی\r\n\r\nنام فنی فیلدها پیشنهادی است؛ برچسب رابط کاربری فارسی خواهد بود.\r\n\r\n| فیلد فنی | برچسب فارسی | الزام در نسخه اول | منبع/روش ثبت | قاعده |\r\n|---|---|---|---|---|\r\n| `book_id` | شناسه کتاب | اجباری، خودکار | سامانه | ثابت؛ مانند BK-000001 |\r\n| `title_raw` | عنوان خام منبع | اجباری برای ورود | ستون «عنوان کتاب» | عین مقدار منبع حفظ شود |\r\n| `title_display` | عنوان نمایشی | اجباری | ثبت/بازبینی | می‌تواند نسخه پاکیزه‌شده برای نمایش باشد؛ خام حذف نشود |\r\n| `publisher_raw` | ناشر خام منبع | اختیاری | ستون «انتشارات» | عین مقدار اکسل |\r\n| `publisher_id` | ناشر استاندارد | اختیاری در شروع | فرهنگ ناشران پس از بازبینی | نگاشت ناشرها دستی/کنترل‌شده؛ ادغام خودکار ممنوع |\r\n| `description_raw` | توضیحات خام منبع | اختیاری | ستون «توضیحات» | عین متن؛ الزاماً نویسنده نیست |\r\n| `author_display` | نویسنده/پدیدآورنده | اختیاری | ثبت دستی از منبع معتبر | از توضیحات به‌طور خودکار استخراج نشود |\r\n| `edition_statement` | مشخصات چاپ/ویرایش | اختیاری | کتاب یا منبع معتبر | فقط در صورت تأیید |\r\n| `publication_year` | سال انتشار | اختیاری | کتاب یا منبع معتبر | مقدار خام و تقویم سال باید روشن باشد |\r\n| `isbn` | شابک | اختیاری | کتاب یا منبع معتبر | در صورت نبود خالی بماند؛ ساخته نشود |\r\n| `category_id` | دسته موضوعی اصلی | قابل تعیین پس از بررسی | دسته‌های R/A/H/P/K/M | در ابتدا می‌تواند «نیازمند تعیین» باشد |\r\n| `keywords` | کلیدواژه‌ها | اختیاری | بازبین | برای جست‌وجو؛ جای دسته اصلی را نمی‌گیرد |\r\n| `source_quantity_raw` | تعداد ثبت‌شده در Excel | اختیاری | ستون «تعداد» | مقدار منبع؛ به‌تنهایی موجودی قطعی نیست |\r\n| `catalog_status` | وضعیت فهرست‌نویسی | اجباری | سامانه/بازبین | پیش‌نویس، نیازمند بررسی، تأییدشده، ردشده با دلیل |\r\n| `source_note` | یادداشت ثبت‌کننده | اختیاری | ثبت‌کننده | جدا از توضیحات خام منبع |\r\n| `created_at/by` | زمان/ثبت‌کننده | خودکار | سامانه | برای ردگیری |\r\n| `updated_at/by` | زمان/آخرین ویرایشگر | خودکار | سامانه | برای ردگیری |\r\n\r\n**نکته:** برای ورود اولیه، عنوان و ناشر و توضیحات خام مهم‌اند؛ نویسنده، شابک، سال چاپ و ویرایش را فقط وقتی ثبت می‌کنیم که واقعاً از منبع معتبر معلوم باشند. از ستون «توضیحات» نمی‌توان به‌طور قطعی نویسنده را استنباط کرد.\r\n\r\n## ۴. فیلدهای نسخه فیزیکی کتاب\r\n\r\nهر جلدی که واقعاً مشاهده و تأیید شده، یک رکورد نسخه دارد. در ورود اولیه از Excel، بدون شمارش فیزیکی نسخه‌ها را به‌صورت خودکار نسازید.\r\n\r\n| فیلد فنی | برچسب فارسی | قاعده |\r\n|---|---|---|\r\n| `copy_id` | کد نسخه فیزیکی | خودکار و ثابت؛ مانند CP-000001 |\r\n| `book_id` | شناسه کتاب | ارتباط با رکورد کتاب‌شناختی |\r\n| `copy_status` | وضعیت نسخه | نامشخص، موجودِ تأییدشده، مفقود، امانت، در انتظار بررسی، خارج از مجموعه |\r\n| `location_id` | محل فعلی | ارجاع به فرهنگ مکان؛ تا تأیید محل می‌تواند خالی باشد |\r\n| `physical_condition` | وضعیت ظاهری | اختیاری؛ سالم، نیازمند ترمیم، آسیب‌دیده، بررسی‌نشده |\r\n| `inventory_checked_at` | تاریخ شمارش/بازبینی | فقط پس از مشاهده فیزیکی |\r\n| `inventory_checked_by` | شمارش‌کننده | کاربر سامانه |\r\n| `copy_note` | توضیح نسخه | اختیاری |\r\n| `created_at/by` | ثبت‌کننده/زمان | خودکار |\r\n\r\nفیلد `source_quantity_raw` در رکورد کتاب باقی می‌ماند؛ تعداد نسخه‌های تأییدشده از شمارش واقعی نسخه‌های دارای `copy_id` محاسبه می‌شود. اختلاف این دو باید در گزارش مغایرت دیده شود.\r\n\r\n## ۵. فیلدهای پرونده شهید و پیوندها\r\n\r\n### پرونده شهید\r\n\r\n- `martyr_id`: شناسه داخلی ثابت، مانند MT-000001.\r\n- `full_name_raw`: نام عین منبع.\r\n- `full_name_display`: نام نمایشی پس از بازبینی.\r\n- `identity_review_status`: بررسی‌نشده، نیازمند بررسی، تأییدشده، احتمالاً تکراری.\r\n- `source_file`, `source_sheet`, `source_row`: منشأ رکورد.\r\n\r\nنام مشابه یا املای متفاوت به‌تنهایی اثبات نمی‌کند که دو ردیف متعلق به یک شخص هستند. نرمال‌سازی برای جست‌وجو مجاز است، ولی مقدار خام باید باقی بماند.\r\n\r\n### پیوند کتاب و شهید\r\n\r\n- `book_martyr_link_id`: شناسه پیوند.\r\n- `book_id`, `martyr_id`: دو طرف ارتباط.\r\n- `relationship_note`: شرح ارتباط، اگر معلوم باشد.\r\n- `source_description_raw`: توضیح مرتبط در فایل.\r\n- `source_file`, `source_sheet`, `source_row`: منشأ اجباری.\r\n- `review_status`: خام، نیازمند بررسی، تأییدشده، ردشده با دلیل.\r\n- `review_note`, `reviewed_by`, `reviewed_at`: بازبینی.\r\n\r\nدر شیت «چند شهید»، هر ردیف شهیدِ ادامه به همان کتاب آغازگر وصل می‌شود. در فایل مرتبط، مقادیر `*` یا عبارت‌های کلی مثل «اشاره به چند شهید غیر تهرانی» نباید پرونده شهید جعلی بسازند؛ آن‌ها باید در لایه خام باقی بمانند تا نوع ارتباط بعداً تعیین شود.\r\n\r\n## ۶. فیلدهای اطلاعات مزار\r\n\r\nاطلاعات مزار را از رکورد کتاب جدا نگه دارید؛ یک شهید ممکن است چند منبع یا چند مقدار متفاوت برای مکان مزار داشته باشد.\r\n\r\n| فیلد | برچسب فارسی | نکته |\r\n|---|---|---|\r\n| `grave_location_id` | شناسه رکورد مزار | خودکار |\r\n| `martyr_id` | شهید | فقط پس از تطبیق هویت |\r\n| `section_raw` | قطعه خام | متن، نه عدد اجباری |\r\n| `grave_row_raw` | ردیف مزار خام | متن؛ با شماره ردیف اکسل اشتباه نشود |\r\n| `grave_number_raw` | شماره مزار خام | متن؛ مقادیر مکرر/حرفی را حفظ کند |\r\n| `source_file/sheet/row` | منشأ | اجباری |\r\n| `review_status` | وضعیت بررسی | بررسی‌نشده، نیازمند بررسی، تأییدشده، متعارض |\r\n| `review_note` | یادداشت | اختیاری |\r\n\r\nعنوان «ردیف» در اکسل هم برای شماره ترتیبی رکورد و هم برای ردیف مزار آمده است؛ در پایگاه داده باید نام‌های متفاوت داشته باشند تا اشتباه رخ ندهد.\r\n\r\n## ۷. مطالب استخراج‌شده و شماره صفحه\r\n\r\nبرای مرحله‌ای که مطالب داخل کتاب‌ها ثبت می‌شوند، جدول مستقل لازم است:\r\n\r\n- `item_id`: شناسه مطلب.\r\n- `book_id`: کتاب منبع.\r\n- `martyr_id`: شهید مرتبط، در صورت وجود و تأیید.\r\n- `page_reference_raw`: ارجاع صفحه عین منبع، مانند «173تا184» یا متن غیرعددی.\r\n- `page_start`, `page_end`: اختیاری؛ فقط وقتی الگو بدون ابهام قابل تجزیه باشد.\r\n- `content_type`: زندگی‌نامه، خاطره، وصیت‌نامه، سند، اشاره کوتاه، سایر/نیازمند تعیین.\r\n- `content_text` یا `research_summary`: متن یا خلاصه ثبت‌شده.\r\n- `review_status`, `reviewed_by`, `reviewed_at`: وضعیت بررسی.\r\n- `source_file/sheet/row`: منشأ ردیف اولیه، در صورت ارتباط با Excel.\r\n\r\nارجاع خام صفحه هرگز با مقدار عددی استخراج‌شده جایگزین نشود. مجوز ثبت داخلی و مجوز انتشار عمومی دو موضوع جدا هستند.\r\n\r\n## ۸. جداول پشتیبان نرم‌افزار\r\n\r\nنسخه اول به این موجودیت‌ها نیاز دارد یا ممکن است به آن‌ها نیاز پیدا کند:\r\n\r\n- `books`: رکورد کتاب‌شناختی.\r\n- `book_copies`: نسخه‌های فیزیکی و محل هر نسخه.\r\n- `publishers`: فرهنگ ناشران استاندارد و نام‌های خام/جایگزین.\r\n- `categories`: فرهنگ دسته‌بندی و کدهای R/A/H/P/K/M.\r\n- `martyrs`: پرونده شهدا.\r\n- `book_martyr_links`: ارتباط چندبه‌چند کتاب و شهید.\r\n- `grave_locations`: اطلاعات مزار و منشأ آن.\r\n- `extracted_items`: مطالب پژوهشی و ارجاعات صفحه.\r\n- `import_batches` و `import_rows`: اجرای ورود و نتیجه هر ردیف.\r\n- `users` و `audit_log`: نقش‌ها و سابقه تغییرات.\r\n- `locations`: فرهنگ مکان فیزیکی و تاریخچه جابه‌جایی، اگر نیاز تأیید شود.\r\n\r\nاین فهرست مدل مفهومی نسخه اول است؛ نوع دقیق پایگاه داده و جزئیات پیاده‌سازی تا بررسی محیط و تأیید معماری قطعی نیست.\r\n\r\n## ۹. نگاشت سه فایل به مدل\r\n\r\n| منبع | فیلدهای مقصد اولیه | مواردی که نباید خودکار قطعی شوند |\r\n|---|---|---|\r\n| `لیست کتاب ها.xlsx` | عنوان خام، ناشر خام، توضیحات خام، تعداد خام، منشأ فایل/شیت/ردیف | نویسنده، نسخه چاپ، موجودی فیزیکی، دسته موضوعی |\r\n| `قطعات شهدا.xlsx` / «یک شهید» | عنوان، ناشر، توضیحات، پیوند کتاب-شهید، قطعه/ردیف/شماره مزار خام، منشأ | یکتایی کتاب و شهید، تأیید آدرس |\r\n| `قطعات شهدا.xlsx` / «چند شهید» | کتاب آغازگر و چند پیوند شهید، اطلاعات خام هر ردیف | تبدیل هر ردیف به یک کتاب جدید |\r\n| `قطعات شهدا.xlsx` / «آدرس مزار» | نام خام شهید و محل مزار خام | تطبیق خودکار هویت بر اساس نام |\r\n| `لیست کتابهای و شهدای مرتبط.xlsx` | عنوان/ناشر/توضیحات خام، پیوندهای احتمالی، قطعه/مزار خام، ارجاع صفحه خام | `*` به‌عنوان شهید، صفحه به‌عنوان عدد قطعی، عبارت‌های کلی به‌عنوان پرونده شخص |\r\n\r\n## ۱۰. وضعیت‌های استاندارد پیشنهادی\r\n\r\nبرای اینکه داده خام، تصمیم بازبین و انتشار با هم اشتباه نشوند:\r\n\r\n- **خام:** همان مقدار منبع وارد شده است.\r\n- **نیازمند بررسی:** مقدار مبهم یا ناسازگار است.\r\n- **تأییدشده:** مسئول مجاز آن را بررسی کرده است.\r\n- **ردشده با دلیل:** برای کاربرد موردنظر معتبر نیست، اما در تاریخچه/داده خام قابل پیگیری می‌ماند.\r\n- **متعارض:** دو منبع اطلاعات متفاوت دارند و نیازمند تصمیم است.\r\n\r\nثبت کتاب در سامانه، تأیید محتوای پژوهشی و مجوز انتشار عمومی، سه وضعیت جدا هستند.\r\n\r\n## ۱۱. تصمیم‌های باز پیش از نهایی‌سازی\r\n\r\n1. آیا برای هر جلد فیزیکی برچسب `CP` نصب شود یا در مرحله اول فقط رکورد کتاب‌شناختی `BK` ثبت شود؟\r\n2. **حل‌شده:** دسته‌بندی شش‌گانه R/A/H/P/K/M حفظ می‌شود و برای آن کد داخلی استفاده می‌شود؛ این تصمیم در پاسخ مدیریتی/کاربر ثبت شده است. تغییر این دسته‌ها بدون تصمیم صریح انجام نشود.\r\n3. چه کسی دسته‌بندی موضوعی و رکوردهای مبهم را تأیید می‌کند؟\r\n4. ساختار واقعی قفسه‌ها چیست و کد مکان باید تا چه سطحی (قفسه، طبقه، جایگاه) دقیق باشد؟\r\n5. آیا در مرحله اول فیلدهای نویسنده، سال چاپ و شابک در فرم نمایش داده شوند، هرچند در اکسل‌های فعلی به‌طور قابل اعتماد موجود نیستند؟\r\n6. آیا اطلاعات مزار در نسخه اول فقط به‌عنوان داده مرتبط و قابل جست‌وجو نگهداری شود یا گردش‌کار مستقل بازبینی هم لازم است؟\r\n\r\n## ۱۲. پیشنهاد اجرایی\r\n\r\n1. این طرح را به‌عنوان پیش‌نویس نگه داریم؛ فعلاً برچسب فیزیکی یا کد نهایی چاپ نکنیم.\r\n2. پس از تأیید قواعد کدگذاری، فرهنگ فیلدهای فارسی/فنی و نگاشت ستون‌های سه فایل را در قالب ماشین‌خوان نیز ثبت کنیم.\r\n3. سپس یک ورود آزمایشی محدود اجرا شود و گزارش دهد: چند ردیف خوانده شد، چند کتاب نامزد ایجاد شد، چند پیوند ساخته شد، چه ردیف‌هایی نیازمند بررسی‌اند و هیچ داده‌ای خودکار ادغام نشده است.\r\n4. فقط پس از بررسی گزارش آزمون، طراحی جداول و فرم‌های اجرایی تثبیت شود.\r\n\r\n\r\n---\r\n\r\n## تغییر مرجع داده — ۱۴۰۵/۰۷/۲۸\r\n\r\nکاربر فایل `فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx` را مبنای جاری تعیین کرده و فایل در commit `b93eaca408c3d921a8596dfdafd5f8c992bbf4bc` به مسیر `کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx` در شاخه `main` ثبت شده است. این طرح هنوز نگاشت نهایی فایل جاری نیست. مفاهیم کلیِ جداسازی رکورد کتاب‌شناختی، نسخه فیزیکی، محل و ارتباط کتاب-شهید به‌عنوان پیشنهاد طراحی قابل بازبینی باقی می‌مانند؛ اما نگاشت ستون‌ها، قواعد ورود و هرگونه شناسه نهایی باید پس از خواندن و ممیزی فایل تلفیقی ثبت‌شده بازبینی شود. فایل‌های مشتق‌شده از سه Excel اولیه در `بایگانی/` هستند و منبع جاری ورود نیستند.\r\n\r\n## یادداشت وضعیت جاری مدل کدگذاری — ۱۴۰۵/۰۷/۲۸\r\n\r\nدسته‌بندی R/A/H/P/K/M تصمیم ثبت‌شده است و دوباره پرسیده نشود. در مقابل، قالب شناسه نهایی اثر، شناسه یکتای هر نسخه فیزیکی، کد محل و روش اتصال به شناسه شهید هنوز تأیید نهایی نشده‌اند. نمونه‌هایی مانند `BK-000001` پیشنهاد طراحی‌اند و مجوز چاپ برچسب یا شناسه‌گذاری انبوه نیستند.\r\n\r\nفایل مرجع جاری، فایل تلفیقی ثبت‌شده در `کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx` است؛ نگاشت قدیمی سه Excel اولیه باید در برابر چهار شیت این فایل بازبینی شود. مرجع یگانه موارد باز: [دفتر تصمیم‌ها و ابهام‌های باز](../../مستندات/دفتر%20تصمیم‌ها%20و%20ابهام‌های%20باز%20مرکز%20اسناد%20-%201405-07-28.md).\r\n\r\n================ FILE: \\مستندات\\پروتکل-تداوم-کار-و-تفکیک-مسیرهای-کتابخانه.md ================\r\n# پروتکل تداوم کار و تفکیک مسیرهای کتابخانه\r\n\r\n**تاریخ ثبت:** ۱۴۰۵/۰۷/۲۳ (۲۰۲۶-۱۰-۱۵)\r\n**وضعیت:** قاعده جاری کار؛ قابل بازنگری با ثبت تصمیم جدید\r\n\r\n## هدف\r\nهر چت تازه باید از سوابق معتبر مخزن ادامه دهد؛ کاربر نباید برای توضیح دوباره اطلاعات ثبت‌شده وقت صرف کند.\r\n\r\n## شروع هر چت جدید\r\n۱. گزارش فنی زنده را بخوان.\r\n۲. آخرین گزارش روزانه را بخوان.\r\n۳. سند جامع و اسناد تخصصی مرتبط را فقط در حد نیاز مرور کن.\r\n۴. برای کار نرم‌افزار، README، گزارش تغییرات، مشخصات داده و نگاشت Excel را بخوان.\r\n۵. تاریخچه GitHub و خروجی‌های ثبت‌شده را بررسی کن.\r\n۶. فقط خلأ واقعی را مشخص کن؛ از کاربر اطلاعات ثبت‌شده را دوباره نخواه.\r\n\r\n## پایان هر نوبت کاری معنادار\r\n- گزارش روزانه: کار انجام‌شده، خروجی واقعی، فایل‌های تغییرکرده، خطاها/موانع و اقدام بعدی.\r\n- گزارش فنی: وضعیت فنی پایدار، تصمیم‌ها، ساختار داده، منبع/نسخه، نتیجه آزمون، مسائل باز و دلیل تغییر.\r\n- گزارش جامع: فقط در نقطه عطف، تغییر دامنه یا تصمیم مهم؛ با حفظ نسخه‌های قبلی.\r\n- سند تخصصی مربوط: جزئیات لازم برای ادامه بدون اتکا به حافظه چت.\r\n\r\n## تفکیک دو پروژه/مسیر\r\n### الف) عملیات و سازمان‌دهی کتابخانه\r\nثبت و شناسایی فیزیکی کتاب‌ها، فهرست‌نویسی، دسته‌بندی، کدگذاری و برچسب‌گذاری، تعیین محل قفسه، کنترل موجودی و روش اجرایی کار. این مسیر در چت مستقل پیش می‌رود.\r\n\r\n### ب) نرم‌افزار کتابخانه\r\nنیازمندی‌ها، مدل داده، طراحی پایگاه داده، ورود کنترل‌شده Excel، فرم‌ها، جست‌وجو، گزارش‌ها، نقش‌های کاربری، کدنویسی و آزمون. این مسیر در چت مستقل پیش می‌رود.\r\n\r\nارتباط این دو فقط با نیازمندی و قرارداد داده ثبت‌شده انجام می‌شود. تصمیم‌های یک مسیر نباید بی‌ثبت به مسیر دیگر تعمیم داده شوند.\r\n\r\n## ثبت‌های فعلی درباره سه فایل Excel\r\nمسیر: کتابخانه/فهرست کتاب‌های مرکز اسناد/\r\n\r\n- «لیست کتاب ها.xlsx»: طبق مستند پیشین، هر شیت به یک ناشر اختصاص دارد. نام همه شیت‌ها و ستون‌ها هنوز در سند نگاشت فعلی ثبت نشده است.\r\n- «قطعات شهدا.xlsx»: شیت‌های گزارش‌شده «یک شهید»، «چند شهید»، «آدرس مزار» هستند. نمونه کاربر: انتشارات ابراهیم هادی کتاب «با مرام» را منتشر کرده که زندگی‌نامه و خاطرات شهید احمد بیابانی را دارد.\r\n- «لیست کتابهای و شهدای  مرتبط.xlsx»: منبع پژوهشی کتاب‌ها و شهدای مرتبط و ارجاع صفحه؛ نگاشت دقیق ستون‌ها هنوز ثبت نشده است.\r\n- «تجمیعی کامل (2).xlsx»: خارج از دامنه ورود اولیه نرم‌افزار، مگر با تصمیم مستند جدید.\r\n\r\nاین اطلاعات، سوابق مستندشده‌اند و نباید دوباره از کاربر پرسیده شوند. با این حال، نبودن نگاشت کامل ستون‌ها به معنای آن است که نباید وانمود کنیم ممیزی کامل انجام شده است. ابتدا سوابق و خروجی‌های قبلی بررسی شوند؛ فقط بخش‌های واقعاً نامعلوم تکمیل شوند.\r\n\r\n## قاعده ثبت نگاشت Excel\r\nبرای هر فایل ثبت شود: نام دقیق، اثرانگشت/نسخه، شیت‌ها و ترتیب آن‌ها، سطر عنوان، نام دقیق ستون‌ها، معنی و مقصد هر ستون، ساختار ردیف‌های ادامه، شمارش‌ها، فرمول/ادغام سلول‌ها، نمونه غیرحساس، ابهام‌ها، تصمیم‌های تأییدشده و تاریخ ممیزی. سند نگاشت باید تنها مرجع قابل اتکا برای چت‌های آینده باشد و در هر بررسی جدید تکمیل شود.\r\n\r\n## حفاظت و صحت\r\n- فایل‌های اصلی دست‌نخورده بمانند.\r\n- هیچ تطبیق نام یا عنوان مشابه به‌طور خودکار به ادغام منجر نشود.\r\n- موجودی فیزیکی تأییدشده از شمار خرید اولیه نتیجه‌گیری نشود.\r\n- هر نتیجه باید وضعیت «مشاهده‌شده»، «گزارش‌شده توسط کاربر»، «پیشنهادی» یا «تأییدنشده» داشته باشد.\r\n- اجرای ابزار یا ممیزی موفق فقط پس از اجرای واقعی اعلام شود.\r\n\r\n## نقطه ادامه فعلی\r\nاسکریپت محلی ممیزی Excel در مخزن ثبت شده، اما طبق آخرین وضعیت ثبت‌شده هنوز خروجی اجرای آن در دسترس نیست. در چت بعدی ابتدا هرگونه خروجی/یافته قبلی را بررسی کن؛ اگر کاربر خروجی PowerShell را ارائه کرد، همان را بخوان و سند نگاشت، گزارش روزانه و گزارش فنی را با یافته‌های واقعی به‌روزرسانی کن. از درخواست اجرای دوباره کل کار خودداری کن مگر آنکه خروجی ناقص یا نامعتبر باشد.\r\n\r\n\r\n---\r\n\r\n## وضعیت جاری که در شروع هر چت باید رعایت شود — ۱۴۰۵/۰۷/۲۸\r\n\r\n- مرجع کار جاری `کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx` است و در commit `b93eaca408c3d921a8596dfdafd5f8c992bbf4bc` به همین مسیر در شاخه `main` ثبت شده است. پیش از ورود عملیاتی باید ساختار workbook و نگاشت ستون‌ها بازبینی شود.\r\n- JSONهای استخراج‌شده، نسخه‌های کاری XML، خروجی‌های CSV ممیزی/تطبیق و گزارش‌های مخصوص سه Excel اولیه به [بایگانی](../بایگانی/README.md) منتقل شده‌اند و مبنای جاری نیستند.\r\n- سه فایل Excel اولیه در پوشه اصلی منابع حفظ شده‌اند و تغییر نکرده‌اند؛ آن‌ها با فایل تلفیقی مبنا یکی نیستند.\r\n- فقط در مخزن `forog1980-star/markaz-asnad-shohada` کار پروژه را ادامه بده.\r\n- هر بار پس از یک نوبت کاری معنادار، گزارش روزانه و سند فنی به‌روزرسانی و در نقطه عطف گزارش جامع نیز هماهنگ شود؛ ثبت موفقیت پس از خواندن دوباره فایل از GitHub تأیید گردد.\r\n\r\n\r\n## اصلاح وضعیت مرجع — ۱۴۰۵/۰۷/۲۸\r\n\r\nفایل مرجع جاری کتابخانه در commit `b93eaca408c3d921a8596dfdafd5f8c992bbf4bc` به مسیر `کتابخانه/فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx` در شاخه `main` افزوده شد. اندازه ثبت‌شده: ۲۵۹٬۲۷۶ بایت؛ SHA-256 فایل محلی تأییدشده: `0B34D6A013D11D2273EF306CEBAFAE92F024E52811E5BC43F6509ADE7AB19C16`. پیوند commit: https://github.com/forog1980-star/markaz-asnad-shohada/commit/b93eaca408c3d921a8596dfdafd5f8c992bbf4bc . این ثبت فقط شامل فایل مرجع بود؛ تغییرات ثبت‌نشده مخزن محلی اصلی وارد این commit نشده‌اند. نسخه‌های JSON/XML/CSV مشتق از سه فایل Excel اولیه در `بایگانی/` باقی می‌مانند و همچنان منبع عملیاتی جاری نیستند. گام بعدی، ممیزی ساختاری نسخه ثبت‌شده (شیت‌ها، ستون‌ها، شمارش ردیف‌ها، فرمول‌ها و خلأها) و بازبینی نگاشت ورود در برابر همین فایل است؛ تا اتمام بازبینی، ورود خودکار داده انجام نشود.\r\n\r\n## به‌روزرسانی پروتکل تداوم — ۱۴۰۵/۰۷/۲۸\r\n\r\nدر شروع هر نوبت جدید، [گزارش جامع وضعیت](./گزارش%20جامع%20وضعیت%20و%20جمع‌بندی%20گفت‌وگوها%20-%201405-07-28.md) و [دفتر تصمیم‌ها و ابهام‌های باز](./دفتر%20تصمیم‌ها%20و%20ابهام‌های%20باز%20مرکز%20اسناد%20-%201405-07-28.md) خوانده شوند. اولی نقطه شروع جاری و دومی مرجع یگانه پاسخ‌های مدیریتی، تصمیم‌ها و پرسش‌های باز است؛ گزارش‌های تخصصی از کپی‌کردن فهرست‌های تکراری خودداری کنند.\r\n\r\nفایل‌های `اسناد بالا دستی/پرسشنامه شناخت وضع موجود و دیدگاه مدیریت.docx`، `اسناد بالا دستی/پاسخ پرسش نامه دوم.docx`، طرح جامع و طرح اجرایی در GitHub موجودند. پیش از پرسیدن سؤال مدیریتی، متن و سوابق همین مخزن بررسی شود؛ پرسش‌هایی که پاسخ صریح دارند دوباره مطرح نشوند.\r\n\r\nوضعیت کار جاری: فایل مرجع تلفیقی در `main` ثبت شده؛ شیت نخست مرور شده و سه شیت باقی است. دو پوشه ممیزی اخیر با ۶۷ فایل در بایگانی GitHub ثبت شده‌اند. فایل‌های مبدأ محلی حذف نشده‌اند و تغییرات محلی را با `git add .` به‌صورت یکجا ثبت نکنید.\r\n\r\n================ FILE: \\مستندات\\ثبت تکمیلی دیدگاه‌های مدیریت و وضعیت کتابخانه - 1405-07-28.md ================\r\n# ثبت تکمیلی: دیدگاه‌های مدیریت و وضعیت واقعی سامان‌دهی کتابخانه\r\n\r\nتاریخ ثبت: ۱۴۰۵/۰۷/۲۸\r\n\r\n## وضعیت و نحوه استفاده\r\nاین سند مکمل سه مرجع پروژه است: گزارش جامع، سند فنی زنده و گزارش روزانه. عبارت پیشین این سند درباره ارائه جمع‌بندی برای تأیید نهایی، با توضیح صریح کاربر در ۱۴۰۵/۰۷/۲۸ اصلاح می‌شود: پاسخ‌های ثبت‌شده مدیر در پرسش‌نامه‌ها، همراه با خروجی «خلاصه برداشت از پرسش‌ها و پاسخ‌های مدیر»، مبنای موافقت اصولی مدیریت با چارچوب و جهت‌گیری کلی پروژه‌اند؛ بنابراین موافقت اصولی نباید دوباره درخواست شود یا به‌عنوان ابهام باز باقی بماند. این وضعیت، جزئیات فنی و اجرایی‌ای را که صریحاً به جلسه یا بررسی بعدی موکول شده‌اند، خودبه‌خود قطعی نمی‌کند. این ثبت، هیچ فایل Excel یا داده سامانه‌ای را تغییر نمی‌دهد.\r\n\r\n## ۱. مأموریت و انتظارات مدیریت\r\nمأموریت مرکز، ایجاد بانک اطلاعاتی و اسنادی منسجم، معتبر و قابل استناد درباره شهدای بهشت زهرا (س)، تاریخچه گلزار شهدای تهران و یگان‌های مرتبط برای پشتیبانی از فعالیت‌های علمی، پژوهشی، فرهنگی، هنری، رسانه‌ای و گویاسازی گلزار است.\r\n\r\nاولویت آغازین، شهدای تهرانی، لشکر ۱۰، لشکر ۲۷ و منابع مرتبط است؛ با تأکید بر شناسایی و سامان‌دهی کتاب‌ها، مقالات، نشریات و اسناد مکتوب و تکمیل مجموعه کتاب‌های موردنیاز. خروجی‌های مورد انتظار عبارت‌اند از سامان‌دهی فیزیکی و موضوعی، مستندسازی اطلاعات و منشأ آن‌ها، مشخص‌بودن اعتبار و وضعیت تأیید، نگهداشت موارد اختلافی و فراهم‌شدن جست‌وجوی ساده و سریع.\r\n\r\nجهت‌گیری دیجیتال، توسعه مرحله‌ای چت‌باتی مستقل برای استفاده در وب‌سایت گلزار است که از منابع مجاز سایت و منابع سامان‌دهی‌شده مرکز استفاده کند، پاسخ‌های مستند همراه با ارجاع/پیوند بدهد، اسناد را هوشمندانه جست‌وجو کند و به کارکنان در یافتن اطلاعات و آماده‌سازی محتوای فرهنگی و رسانه‌ای کمک کند. فناوری، زیرساخت و هزینه پس از بررسی کارشناسی برای تصمیم مدیریت ارائه می‌شود.\r\n\r\nامکانات گزارش‌شده شامل یک رایانه، تجهیزات اداری و فضای دارای میز، صندلی، کمد و قفسه است. در پرسش‌نامه، حدود ۵۰۰ جلد تهیه‌شده و حدود ۴۰۰ جلد دیگر در حال پیگیری ذکر شده است؛ ارقام باید با تحویل و ثبت واقعی تطبیق داده شوند و کتاب تحویل‌نشده موجودی دریافتی نیست. ظرفیت سه نفر در پرسش‌نامه مطرح شده، اما توافق فعلی آغاز کار با یک نفر است. بازه ۸ تا ۱۰ هفته پیشنهاد اولیه برای مرحله نخست است و تا تعیین دامنه و تأیید مدیریت برنامه مصوب محسوب نمی‌شود.\r\n\r\nبرای تداوم مرکز، ضوابط مکتوب مأموریت، مسئولیت، ثبت و تأیید، سطح دسترسی، انتشار و نگهداری لازم است. مسئول سازمانی نگهداری سامانه باید مشخص شود و امکان استفاده از تخصص بیرونی پیش‌بینی گردد. انتشار عمومی تابع بررسی، تأیید و مجوزهای لازم است.\r\n\r\n## ۲. جمع‌بندی چهار فایل Excel\r\n- **لیست کتاب ها.xlsx:** فهرست کتاب‌های موجود با شیت‌های تفکیک‌شده بر اساس ناشر؛ تعداد اعلام‌شده تقریبی است و باید با خود فایل و شمارش فیزیکی تطبیق شود.\r\n- **قطعات شهدا.xlsx:** سه شیت درباره کتاب‌های مرتبط با یک شهید، کتاب‌های مرتبط با چند شهید، و نام‌ها و نشانی مزارها. وجود نام شهید اثبات موجودبودن کتاب نیست.\r\n- **لیست کتابهای و شهدای مرتبط.xlsx:** اطلاعات کتاب‌شناختی و ارتباط کتاب‌ها با شهدا، همراه با نشانی مزار و شماره صفحه در موارد ثبت‌شده؛ برخی ارتباط‌ها ناقص یا مربوط به شهدای غیرتهرانی‌اند.\r\n- **تجمیعی کامل (2).xlsx:** کتاب‌های مورد انتظار برای تحویل آینده و شیت‌های قطعات و یادمان‌ها. تا تحویل فیزیکی و ثبت نهایی، این کتاب‌ها موجودی دریافت‌شده محسوب نمی‌شوند.\r\n\r\nاین فایل‌ها از نظر هدف و وضعیت یکسان نیستند و نباید بدون نگاشت و بررسی به‌صورت خودکار ادغام، تأیید یا حذف شوند. منشأ داده باید حفظ شود.\r\n\r\n## ۳. واقعیت اجرایی فعلی کتابخانه\r\nکاربر تصریح کرده است که **کار فیزیکی انجام‌شده تا این مرحله فقط تقسیم کتاب‌ها در شش موضوع و چیدن آن‌ها در قفسه‌هاست**:\r\n- R — روایت و خاطرات: ۵۸۰\r\n- A — ادبیات و هنر: ۷۶\r\n- H — تاریخ و اسناد: ۶۰\r\n- P — پژوهش و تحلیل: ۶۹\r\n- K — کودک و نوجوان: ۳۶\r\n- M — متفرقه و متنوع: ۱۲۱\r\n- جمع شمارش فیزیکی اعلام‌شده: ۹۴۲\r\n\r\nشیت «فهرست کتاب‌ها» در فایل تلفیقی ۹۸۰ رکورد دارد. اختلاف محاسباتی ۳۸ موردی باز است؛ احتمال شمارش‌نشدن تعدادی کتاب فقط فرضیه است، نه علت قطعی. عدد ۹۸۰ تعداد رکوردهای فهرست و ۹۴۲ شمارش فیزیکی اعلام‌شده است؛ تا تطبیق موردبه‌مورد، این اعداد قابل جایگزینی با یکدیگر نیستند و نباید اختلاف به‌عنوان کسری قطعی ثبت شود.\r\n\r\nتقسیم‌بندی و چیدن قفسه‌ها به‌تنهایی به معنای تکمیل فهرست‌نویسی، شناسه‌گذاری نسخه فیزیکی، ثبت محل دقیق، تطبیق رکوردبه‌رکورد، تأیید ارتباط کتاب و شهید یا تکمیل نرم‌افزار نیست.\r\n\r\n## ۴. اقدامات باز\r\n۱. دریافت تأیید نهایی مدیریت و تعیین موارد نیازمند مجوز.\r\n۲. تطبیق چهار فایل منبع با فایل تلفیقی و مستندات تحویل بدون ادغام خودکار. \r\n۳. شمارش و تطبیق کتاب‌ها و تعیین مستند اختلاف ۳۸ موردی.\r\n۴. تعریف شناسه نسخه فیزیکی و ثبت محل دقیق.\r\n۵. بررسی اعتبار ارتباط‌های کتاب و شهید، به‌ویژه ارتباط‌های ناقص یا مربوط به شهدای غیرتهرانی.\r\n۶. تعیین دامنه مرحله نخست و بررسی برنامه ۸ تا ۱۰ هفته‌ای و هزینه فناوری پس از تأیید مدیریت.\r\n\r\n## ۵. قاعده ثبت وضعیت\r\nکار فیزیکی انجام‌شده: تقسیم موضوعی و چیدن قفسه‌ها. سایر موارد فوق اقدام‌های باز یا پیشنهادی‌اند مگر بعداً با شواهد اجرا تأیید شوند. هیچ فایل Excel یا داده سامانه در این اقدام تغییر نکرده است.\r\n\r\n## ارجاع تداوم و وضعیت منابع مدیریت — ۱۴۰۵/۰۷/۲۸\r\n\r\nفایل‌های مبنای دیدگاه مدیریت در مخزن رسمی در مسیر `اسناد بالا دستی/` موجودند: پرسشنامه شناخت وضع موجود و دیدگاه مدیریت، پاسخ پرسش‌نامه دوم، طرح جامع مرکز اسناد و طرح اجرایی ایجاد و راه‌اندازی. این سند جمع‌بندی آن منابع است، نه جایگزین متن اصل آن‌ها.\r\n\r\nبرای جلوگیری از تکرار، مرجع وضعیت فعلی و ادامه کار [گزارش جامع وضعیت](./گزارش%20جامع%20وضعیت%20و%20جمع‌بندی%20گفت‌وگوها%20-%201405-07-28.md) و مرجع یگانه تصمیم‌ها/ابهام‌ها [دفتر تصمیم‌ها](./دفتر%20تصمیم‌ها%20و%20ابهام‌های%20باز%20مرکز%20اسناد%20-%201405-07-28.md) است. از کاربر دوباره خواسته نشود فایل‌های موجود مدیریتی را ارسال کند.\r\nPS C:\\Windows\\System32>\r\nPS C:\\Windows\\System32> $jsonFile = \"$path\\نرم‌افزار کتابخانه\\فهرست-کاری-کتابخانه-نسخه-0.1.json\"\r\nPS C:\\Windows\\System32> if (Test-Path $jsonFile) {\r\n>>   Write-Host \"`r`n================ SAMPLE JSON: فهرست-کاری-کتابخانه-نسخه-0.1.json ================\" -ForegroundColor Cyan\r\n>>   Get-Content $jsonFile -TotalCount 80 -Encoding UTF8 -ErrorAction SilentlyContinue\r\n>> }\r\n\r\n================ SAMPLE JSON: فهرست-کاری-کتابخانه-نسخه-0.1.json ================\r\n{\r\n  \"format\": \"markaz-asnad-library-workbook-json\",\r\n  \"schema_version\": \"1.0\",\r\n  \"source_file\": \"فهرست کاری کتابخانه - نسخه 0.1 (1).xlsx\",\r\n  \"source_sha256\": null,\r\n  \"conversion_mode\": \"read-only; cell positions preserved; formulas preserved as formulas\",\r\n  \"sheet_count\": 5,\r\n  \"nonempty_row_count_total\": 2591,\r\n  \"sheets\": [\r\n    {\r\n      \"name\": \"فهرست کتاب‌ها\",\r\n      \"max_row\": 981,\r\n      \"max_column\": 18,\r\n      \"nonempty_row_count\": 981,\r\n      \"rows\": [\r\n        [\r\n          \"شناسه موقت کتاب\",\r\n          \"عنوان کتاب\",\r\n          \"ناشر\",\r\n          \"توضیحات ثبت‌شده در منبع\",\r\n          \"دسته\",\r\n          \"نویسنده/گردآورنده\",\r\n          \"شابک\",\r\n          \"فیپا\",\r\n          \"شماره ثبت کتابخانه\",\r\n          \"محل نگهداری/قفسه\",\r\n          \"تعداد نسخه‌های موجود پس از شمارش\",\r\n          \"وضعیت بررسی کتاب\",\r\n          \"یادداشت\",\r\n          \"شیت منبع (پشتیبان)\",\r\n          \"ردیف منبع (پشتیبان)\",\r\n          null,\r\n          null,\r\n          null\r\n        ],\r\n        [\r\n          \"BK-0001\",\r\n          \"101خاطره جنگی (سال 2009-سارایوو)\",\r\n          \"سوره مهر\",\r\n          \"ژنرال راسم دلیچ\",\r\n          null,\r\n          \"\",\r\n          \"\",\r\n          \"\",\r\n          \"\",\r\n          \"\",\r\n          \"\",\r\n          \"بررسی‌نشده\",\r\n          \"\",\r\n          \"سوره مهر\",\r\n          \"2\",\r\n          null,\r\n          null,\r\n          null\r\n        ],\r\n        [\r\n          \"BK-0002\",\r\n          \"اردوگاه اطفال\",\r\n          \"سوره مهر\",\r\n          \"\",\r\n          null,\r\n          \"\",\r\n          \"\",\r\n          \"\",\r\n          \"\",\r\n          \"\",\r\n          \"\",\r\n          \"بررسی‌نشده\",\r\n          \"\",\r\n          \"سوره مهر\",\r\n          \"3\",\r\n          null,\r\n          null,\r\n          null\r\n        ],\r\n        [\r\n          \"BK-0003\",\r\n          \"اردوگاه عنبر\",\r\n          \"سوره مهر\",\r\n          \"خاطرات آزادگان و اسرا\",\r\nPS C:\\Windows\\System32>";
const comprehensiveTechAndSoftwareReportRaw = "# گزارش جامع فنی و معرفی کامل «سامانه کتابخانه، ثبت موجودی و پژوهش مرکز اسناد گلزار شهدای تهران»\n\n- **مخزن رسمی کد منبع (GitHub):** `https://github.com/forog1980-star/book`\n- **شاخه اصلی:** `main`\n- **نسخه مبنا (Base Commit):** `ea73b032a74cc6051a574b8d8ab78a1dd035a4ad` (به همراه تکمیل تراکنش اتمیک چندمجموعه‌ای در `IndexedDB`)\n- **معماری سامانه:** وب‌اپلیکیشن پیش‌رونده محلی‌محور (`Local-First PWA`) با همگام‌سازی مستقیم نظیربه‌نظیر (`WebRTC P2P DataChannel`)\n- **اصل بنیادین مالکیت داده:** گوشی اندرویدی کارشناس (`phone-primary`) مرجع اصلی و صاحب اختیار نهایی داده‌هاست و لپ‌تاپ/رایانه (`pc-companion`) دستگاه همراه برای جست‌وجو، ورود اطلاعات و پژوهش است.\n\n---\n\n## بخش اول: معرفی جامع نرم‌افزار، مأموریت و قابلیت‌های عملیاتی\n\n### ۱. چیستی و فلسفه طراحی نرم‌افزار\n«سامانه کتابخانه و پژوهش مرکز اسناد گلزار شهدای تهران» یک سامانه تخصصی، آفلاین‌محور (`Offline-First` / `Local-First`) و بدون وابستگی به سرورهای ابری ذخیره‌سازی داده است که برای مدیریت یکپارچه **موجودی فیزیکی کتابخانه**، **بانک جامع شهدای گلزار تهران** و **ارتباطات پژوهشی کتاب و شهید** طراحی و پیاده‌سازی شده است.\n\nاین نرم‌افزار دو محیط کاری را بدون نیاز به اینترنت پایدار یا انتقال دستی روزانه فایل‌های اکسل به هم پیوند می‌دهد:\n1. **محیط میدانی کنار قفسه‌ها (گوشی اندرویدی — `phone-primary`):** برای انبارگردانی سریع، ثبت موقعیت فیزیکی کتاب‌ها در قفسه‌ها (`SH-01` تا `SH-04`)، ثبت نسخه‌های فیزیکی (`CP-xxxxxx`) و کنترل نهایی داده‌ها.\n2. **محیط میز کار پژوهشی (لپ‌تاپ/رایانه — `pc-companion`):** برای جست‌وجوی پیشرفته، استخراج مطالب پژوهشی از صفحات کتاب‌ها، پالایش صف بررسی کارشناس و تولید گزارش‌های مدیریتی ۱۶گانه.\n\n---\n\n### ۲. پایگاه‌های داده مرجع و آمار بنیادین تعبیه‌شده در سامانه\nنرم‌افزار بر پایه ممیزی سلول‌به‌سلول ۴ فایل اکسل مرجع مرکز اسناد (**۱۳٬۴۸۵ سلول بررسی‌شده با ۰ اختلاف**) بنا شده و داده‌های پایه زیر را به‌صورت توکار (`Built-in`) و تغییرناپذیر در خود دارد:\n- **۹۸۰ عنوان کتاب مرجع (`BK-0001` تا `BK-0980`):** شامل ۴۱۳ کتاب انتشارات سوره مهر، کتاب‌های نشر شاهد و سایر ناشران حوزه دفاع مقدس و ایثار و شهادت.\n- **۶ گروه موضوعی استاندارد کتابخانه:**\n  1. `R` — مرجع، فهرست‌ها و کلیات (`#1F4E79`)\n  2. `H` — تاریخ و عملیات دفاع مقدس (`#2E7D5B`)\n  3. `A` — زندگی‌نامه، خاطرات و وصیت‌نامه شهدا (`#8C3B2B`)\n  4. `P` — ادبیات، شعر، داستان و هنر مقاومت (`#6B4E9B`)\n  5. `K` — کودک و نوجوان (`#C87A19`)\n  6. `M` — اسناد، عکس، آلبوم و نشریات (`#3B6E8C`)\n- **بانک جامع ۲۸٬۳۶۸ شهید (`AllMartyrsDatabase`):** شامل **۲۷٬۹۹۹ شهید آرمیده در گلزار شهدای تهران** + **۳۶۹ شهید خارج از گلزار / یادبود / جاویدالاثر** همراه با جزئیات قطعه، ردیف، شماره مزار، تاریخ شهادت، محل شهادت و کد رهگیری.\n- **۶۱۶ ارتباط فعال کتاب و شهید (در قالب ۸۳۶ سطر پژوهشی):** شامل ۳۷۹ ارتباط مستند از فایل پژوهشی سوره مهر (تطبیق‌یافته با ۲۳۶ شهید یکتا) و ۲۳۷ ارتباط از فایل قطعات شهدا.\n- **۵۶۷ رکورد در صف بررسی کارشناس (`pendingReviews`):** برای تکمیل نواقص اطلاعاتی (شماره صفحه، تطبیق مزار یا تصمیم کارشناسی).\n- **۱۶ گروه چندشهیدی (`multiMartyrGroups` — ۱۹۸ سطر):** برای تفکیک و تعیین تکلیف کتاب‌هایی که به چندین شهید یا عبارات جمعی اشاره دارند.\n\n---\n\n### ۳. ساختار ۵ تب اصلی رابط کاربری (حفظ کامل معماری بصری)\nنرم‌افزار دارای **۵ منوی اصلی** در نوار ناوبری بالا (دسکتاپ) و نوار پایین (موبایل) است:\n\n#### ۱) تب «خانه» (`HomeDashboardTab`)\n- نمایش داشبورد مدیریتی و آمار تفکیک‌شده (بدون درهم‌تنیدگی شمارش ردیف‌های اکسل با جلدهای فیزیکی قفسه و ارتباطات پژوهشی).\n- نمایش وضعیت پیشرفت انبارگردانی قفسه‌ها، توزیع موضوعی ۶گانه، دسترسی سریع به راهنمای نصب PWA روی اندروید و خلاصه وضعیت همگام‌سازی دو دستگاه.\n\n#### ۲) تب «کتابخانه» (`QuickInventoryTab` و `ShelfMapAndLabelsTab`)\n- **جست‌وجو و فیلتر چندبعدی:** بر اساس عنوان، نویسنده، ناشر، کد کتاب (`BK`)، گروه موضوعی ۶گانه، شماره قفسه (`SH-01` تا `SH-04`)، طبقه (`T01` تا `T06`) و وضعیت فیزیکی (`دیده شد و ثبت شد`، `نیازمند بررسی`، `پیدا نشد`).\n- **کشوی انبارگردانی سریع درون‌خطی (`Inline Rapid Audit Drawer`):** باز شدن فرم ثبت سریع دقیقاً زیر هر کارت کتاب و دکمه **«ذخیره سریع و رفتن به کتاب بعدی ⬇️»** برای کار با یک دست در کنار قفسه‌ها.\n- **مدیریت نسخه‌های فیزیکی مستقل (`BookCopyRecord` — `CP-xxxxxx`):** تفکیک کامل مفهوم «عنوان کتاب (`BK`)» از «نسخه/جلد فیزیکی روی قفسه (`CP`)» با قابلیت ثبت بارکد، وضعیت ظاهری جلد و موقعیت قفسه برای هر نسخه.\n- **ثبت کتاب‌های خارج از فهرست اکسل (`outside-list`):** امکان افزودن کتاب‌های جدیدی که در قفسه حضور دارند اما در فهرست اولیه ۹۸۰ کتاب نبوده‌اند.\n- **نقشه شماتیک قفسه‌ها و چاپ برچسب عطف (`ShelfMapAndLabelsTab`):** تولید برچسب‌های استاندارد کدینگ قفسه (`SH-01-T02-A-014`) با قابلیت چاپ.\n\n#### ۳) تب «شهدا» (`AllMartyrsDatabaseTab`)\n- کاوش و فیلتر فوری در بانک رسمی **۲۸٬۳۶۸ شهید** بر اساس نام، نام خانوادگی، نام پدر، قطعه، ردیف، شماره مزار، عملیات و سال شهادت.\n- **سیستم کامل کارشناسی پرونده‌های شهدا (`CRUD & Dual Verification`):** امکان ثبت شهید جدید، ویرایش پرونده، حذف امن با پاک‌سازی آبشاری (`Cascade Delete`) و اعتبارسنجی دوگانه:\n  - *وضعیت هویت:* `تأییدشده` | `نیازمند بررسی` | `ردشده / غیرمعتبر`\n  - *وضعیت مزار:* `تأییدشده میدانی/سند` | `نیازمند تطبیق مزار` | `یادبود / غیرتهرانی`\n- مشاهده تمام کتاب‌های مرتبط با هر شهید در شناسنامه او و پرش مستقیم به تب جست‌وجوی هوشمند.\n\n#### ۴) تب «جست‌وجوی هوشمند» (`SmartBookSearchTab`)\n- **جست‌وجوی دوطرفه کتاب و شهید:** تطبیق هوشمند نام شهید با مخزن ۹۸۰ کتاب، بانک ارتباطات سوره مهر و استعلام هدفمند از درگاه‌های مرجع کتاب‌شناختی (کتابخانه ملی ایران، خانه کتاب `ketab.ir` و ۱۸ ناشر تخصصی دفاع مقدس).\n- **ممنوعیت مطلق حدس‌زنی و داده‌سازی خودکار (قانون D-01 و رفع کامل خطای SS-0007):** هیچ کتاب یا ناشر فرضی تولید نمی‌شود؛ در صورت نبود کتاب در مخزن، نتیجه صریحاً `۰ رکورد` اعلام می‌شود و هیچ پیشنهادی بدون **تأیید کارشناس** وارد پرونده قطعی شهید نمی‌گردد.\n- **موتور جست‌وجوی انبوه اکسل‌محور:** امکان بارگذاری فایل اکسل (`.xlsx`, `.csv`) یا فهرست متنی اسامی شهدا برای تطبیق دسته‌ای با مخزن کتابخانه.\n- **حافظه پایدار تصمیمات کارشناس (D-19):** حفظ دائمی وضعیت پیشنهادهای «تأییدشده» و «ردشده (همراه با دلیل رد کارشناس)» در جست‌وجوهای بعدی.\n\n#### ۵) تب «پژوهش» و «مدیریت، پشتیبان و گزارش‌ها» (`ResearchAndLinksTab`, `DepositoryAndExportHub`, `BackupAndExportTab`, `PilotTestAndReportTab`, `DeviceSyncPanel`)\n- **پژوهش و ارتباط کتاب و شهید (`ResearchAndLinksTab`):** مدیریت ۶۱۶+ پیوند کتاب–شهید، ثبت مطالب استخراج‌شده (`ExtractedContentItem` شامل خاطره، وصیت‌نامه، عکس، زندگینامه با ذکر شماره صفحه)، پالایش تعاملی ۵۶۷ مورد نیازمند بررسی و تعیین تکلیف ۱۶ گروه چندشهیدی.\n- **همگام‌سازی مستقیم گوشی و لپ‌تاپ (`DeviceSyncPanel`):** اتصال امن دو دستگاه با QR Code و انتقال مستقیم داده‌ها از طریق `WebRTC DataChannel`.\n- **پشتیبان‌گیری نسخه ۳ (`BackupService v3`):** تولید و بازیابی بسته پشتیبان کامل JSON شامل هر ۱۱ مجموعه عملیاتی با بررسی `SHA-256` و خروجی‌های چندشیتی استاندارد Excel (`.xlsx`) و CSV.\n- **گزارش‌های مدیریتی ۱۶گانه و موتور اجرای واقعی آزمون‌های پذیرش (`PilotTestAndReportTab`):** محاسبه زنده ۱۶ شاخص کلیدی مرکز اسناد و اجرای واقعی تست‌های ۶ دسته الزامی (`CAT-A` تا `CAT-F`) روی حافظه مرورگر.\n\n---\n\n## بخش دوم: معماری فنی لایه ذخیره‌سازی محلی و تراکنش اتمیک چندمجموعه‌ای (`IndexedDB` + `localStorage`)\n\n### ۱. معماری ذخیره‌سازی دوگانه (`Dual-Layer Local Persistence`)\nتمامی داده‌های عملیاتی سامانه در مرورگر دستگاه تحت فضای نام اختصاصی `book` در دو لایه ذخیره می‌شوند (`src/utils/indexedDbStorage.ts`):\n1. **لایه اول (اصلی و حجیم):** پایگاه داده `IndexedDB` با نام `MarkazAsnadBookLibraryDB` (نسخه ۲) و ObjectStore اصلی `app_state_store`.\n2. **لایه دوم (پشتیبان همگام):** حافظه `localStorage` مرورگر به همراه کلیدهای متادیتای زمان ویرایش (`__meta_updated_at__:<key>`).\n\n### ۲. تضمین اتمیک بودن ذخیره ۶ مجموعه عملیاتی در یک تراکنش واحد (`saveOperationalDataBatchAtomic`)\nدر جریان همگام‌سازی (`Device Sync`)، ۶ مجموعه عملیاتی باید با هم در دستگاه مقصد ذخیره شوند:\n1. `auditRecords` (`markaz_asnad_book_audit_v1`)\n2. `bookCopies` (`markaz_asnad_book_copies_v1`)\n3. `customMartyrs` (`markaz_asnad_custom_martyrs_v1`)\n4. `links` (`markaz_asnad_research_links_v1`)\n5. `pendingReviews` (`markaz_asnad_pending_reviews_v1`)\n6. `extractedItems` (`markaz_asnad_extracted_items_v1`)\n\nبرای جلوگیری از **ذخیره نیمه‌کاره (Partial Apply)** در صورت بروز خطا یا پر شدن سهمیه حافظه در میانه کار، سازوکار زیر پیاده‌سازی شده است:\n- **تراکنش واحد `readwrite` در `IndexedDB` (`idbSetBatchWithStatus`):** هر ۶ کلید در یک تراکنش واحد `db.transaction('app_state_store', 'readwrite')` با یک مهر زمانی یکنواخت و اکیداً صعودی (`nextMonotonicTimestamp`) نوشته می‌شوند. اگر نوشتن هر یک از کلیدها با خطا مواجه شود، تراکنش بلافاصله `tx.abort()` شده و موتور `IndexedDB` به طور خودکار تمام تغییرات کلیدهای قبلی همان تراکنش را Rollback می‌کند.\n- **بازگردانی کامل `localStorage` (`Full Snapshot Rollback`):** پیش از نوشتن در `localStorage`، از مقدار قبلی هر ۶ کلید و متادیتای زمانی آن‌ها Snapshot گرفته می‌شود. اگر نوشتن کلید چهارم یا پنجم با خطای `QuotaExceededError` مواجه شود:\n  - اگر `IndexedDB` نیز موفق نبوده باشد، تمام کلیدهای `localStorage` به Snapshot دقیق قبل از عملیات بازگردانی می‌شوند و عملیات با `ok: false` متوقف می‌گردد (هیچ ACKای ارسال نمی‌شود).\n  - اگر تراکنش اتمیک `IndexedDB` هر ۶ مجموعه را کامل ذخیره کرده باشد اما `localStorage` به دلیل محدودیت ۵ مگابایتی مرورگر جا نداشته باشد، `localStorage` به وضعیت قبلی بازگردانی می‌شود ولی مهر زمانی جدید در `IndexedDB` بزرگ‌تر از `localStorage` است (`idbUpdatedAt > localUpdatedAt`).\n- **رفتار هوشمند هنگام Refresh (`hydrateOperationalKey`):** در زمان بارگذاری مجدد صفحه، تابع `hydrateOperationalKey` مقادیر `IndexedDB` و `localStorage` را مقایسه می‌کند؛ از آنجا که `idbUpdatedAt >= localUpdatedAt` است، نسخه کامل و اتمیک `IndexedDB` (`source: 'indexedDB'`) انتخاب شده و هرگز اجازه داده نمی‌شود داده ناقص یا قدیمی `localStorage` جایگزین داده کامل `IndexedDB` شود.\n- **ذخیره اتمیک متادیتای همگام‌سازی (`commitSyncMetadataAtomically` در `syncStorage.ts`):** سه کلید متادیتای همگام‌سازی (`RECORD_META_MAP_KEY`، `BASELINE_CHANGE_MAP_KEY` و `APPLIED_PACKAGES_KEY`) تنها **پس از** موفقیت کامل ذخیره هر ۶ مجموعه عملیاتی، به صورت اتمیک ذخیره می‌شوند و در صورت خطا در هر یک، هر سه کلید به وضعیت قبلی Rollback می‌شوند.\n\n---\n\n## بخش سوم: معماری فنی همگام‌سازی مستقیم گوشی و لپ‌تاپ (`src/modules/device-sync/`)\n\nماژول `src/modules/device-sync/` وظیفه اتصال مستقیم دو دستگاه و تبادل امن بسته‌های داده را بر عهده دارد و شامل ۷ زیرماژول تخصصی است:\n\n### ۱. جفت‌سازی دوطرفه با کد QR و اعتبارسنجی قوی (`pairingService.ts`)\n- تولید شناسه نشست تصادفی رمزنگاری‌شده ۱۹۲ بیتی (`sessionId` با ۴۸ کاراکتر هگز از `crypto.getRandomValues`) و کد جفت‌سازی ۱۲ کاراکتری مستقل (`XXXX-XXXX-XXXX`).\n- پشتیبانی از شروع نشست (`Host`) هم از روی گوشی و هم از روی لپ‌تاپ: هر دستگاه می‌تواند QR Code تولید کند و دستگاه دوم با دوربین آن را اسکن کرده یا کد را وارد نماید.\n- محاسبه چک‌سام ۶ کاراکتری (`SHA-256`) برای تشخیص فوری خطای تایپ کد قبل از ارسال به شبکه.\n\n### ۲. سیگنالینگ موقت و امن با قفل تراکنشی (`signalingService.ts` + `firestore.rules`)\n- استفاده از Firebase Firestore **صرفاً به عنوان کانال سیگنالینگ موقت (SDP Offer/Answer و ICE Candidates)** برای برقراری اتصال WebRTC. هیچ‌گاه هیچ رکورد کتاب، شهید یا پژوهشی به Firebase ارسال نمی‌شود.\n- ذخیره صرفاً هش یک‌طرفه کد جفت‌سازی (`pairingCodeDigest = SHA-256(\"markaz-asnad-pairing-v2:\" + sessionId + \":\" + normalizedCode)`) در سند سیگنالینگ.\n- **قفل اتمیک `peerUid` (`claimAndInspectSignalingSession`):** به محض اسکن QR توسط دستگاه دوم، با استفاده از `runTransaction`، فیلد `peerUid` به UID دستگاه دوم قفل می‌شود تا هیچ دستگاه سومی نتواند وارد نشست شود.\n- **حذف خودکار اسناد موقت (`cleanupSignalingDocumentOnly`):** به محض باز شدن کانال مستقیم `RTCDataChannel` و تبادل پیام `HELLO_HANDSHAKE`، سند سیگنالینگ و زیرمجموعه کاندیداهای آن از Firestore پاک می‌شوند.\n\n### ۳. کانال ارتباطی مستقیم و انتقال قطعه‌بندی‌شده (`peerConnection.ts` + `transferProtocol.ts`)\n- برقراری کانال مستقیم `RTCDataChannel` (رمزنگاری‌شده در لایه انتقال با استاندارد `DTLS-SRTP`).\n- **تأیید نهایی اتصال روی گوشی (`onPhoneApprovalRequired`):** حتی اگر گوشی تولیدکننده QR (`Host`) باشد، پس از پیوستن لپ‌تاپ، کادر تأیید روی گوشی نمایش داده می‌شود تا کاربر گوشی اتصال را تأیید کند.\n- **پروتکل انتقال تکهتکه (`Chunked Transfer Protocol`):** بسته‌های بزرگ JSON به قطعات ۱۶ کیلوبایتی (`CHUNK_SIZE = 16384`) تقسیم شده و همراه با هش یکپارچگی کل بسته (`payloadChecksum = SHA-256`) ارسال می‌شوند. در مقصد، تنها پس از دریافت تمام قطعات و تطابق دقیق `SHA-256`، بسته تحویل موتور همگام‌سازی می‌شود.\n\n### ۴. قوانین سخت‌گیرانه تطبیق رکوردها و حفاظت از کتاب‌های هم‌نام (`syncEngine.ts` + `conflictResolver.ts`)\nموتور همگام‌سازی، تطبیق رکوردها را به تفکیک هر مجموعه و بدون ادغام اشتباه انجام می‌دهد:\n1. **کتاب‌ها (`matchAuditBookRecord`):**\n   - اولویت ۱: تطبیق با شناسه یکتای پایدار (`recordKey` / `syncId`).\n   - اولویت ۲: تطبیق با کلید ترکیبی کامل و غیرخالی (`normalizedTitle + normalizedAuthor + normalizedPublisher`)، تنها زمانی که حداقل یکی از دو فیلد `author` یا `publisher` مقدار واقعی داشته باشد.\n   - **خط قرمز کتاب‌های هم‌نام بدون نویسنده و ناشر:** اگر دو کتاب فقط در `title` یکسان باشند و هر دو فاقد `author` و `publisher` باشند، سیستم **هرگز آن‌ها را یکی فرض نمی‌کند و ادغام نمی‌کند**؛ هر دو رکورد با کلیدهای مستقل حفظ می‌شوند و یک هشدار تعارض (`CONF_AMBIGUOUS_...`) برای بررسی کارشناس ثبت می‌گردد.\n2. **تکمیل غیرمخرب فیلدهای خالی (`mergeAuditRecordsNonDestructively`):**\n   - اگر دو رکورد واقعاً مربوط به یک کتاب واحد باشند و یک طرف فیلد خالی داشته باشد که طرف دیگر آن را پر کرده است، فیلد خالی به صورت غیرمخرب تکمیل می‌شود (بدون پاک کردن هیچ داده موجودی).\n   - اگر هر دو دستگاه یک فیلد واحد را به دو مقدار متفاوت تغییر داده باشند، رکورد وارد فهرست تعارض (`SyncConflictItem`) می‌شود و طبق اصل مرجعیت گوشی، نسخه گوشی (`phone-primary`) به عنوان مقدار مرجع حفظ شده و نسخه لپ‌تاپ برای تصمیم کارشناس نمایش داده می‌شود.\n3. **تفکیک سایر مجموعه‌ها:**\n   - نسخه‌های فیزیکی (`matchBookCopyRecord`): فقط بر اساس `copyId`.\n   - پرونده‌های شهدا (`matchCustomMartyrRecord`): بر اساس `id` یا کد ملی/شماره پرونده معتبر یا ترکیب کامل (`نام + نام پدر + قطعه + ردیف + شماره مزار`).\n   - ارتباطات کتاب و شهید (`matchBookMartyrLinkRecord`): بر اساس `id` یا ترکیب چهارگانه (`bookId + martyrId + normalizedMartyrName + normalizedPage`).\n   - صف بررسی (`matchPendingReviewRecord`): فقط بر اساس `id`.\n\n### ۵. چرخه ۷ مرحله‌ای ذخیره پایدار و تأیید نهایی (`Strict 7-Step Durable ACK Lifecycle`)\nبرای تضمین اینکه هیچ انتقالی پیش از ذخیره واقعی در دیسک مقصد «موفق» اعلام نشود، ترتیب زیر در کد قفل شده است:\n1. **مرحله ۱:** دریافت کامل تمام قطعات بسته (`TRANSFER_START` -> `TRANSFER_CHUNK` -> `TRANSFER_END`).\n2. **مرحله ۲:** محاسبه و تطبیق هش `SHA-256` کل بسته دریافتی (`verifySyncPackageIntegrity`).\n3. **مرحله ۳:** تحلیل غیرمخرب بسته (`analyzeIncomingSyncPackage`) و تفکیک رکوردهای جدید، تکمیل‌شده و تعارض‌ها.\n4. **مرحله ۴:** اعمال تغییرات در حافظه با تعویق ثبت متادیتا (`deferMetadataCommit: true`).\n5. **مرحله ۵:** ذخیره پایدار و اتمیک هر ۶ مجموعه عملیاتی در `IndexedDB` + `localStorage` (`saveOperationalDataBatchAtomic`) به همراه بررسی سلامت پس از نوشتن و سپس ثبت اتمیک متادیتای همگام‌سازی (`commitSyncMetadataAtomically`).\n6. **مرحله ۶:** ارسال پیام `TRANSFER_ACK` با ساختار صریح `{ ok: true, applied: true, appliedRecordsCount }` **فقط و فقط در صورتی که مرحله ۵ با موفقیت ۱۰۰٪ انجام شده باشد**. (در حالت بازبینی دستی کارشناس روی گوشی، در لحظه دریافت بسته صرفاً پیام مرحله‌ای `TRANSFER_STAGE_RECEIPT` ارسال می‌شود و `TRANSFER_ACK` نهایی تا لحظه فشردن دکمه «تأیید و اعمال نهایی در گوشی» و ذخیره اتمیک در دیسک ارسال نمی‌گردد).\n7. **مرحله ۷:** در سمت فرستنده، تابع `isStrictValidTransferAck(ack)` بررسی می‌کند که حتماً `ack.ok === true && ack.applied === true` باشد؛ تنها پس از دریافت این ACK معتبر، `Baseline` فرستنده به‌روزرسانی می‌شود. هرگونه قطع ارتباط، خطای ذخیره‌سازی یا ACK با `applied: false` باعث حفظ کامل `Baseline` قبلی برای ارسال مجدد امن می‌شود.\n\n---\n\n## بخش چهارم: وضعیت فعلی مخزن، تست‌های خودکار و نقاط بازیابی (`Recovery Points`)\n\n1. **وضعیت کامپایل و تحلیل ایستا:**\n   - `npx tsc --noEmit` (`lint_applet`): **PASS (۰ خطا)**\n   - `npm run build` (`compile_applet`): **PASS (بیلد کامل نسخه Production)**\n2. **آزمون‌های خودکار اجراشده:**\n   - **۱۴ سناریوی مستقل مرحله اول همگام‌سازی:** بررسی صحت ACK، عدم تغییر Baseline در خطا، حفظ کتاب‌های هم‌نام بدون نویسنده/ناشر، تکمیل غیرمخرب فیلدهای خالی و تفکیک مجموعه‌ها -> **14/14 PASS**\n   - **۸ سناریوی مستقل مرحله دوم (ذخیره اتمیک چندمجموعه‌ای و Rollback):** بررسی ذخیره هم‌زمان ۶ مجموعه در یک تراکنش `IndexedDB`، شبیه‌سازی خطا در میانه ذخیره‌سازی و اثبات Rollback کامل بدون ذخیره نیمه‌کاره، بازیابی صحیح پس از Refresh و حفاظت از ۱۸ رکورد واقعی گوشی -> **8/8 PASS** (مجموعاً **22/22 PASS**)\n3. **نقاط بازیابی مستقل و تأییدشده با `SHA-256` روی دیسک:**\n   - `.recovery-point-ae08bac/` (`14/14 OK`)\n   - `.recovery-point-c4320b7/` (`11/11 OK`)\n   - `.recovery-point-ea73b03/` (`12/12 OK`)\n";
const dailyTechReport20261111Raw = "# گزارش فنی جامع فعالیت‌ها، معماری، اصلاحات و نتایج آزمون روزانه\n**سامانه کتابخانه، پژوهش و مرکز اسناد گلزار شهدای تهران**\n\n- **تاریخ گزارش:** چهارشنبه ۲۰ آبان ۱۴۰۵ (۱۱ نوامبر ۲۰۲۶)\n- **مخزن رسمی GitHub:** `https://github.com/forog1980-star/book` (شاخه `main`)\n- **پیوند انتشار وب (GitHub Pages):** `https://forog1980-star.github.io/book/`\n- **نسخه ساخت و کش (Build & Cache Version):** `2026-11-11-v12` (`markaz-asnad-main-book-v12`)\n- **وضعیت کامپایل و بررسی نوع‌ها (Build & TypeCheck):** `PASS` (`Exit Code: 0` بدون هیچ‌گونه خطا یا هشدار)\n- **وضعیت هسته داده و ذخیره‌سازی (Local-First Storage Core):** ۱۰۰٪ دست‌نخورده و محافظت‌شده (`IndexedDB` + `localStorage`)\n\n---\n\n## خلاصه مدیریتی (Executive Summary)\n\nدر جریان فعالیت‌های مهندسی، توسعه و بهینه‌سازی امروز، **۸ محور کلیدی و عملیاتی** در «سامانه کتابخانه، ثبت موجودی و پژوهش مرکز اسناد گلزار شهدای تهران» طراحی، ریشه‌یابی، پیاده‌سازی و راستی‌آزمایی شد:\n\n1. **طراحی و استقرار موتور نمایه‌سازی سراسری ۲۸٬۳۶۸ شهید گلزار شهدای تهران (`martyrsCrossMatchEngine.ts`) با کش دائمی یک‌بارمصرف (`One-Time Persistent Index`):** بارگذاری غیرمسدودکننده بانک ۲۸٬۳۶۸ شهید (`۲۷٬۹۹۹` شهید آرمیده در قطعات گلزار شهدای بهشت زهرا (س) + `۳۶۹` شهید خارج از قطعات/یادبود)، ساخت جداول هش با پیچیدگی زمانی $O(1)$ و ذخیره‌سازی دائمی نمایه تطبیق ۹۸۰ کتاب کاتالوگ در حافظه مرورگر (`book_tehran_determined_index_v2`) برای اجرای آنی و بدون مکث در بارگذاری‌های بعدی.\n2. **طراحی و استقرار سراسری نشان کپسولی قرمزرنگ «تهرانی» (`TehranMartyrBadge.tsx`) در تمام ۵ تب اصلی و پنجره‌های سامانه:** نمایش هوشمند نشان «تهرانی» در کنار نام شهدای گلزار شهدای تهران و عنوان کتاب‌های مرتبط با شهدای تهرانی در تب‌های «خانه»، «کتابخانه»، «بانک جامع شهدا»، «جست‌وجوی هوشمند»، «پژوهش و ارتباطات» و «انبار اسناد و خروجی‌ها» به همراه فیلترهای اختصاصی «فقط شهدای تهرانی».\n3. **پیاده‌سازی قانون استثنای شهدای غیرتهرانی (`غ تهرانی`) و تشخیص هوشمند تشابه اسمی (`Homonym Detection`):** جلوگیری ۱۰۰٪ از درج نشان «تهرانی» برای رکوردهایی که در شیت‌های مرجع دارای قید «غ تهرانی»، «غیر تهرانی» یا نام سایر استان‌ها هستند؛ و هدایت خودکار موارد هم‌نام با بانک ۲۸٬۳۶۸ شهید تهران به وضعیت «نیازمند بررسی کارشناسی (تشابه اسمی با شهدای تهران — ثبت‌شده به عنوان غیرتهرانی)» بدون تغییر خودسرانه مزار.\n4. **ریشه‌یابی و رفع قطعی تداخل نام ناشر با نام شهید (مورد خاص «انتشارات شهید ابراهیم هادی») و حفاظت از تأییدهای کارشناس:** پیاده‌سازی تابع `stripPublisherAndAutoNotesForMartyrMatch` برای حذف نام ناشر و یادداشت‌های سیستمی از متن تطبیق کتاب، و پاک‌سازی خودکار رکوردهای ذخیره‌شده (`sanitizeAuditRecordsMap` و `sanitizeSmartSuggestionsList`) تا هیچ کتابی صرفاً به خاطر نام ناشر به شهید ابراهیم هادی منتسب نشود و تأییدهای کارشناس هرگز به وضعیت «نیازمند بررسی» بازنگردند.\n5. **ارتقای موتور خروجی چندشیتی Excel (`src/modules/excel-export/`) با فیلتر و ستون «وضعیت شهید تهرانی»، الگوی ۶ عنوان موضوعی اصلی و فونت ۱۰۰٪ یکپارچه `Vazirmatn`:** افزودن فیلتر «فقط کتاب‌ها و شهدای تهرانی» در پنجره تنظیمات Excel، درج ستون رسمی `وضعیت شهید تهرانی (گلزار شهدای تهران)` در هر ۵ برگه خروجی، قرار دادن الگوی آماده شماره ۱ برای ۶ موضوع اصلی (`R, P, H, A, K, M`) با قابلیت تیک‌زدن تکی یا همه، اختیاری‌سازی جهت گزارش، اصلاح دکمه «✕ حذف انتخاب‌ها» و تثبیت ۱۰۰٪ فونت `Vazirmatn` در تمام سلول‌ها.\n6. **ایمن‌سازی چرخه Preview تا Apply و همگام‌سازی دوطرفه گوشی و رایانه در انتقال JSON (`jsonTransferEngine.ts`):** قفل اثرانگشت وضعیت مقصد (`DEST_FP_SHA256_...`) بین مرحله پیش‌نمایش و اجرای ادغام، حل برخورد شناسه‌های `LOG-xxxx` در `auditLog` بین گوشی و رایانه، و پیاده‌سازی ادغام سه‌طرفه سطح فیلد (`3-Way Field-Level Merge`).\n7. **رفع خطای `Permission denied` در اشتراک‌گذاری فایل JSON و اصلاح چیدمان پنجره خلاصه خروجی (`JsonSystemTransferSection.tsx`):** جایگزینی خطای مسدودکننده مرورگر با باز شدن خودکار «پنل ارسال فایل JSON در پیام‌رسان‌ها (ایتا، بله، روبیکا، تلگرام، واتساپ و ایمیل)» و رفع بیرون‌زدگی کد یکتای صحت داده (`SHA256_...`) و بریدگی عنوان «نام فایل» در چیدمان راست‌به‌چپ.\n8. **بهینه‌سازی سرعت رندر و جست‌وجو (`0ms Lag`) و ارتقای مکانیزم کش‌زدایی نسخه موبایل (`Cache Busting v12`):** پیش‌محاسبه نگاشت جست‌وجوی کتابخانه (`precomputedSearchMap`) و کش‌های درون‌حافظه‌ای $O(1)$ برای تایپ بدون مکث، و ارتقای اسکریپت کش‌زدایی خودکار در `index.html` برای دریافت تضمین‌شده آخرین نسخه در موبایل و دسکتاپ.\n\n---\n\n## تشریح فنی فعالیت‌ها و اقدامات انجام‌شده (به‌تفکیک ۸ فاز مهندسی)\n\n### فاز ۱: موتور نمایه‌سازی سراسری ۲۸٬۳۶۸ شهید گلزار شهدای تهران و کش دائمی یک‌بارمصرف (`src/utils/martyrsCrossMatchEngine.ts`)\n\n#### ۱-۱. ساختار داده‌ای و بارگذاری غیرمسدودکننده (`Chunked Async Parsing`)\n- بانک جامع شهدای گلزار تهران (`public/data/golzar_martyrs.xlsx`) شامل دو شیت `golzar_martyrs` (**۲۷٬۹۹۹ شهید** آرمیده در قطعات گلزار شهدای بهشت زهرا (س)) و `outside_golzar_martyrs` (**۳۶۹ شهید** خارج از قطعات / یادبود) و در مجموع **۲۸٬۳۶۸ رکورد رسمی** است.\n- در تابع `loadCachedGolzarMartyrs()`، پردازش ردیف‌ها در قطعات ۳٬۵۰۰ تایی (`CHUNK_SIZE = 3500`) با تنفس نخ اصلی مرورگر (`await new Promise((r) => setTimeout(r, 0))`) انجام می‌شود تا رابط کاربری در حین بارگذاری اولیه کاملاً روان باقی بماند.\n- برای هر رکورد، نام نرمال‌شده (`normalizedFullName`)، نام بدون القاب (`stripTitlesForTehranIndex`) و کلید فشرده بدون فاصله (`compactFullName`) محاسبه شده و در دو جدول هش `cachedGolzarByNormName` و `cachedGolzarByCompactName` قرار می‌گیرد تا جست‌وجوی هر نام در بانک ۲۸٬۳۶۸ نفری با پیچیدگی زمانی **$O(1)$** (بدون پیمایش آرایه) انجام شود.\n\n#### ۱-۲. کش دائمی یک‌بارمصرف (`One-Time Persistent Index`) در حافظه مرورگر\n- به منظور حذف کامل هرگونه مکث در بارگذاری‌های بعدی برنامه، ساختار `PersistedTehranDeterminedIndex` تحت کلید `book_tehran_determined_index_v2` در `localStorage` پیاده‌سازی شد.\n- در اولین اجرای کامل که کاتالوگ ۹۸۰ کتاب و بانک ۲۸٬۳۶۸ شهید آماده می‌شوند، تابع `enrichLinksAndCatalogBooksWith28kTehranIndex` تمام پیوندهای خودکار کشف‌شده بین کتاب‌ها و شهدای تهرانی (`autoBookLinks`) و رکوردهای شهدای منطبق (`knownMartyrs`) را ذخیره می‌کند.\n- در دفعات بعدی باز شدن برنامه، تابع `loadPersistedTehranIndexSync()` در بدو بارگذاری ماژول (در زمان `0ms`) نمایه ذخیره‌شده را بازیابی می‌کند و تنها کتاب‌هایی که توسط کارشناس در `auditRecords` ویرایش یا تازه ثبت شده‌اند به‌صورت تفاضلی (`Differential Scan`) اسکن می‌شوند.\n\n#### ۱-۳. تکمیل خودکار نشانی مزار شهدای تهرانی\n- اگر شهیدی در شیت‌های پژوهشی (مانند شیت سوره مهر) بدون شماره قطعه، ردیف یا شماره مزار ثبت شده باشد، اما در بانک ۲۸٬۳۶۸ شهید گلزار شهدای تهران دارای تطابق قطعی باشد (و غیرتهرانی نباشد)، فیلدهای `gravePieceRaw`، `graveRowRaw` و `graveNumberRaw` به‌طور خودکار از بانک گلزار تکمیل می‌شوند.\n\n---\n\n### فاز ۲: طراحی و استقرار سراسری نشان «تهرانی» (`src/components/TehranMartyrBadge.tsx`) و فیلترهای اختصاصی\n\n#### ۲-۱. مشخصات کامپوننت `TehranMartyrBadge`\n- کامپوننت مستقل `src/components/TehranMartyrBadge.tsx` به صورت یک نشان کپسولی ظریف با پس‌زمینه قرمز آرشیوی (`bg-[#B91C1C]`)، حاشیه ملایم (`border-[#991B1B]/40`) و متن سفید پررنگ **`تهرانی`** در سه اندازه استاندارد (`xs`، `sm`، `md`) طراحی شد.\n\n#### ۲-۲. یکپارچه‌سازی در تمام ۵ تب اصلی سامانه\n1. **تب ۱ — خانه (`HomeDashboardTab.tsx`):**\n   - نمایش نشان «تهرانی» کنار عنوان کتاب‌های دارای شهید تهرانی (`dossier.hasTehranMartyr`) و کنار نام شهدای تهرانی (`rel.isTehranMartyr`) در کارت‌ها، جداول و پنجره «پرونده یکپارچه کتاب» (`Unified Book Dossier`) و «پرونده یکپارچه شهید».\n   - افزودن دکمه فیلتر سریع **`شهدای تهرانی (گلزار تهران)`** (`statModalSubFilter === 'tehran_martyrs'`) در بالای پنجره‌های آماری داشبورد.\n2. **تب ۲ — کتابخانه و انبارگردانی سریع (`QuickInventoryTab.tsx`):**\n   - محاسبه زنده تعداد کتاب‌های دارای شهید تهرانی (`tehranMartyrBooksCount`) و افزودن گزینه **`۲. کتاب‌های شهدای تهرانی (منطبق با گلزار شهدای تهران)`** در منوی فیلتر وضعیت ممیزی.\n   - نمایش نشان «تهرانی» در کنار عنوان کتاب در فهرست کاتالوگ، در کشوی جانمایی سریع درون‌خطی و در بخش شهدای مرتبط با کتاب.\n   - افزودن کلیدواژه‌های `تهرانی`، `شهدای تهرانی` و `گلزار تهران` به نمایه جست‌وجوی کتاب‌های مرتبط.\n3. **تب ۳ — بانک جامع شهدا (`AllMartyrsDatabaseTab.tsx`):**\n   - نمایش نشان «تهرانی» در کنار نام شهدای گلزار در جدول اصلی ۲۸٬۳۶۸ شهید، کارت‌های موبایل، پنجره جزئیات پرونده شهید و مودال اتصال کتاب به شهید.\n4. **تب ۴ — جست‌وجوی هوشمند (`SmartBookSearchTab.tsx`):**\n   - نمایش نشان «تهرانی» در کنار نام شهید و عنوان کتاب در نتایج جست‌وجوی انفرادی، نتایج جست‌وجوی انبوه اکسل‌محور و صف بررسی کارشناس.\n5. **تب ۵ — پژوهش، ارتباطات و انبار اسناد (`ResearchAndLinksTab.tsx` و `DepositoryAndExportHub.tsx`):**\n   - نمایش نشان «تهرانی» در جداول ارتباط کتاب و شهید، نمای کتاب‌محور و نمای شهیدمحور.\n   - افزودن گزینه فیلتر **`شهدای تهرانی (منطبق با گلزار شهدای تهران)`** (`tehran_martyrs_only` / `tehran_only`) برای گزارش‌گیری و پالایش متمرکز روی شهدای گلزار تهران.\n\n---\n\n### فاز ۳: قانون استثنای شهدای غیرتهرانی (`غ تهرانی`) و مدیریت هوشمند تشابه اسمی (`Homonym Detection`)\n\nطبق دستور صریح کارشناسی مرکز اسناد، دو قاعده سخت‌گیرانه در `src/utils/martyrsCrossMatchEngine.ts` پیاده‌سازی شد:\n\n1. **تشخیص صریح رکوردهای غیرتهرانی (`isExplicitlyNonTehranRecord`):**\n   - هر رکوردی که در ستون قطعه مزار (`gravePiece`)، نام شهید، توضیحات منبع یا یادداشت کارشناس دارای عبارات `غ تهرانی`، `غیر تهرانی`، `غیرتهرانی`، `شهرستان`، `شهدای غیر تهرانی` یا نام گلزار سایر استان‌ها (قم، مشهد، اصفهان، شیراز، تبریز، همدان، کرمانشاه، خراسان، خوزستان، فارس، مازندران، گیلان) باشد، صراحتاً به عنوان `isNonTehran = true` علامت‌گذاری شده و **تحت هیچ شرایطی نشان «تهرانی» دریافت نمی‌کند** (`isTehran = false`).\n2. **مدیریت تشابه اسمی با بانک ۲۸٬۳۶۸ شهید تهران (`hasHomonymIn28kNeedsReview`):**\n   - اگر شهیدی در شیت‌های مرجع با قید `غ تهرانی` ثبت شده باشد، اما نام و نام خانوادگی او دقیقاً هم‌نام با یکی از شهدای موجود در بانک ۲۸٬۳۶۸ نفری گلزار شهدای تهران باشد، سیستم هرگز به صورت خودسرانه مزار شهید تهرانی را به او نسبت نمی‌دهد؛ بلکه رکورد را با وضعیت **`نیازمند بررسی کارشناسی (تشابه اسمی با شهدای تهران — ثبت‌شده به عنوان غیرتهرانی)`** و توضیح دقیق قطعه/ردیف/شماره شهید هم‌نام در تهران به صف بازبینی کارشناس هدایت می‌کند تا کارشناس تصمیم نهایی را اتخاذ کند.\n\n---\n\n### فاز ۴: رفع قطعی باگ تداخل نام ناشر با نام شهید (مورد خاص «انتشارات ابراهیم هادی») و حفاظت از تأییدهای کارشناس\n\n#### ۴-۱. ریشه‌یابی فنی مشکل\n- در کاتالوگ کتابخانه، تعدادی از کتاب‌ها توسط **«انتشارات شهید ابراهیم هادی»** (یا «نشر ابراهیم هادی» / «گروه فرهنگی شهید ابراهیم هادی») منتشر شده‌اند، در حالی که موضوع کتاب درباره شهید دیگری است.\n- الگوریتم قبلی به دلیل حضور عبارت «ابراهیم هادی» در نام ناشر یا در متن ترکیبی مشخصات کتاب، این کتاب‌ها را به «شهید ابراهیم هادی» (قطعه ۲۶، ردیف ۵۲، شماره ۱) مرتبط می‌کرد یا یادداشت خودکار `⚠️ نیازمند بررسی: تشابه نام با...` به فیلد `notes` کتاب می‌افزود که باعث می‌شد حتی پس از تأیید کارشناس، کتاب مجدداً در دسته «نیازمند بررسی» قرار گیرد.\n\n#### ۴-۲. راهکار مهندسی پیاده‌سازی‌شده در `martyrsCrossMatchEngine.ts` و `App.tsx`\n1. **تابع پالایش `stripPublisherAndAutoNotesForMartyrMatch(rawText, publisherRaw)`:**\n   - پیش از هرگونه استخراج یا تطبیق نام شهید از متن کتاب (در `extractTehranMartyrsFromBookText`، `matchSingleBookAgainstMartyrs`، `runFastCrossMatchBooksAnd28kMartyrs` و `SmartBookSearchTab.tsx`)، ابتدا تمامی عبارات مرتبط با ناشر شامل `(انتشارات|نشر|موسسه|مؤسسه|گروه فرهنگی|مرکز نشر|چاپ) (شهید )?ابراهیم هادی` و همچنین نام ناشر ثبت‌شده در فیلد `publisher` به طور کامل از رشته جست‌وجو حذف می‌شود.\n   - در نتیجه، اگر «ابراهیم هادی» صرفاً نام ناشر کتاب باشد، هرگز با «شهید ابراهیم هادی» تطبیق کاذب نمی‌خورد؛ اما اگر عنوان یا متن خود کتاب واقعاً درباره «شهید ابراهیم هادی» باشد (مانند کتاب «سلام بر ابراهیم» یا صفحه ۱۴۷ کتاب «یک محسن عزیز»)، ارتباط واقعی کاملاً حفظ می‌شود.\n2. **پاک‌سازی خودکار رکوردهای قبلی و حفاظت مطلق از تأیید کارشناس (`App.tsx`):**\n   - تابع `sanitizeAuditRecordsMap`: در هنگام بارگذاری داده‌ها از حافظه، تمام یادداشت‌های سیستمی خودکار قبلی (`⚠️ نیازمند بررسی: تشابه نام با...`) را از فیلد `notes` کتاب‌ها پاک می‌کند و اگر کتابی توسط کارشناس `verified` شده باشد، پرچم `needsReview` آن را `false` نگه می‌دارد.\n   - تابع `sanitizeSmartSuggestionsList`: پیشنهادهای صف بررسی را که در آن‌ها نام شهید صرفاً در نام ناشر آمده و در عنوان یا توضیحات واقعی کتاب وجود ندارد، به‌طور خودکار پالایش و حذف می‌کند.\n   - تابع `mergeLinksPreservingApprovals`: تضمین می‌کند پیوندهایی که کارشناس وضعیت آن‌ها را `تأییدشده کارشناسی` یا `قطعی` قرار داده است، در هیچ بارگذاری یا همگام‌سازی مجددی به وضعیت `بررسی‌نشده` یا `نیازمند بررسی` بازنگردند.\n\n---\n\n### فاز ۵: ارتقای موتور خروجی ۵ برگه Excel با فیلتر و ستون «وضعیت شهید تهرانی»، الگوی ۶ موضوع اصلی و فونت ۱۰۰٪ یکپارچه `Vazirmatn`\n\nدر ماژول `src/modules/excel-export/` (`types.ts`، `fieldCatalog.ts`، `excelBuilderEngine.ts` و `ExcelExportConfigModal.tsx`) قابلیت‌های زیر تکمیل و تثبیت شد:\n\n1. **فیلتر و ستون اختصاصی «وضعیت شهید تهرانی (گلزار شهدای تهران)»:**\n   - افزودن چک‌باکس **`فقط کتاب‌ها و شهدای تهرانی (منطبق با ۲۸٬۳۶۸ شهید گلزار شهدای تهران)`** (`onlyTehranMartyrs`) در بالای پنجره تنظیمات خروجی Excel.\n   - افزودن فیلد رسمی `tehran_martyr_status` (**«وضعیت شهید تهرانی (گلزار شهدای تهران)»**) به کاتالوگ فیلدها و درج آن در هر ۵ برگه خروجی (`۱-فهرست اصلی کتاب‌ها`، `۲-ارتباط کتاب و شهید`، `۳-موضوعات و صفحات مرتبط`، `۴-متن‌های استخراج‌شده` و `۵-اطلاعات شهدای مرتبط`).\n2. **الگوی آماده شماره ۱ — «۱. گزارش بر اساس ۶ عنوان موضوعی کتاب‌ها (R، P، H، A، K، M)»:**\n   - قرار گرفتن این الگو در صدر «۱. الگوهای آماده گزارش‌گیری سریع» به همراه چک‌باکس‌های مستقل برای هر ۶ موضوع (`R — روایت و خاطرات`، `P — پژوهش و تحلیل`، `H — تاریخ و اسناد`، `A — ادبیات و هنر`، `K — کودک و نوجوان`، `M — متفرقه`) و نمایش شمارنده زنده تعداد کتاب‌های هر موضوع.\n   - امکان تیک‌زدن تک‌تک موضوعات یا استفاده از دکمه‌های **«✓ انتخاب همه ۶ موضوع»** و **«حذف تیک موضوعات»**.\n3. **اختیاری‌سازی جهت گزارش و اصلاح کامل دکمه «✕ حذف انتخاب‌ها»:**\n   - دکمه‌های «از کتاب به شهید» و «از شهید به کتاب» به‌صورت اختیاری (`direction: null` در حالت پیش‌فرض) عمل می‌کنند و با کلیک مجدد، انتخاب آن‌ها برداشته می‌شود.\n   - دکمه **«✕ حذف انتخاب‌ها»** تمام الگوها، تیک‌های ۶ موضوع، فیلتر شهدای تهرانی، جهت گزارش، هر ۵ برگه (`۰ برگه`) و هر ۴۵ فیلد (`۰ فیلد`) را به طور کامل صفر می‌کند.\n4. **یکپارچه‌سازی ۱۰۰٪ فونت `Vazirmatn` در تمامی برگه‌ها و سلول‌های فایل خام `.xlsx`:**\n   - تعریف `EXCEL_VAZIRMATN_THEME_XML` و `createUnifiedWorksheetStyles()` با کدهای رنگ ۸ کاراکتری استاندارد ARGB (`FF6B3E26`، `FFF5E6D3`، `FF1E4D2B`، `FFFFFFFF`، `FFFAF6EE`) جهت جلوگیری از باگ تغییر درجا (`In-place Mutation`) در کتابخانه `xlsx-js-style` و تضمین ۱۰۰٪ فونت `Vazirmatn` در هر ۵ برگه (`۰` سلول `B Zar` و `۰` سلول `Calibri`).\n\n---\n\n### فاز ۶: ایمن‌سازی چرخه Preview تا Apply، ادغام دوطرفه گوشی و رایانه و پنل اشتراک‌گذاری پیام‌رسان‌ها در انتقال JSON\n\nدر ماژول `src/modules/json-system-transfer/` (`jsonTransferEngine.ts` و `JsonSystemTransferSection.tsx`) و `src/components/ModalWindow.tsx`:\n\n1. **قفل اثرانگشت وضعیت مقصد (`DEST_FP_SHA256_...`) بین Preview و Apply:**\n   - حذف کامل Fallback به وضعیت قدیمی حافظه در صورت خطای خواندن از Storage و محاسبه اثرانگشت قطعی وضعیت مقصد در لحظه پیش‌نمایش؛ در صورت تغییر داده‌های دستگاه پیش از کلیک روی «تأیید و اجرای ادغام»، عملیات متوقف شده و از بازنویسی ناخواسته جلوگیری می‌شود.\n2. **حل برخورد شناسه `LOG-xxxx` در `auditLog` و ادغام سه‌طرفه سطح فیلد (`3-Way Field-Level Merge`):**\n   - در هنگام همگام‌سازی دوطرفه گوشی و رایانه، رویدادهای `auditLog` که دارای شناسه سریال یکسان ولی محتوای متفاوت هستند، با شناسه جدید (`LOG-${nextSeq}__IMP_...`) حفظ می‌شوند تا هیچ سابقه‌ای از بین نرود.\n   - تغییرات غیرمتعارض روی فیلدهای مختلف یک کتاب در دو دستگاه، به صورت فیلدبه‌فیلد ترکیب می‌شوند.\n3. **رفع قطعی خطای `Permission denied` هنگام اشتراک‌گذاری فایل JSON:**\n   - در صورت مسدود شدن `navigator.share` برای فایل‌های `.json` توسط مرورگر، به جای نمایش خطای قرمز `Permission denied`، مشخصات فایل در کلیپ‌بورد کپی شده و **«پنل ارسال فایل JSON در پیام‌رسان‌ها (ایتا، بله، روبیکا، تلگرام، واتساپ و ایمیل)»** به طور خودکار باز می‌شود.\n4. **رفع بیرون‌زدگی کد یکتای صحت داده (`SHA256_...`) در پنجره خلاصه خروجی JSON:**\n   - اختصاص سطر کامل (`sm:col-span-2`) با کلاس‌های `min-w-0 overflow-hidden break-all` به «نام فایل» و «کد یکتای صحت داده» و افزودن `overflow-x-hidden` به `ModalWindow.tsx` تا هیچ متنی از کادر پنجره بیرون نزند.\n\n---\n\n### فاز ۷: بهینه‌سازی سرعت رابط کاربری (`0ms Search Lag`) و کش‌زدایی هوشمند نسخه موبایل (`Cache Busting v12`)\n\n1. **پیش‌محاسبه نگاشت جست‌وجو و کش‌های $O(1)$:**\n   - در `QuickInventoryTab.tsx`، ساختار `precomputedSearchMap` تمامی متن‌های نرمال‌شده کتاب، نویسنده، ناشر، شهدای مرتبط و وضعیت «شهدای تهرانی» را یک‌بار پیش‌محاسبه می‌کند تا تایپ در کادر جست‌وجوی کتابخانه بدون کوچک‌ترین مکث انجام شود.\n   - در `martyrsCrossMatchEngine.ts`، سه لایه کش درون‌حافظه‌ای (`evaluationCache`، `bookExtractCache` و `lastEnrichedLinksCache`) از تکرار پردازش‌های متنی در رندرهای React جلوگیری می‌کنند.\n2. **ارتقای نسخه ساخت و کش سرویس‌ورکر در `index.html` (`2026-11-11-v12`):**\n   - ارتقای `BUILD_VER = '2026-11-11-v12'` و `ACTIVE_CACHE = 'markaz-asnad-main-book-v12'` در `index.html` به همراه تابع `verifyLatestServerBundle()` که در پس‌زمینه هش باندل سرور را بررسی کرده و در صورت وجود نسخه جدید در GitHub Pages، کش‌های قدیمی اسکریپت را پاک و صفحه را یک‌بار بازخوانی می‌کند (بدون دست زدن به داده‌های ذخیره‌شده کاربر در `IndexedDB` و `localStorage`).\n\n---\n\n## فهرست فایل‌های کلیدی ایجاد یا به‌روزرسانی‌شده و نتایج آزمون‌ها\n\n### ۱. جدول فایل‌های کلیدی\n| ردیف | مسیر فایل در مخزن | شرح فنی اقدامات انجام‌شده |\n| :---: | :--- | :--- |\n| ۱ | `src/utils/martyrsCrossMatchEngine.ts` | موتور نمایه‌سازی ۲۸٬۳۶۸ شهید گلزار تهران، جداول هش $O(1)$، کش دائمی یک‌بارمصرف (`book_tehran_determined_index_v2`)، قانون استثنای شهدای غیرتهرانی (`غ تهرانی`)، تشخیص تشابه اسمی و حذف نام ناشر (`stripPublisherAndAutoNotesForMartyrMatch`) |\n| ۲ | `src/components/TehranMartyrBadge.tsx` | کامپوننت نشان کپسولی قرمزرنگ «تهرانی» (`#B91C1C`) در سه اندازه `xs`، `sm` و `md` |\n| ۳ | `src/App.tsx` | اتصال نمایه سراسری ۲۸٬۳۶۸ شهید به `indexedLinks`، پاک‌سازی خودکار یادداشت‌های کاذب نام ناشر (`sanitizeAuditRecordsMap` و `sanitizeSmartSuggestionsList`) و حفاظت قطعی از تأییدهای کارشناس (`mergeLinksPreservingApprovals`) |\n| ۴ | `src/data/soorehMehrResearch.ts` | افزودن فیلدهای `isTehranMartyr` و `hasTehranMartyr` به ساختار `UnifiedBookDossier` و ارتباطات شهید در پرونده یکپارچه کتاب |\n| ۵ | `src/components/HomeDashboardTab.tsx` | نمایش نشان «تهرانی» در کارت‌ها و پرونده یکپارچه کتاب و شهید، و افزودن فیلتر `شهدای تهرانی (گلزار تهران)` در پنجره‌های آماری |\n| ۶ | `src/components/QuickInventoryTab.tsx` | پیش‌محاسبه `precomputedSearchMap` برای جست‌وجوی آنی، نمایش نشان «تهرانی» کنار کتاب‌ها و شهدای مرتبط، و افزودن فیلتر «۲. کتاب‌های شهدای تهرانی» با شمارنده زنده |\n| ۷ | `src/components/AllMartyrsDatabaseTab.tsx` | نمایش نشان «تهرانی» در بانک ۲۸٬۳۶۸ شهید، کارت‌ها، پنجره جزئیات پرونده و مودال اتصال کتاب |\n| ۸ | `src/components/SmartBookSearchTab.tsx` | حذف نام ناشر از متن تطبیق خودکار و نمایش نشان «تهرانی» در نتایج جست‌وجو و صف بررسی کارشناس |\n| ۹ | `src/components/ResearchAndLinksTab.tsx` | نمایش نشان «تهرانی» در جداول ارتباط کتاب و شهید و افزودن فیلتر `شهدای تهرانی (منطبق با گلزار شهدای تهران)` |\n| ۱۰ | `src/components/DepositoryAndExportHub.tsx` | نمایش نشان «تهرانی» در نمای کتاب‌محور و شهیدمحور و افزودن فیلتر `فقط شهدای تهرانی — گلزار شهدای تهران` |\n| ۱۱ | `src/modules/excel-export/types.ts` | تعریف ۶ کد موضوعی اصلی (`R, P, H, A, K, M`)، فیلدهای `isTehranMartyr`، `tehranStatusLabel` و `onlyTehranMartyrs` و اختیاری‌سازی `direction` |\n| ۱۲ | `src/modules/excel-export/fieldCatalog.ts` | افزودن ستون `tehran_martyr_status` و قرار دادن الگوی «۱. گزارش بر اساس ۶ عنوان موضوعی کتاب‌ها (R، P، H، A، K، M)» در صدر الگوهای آماده |\n| ۱۳ | `src/modules/excel-export/excelBuilderEngine.ts` | یکپارچه‌سازی ۱۰۰٪ فونت `Vazirmatn` در هر ۵ برگه، اعمال فیلتر ۶ موضوع اصلی و فیلتر `onlyTehranMartyrs` و درج ستون وضعیت شهید تهرانی |\n| ۱۴ | `src/modules/excel-export/ExcelExportConfigModal.tsx` | افزودن چک‌باکس «فقط کتاب‌ها و شهدای تهرانی»، چک‌باکس‌های تعاملی ۶ موضوع اصلی، اختیاری‌سازی دکمه‌های جهت گزارش و اصلاح دکمه «✕ حذف انتخاب‌ها» |\n| ۱۵ | `src/modules/json-system-transfer/jsonTransferEngine.ts` | قفل اثرانگشت مقصد (`DEST_FP_SHA256_...`)، حل برخورد شناسه `LOG-xxxx` در ادغام دوطرفه، و مدیریت هوشمند `shareJsonFileIfSupported` |\n| ۱۶ | `src/modules/json-system-transfer/JsonSystemTransferSection.tsx` | افزودن پنل ارسال فایل JSON در پیام‌رسان‌ها (ایتا، بله، روبیکا، تلگرام، واتساپ، ایمیل) و اصلاح چیدمان کادر خلاصه خروجی JSON |\n| ۱۷ | `src/components/ModalWindow.tsx` | افزودن `overflow-x-hidden` به بدنه مودال برای جلوگیری از هرگونه بیرون‌زدگی افقی |\n| ۱۸ | `index.html` | ارتقای نسخه کش به `2026-11-11-v12` و بررسی خودکار آخرین باندل سرور جهت به‌روزرسانی بدون کش در موبایل |\n\n### ۲. نتایج آزمون‌های فنی و کامپایل نهایی\n- **بررسی ایستای کد و تایپ‌ها (`npm run lint` / `tsc --noEmit`):** موفق (`Exit Code: 0`) — ۰ خطا.\n- **کامپایل و ساخت نسخه نهایی (`npm run build` / `compile_applet`):** موفق (`Exit Code: 0`) — ساخت کامل باندل Production.\n- **آزمون ۱۷گانه بازیابی، Rollback و همگام‌سازی JSON (`restoreRollbackVerification.test.ts`):** تمامی ۱۷ سناریو `PASS`.\n- **آزمون یکپارچگی فونت خروجی Excel:** ۱۰۰٪ سلول‌های هر ۵ برگه دارای فونت `Vazirmatn` (`۰` سلول `B Zar` و `۰` سلول `Calibri`).\n- **آزمون دقت تطبیق شهدای تهرانی و عدم تداخل نام ناشر:**\n  - شهدای دارای قید `غ تهرانی` / `غیر تهرانی`: `۰` مورد نشان کاذب «تهرانی» (۱۰۰٪ دقیق).\n  - کتاب‌های «انتشارات شهید ابراهیم هادی» که درباره شهید دیگری هستند: `۰` مورد انتساب کاذب به شهید ابراهیم هادی.\n\n---\n**مرکز اسناد و تحقیقات گلزار شهدای تهران**  \n*گزارش فنی جامع عملکرد روزانه — ثبت‌شده در مخزن رسمی پروژه (`https://github.com/forog1980-star/book`)*\n";
function cleanExecutiveDoc(raw) {
  const lines = raw.replace(/\r\n/g, "\n").split("\n");
  const cleaned = [];
  let skippingPs = true;
  for (const line of lines) {
    if (line.includes("================ FILE:")) {
      skippingPs = false;
      const fileMatch = line.match(/================ FILE:\s*\\?(.+?)\s*================/);
      const fileName = fileMatch ? fileMatch[1].replace(/\\/g, " / ") : "بخش اجرایی";
      cleaned.push("\n\n# " + fileName + "\n");
      continue;
    }
    if (skippingPs && (line.startsWith("PS ") || line.startsWith(">>") || !line.trim())) {
      continue;
    }
    skippingPs = false;
    cleaned.push(line);
  }
  return cleaned.join("\n");
}
